//--------------------------------------------------------------
void ofApp::drawMinionStatusBars(Player & minion, const std::string & name, float x, float y, float totalWidth) {
	float scale = ofGetHeight() / 1080.0f;
	float fontScale = 0.9f;

	// 1. Main Stats Bar
	float barHeight = 20 * scale;
	ofRectangle nameBounds = uiFont.getStringBoundingBox(name, 0, 0);
	float barY = y + (nameBounds.height * fontScale) + (4 * scale);

	float statW = totalWidth * 0.20f;
	float usedWidth = 0;

	// --- FIX: Add holyBlock to width calculation ---
	if (minion.block > 0) usedWidth += statW;
	if (minion.fortification > 0) usedWidth += statW;
	if (minion.barrier > 0) usedWidth += statW;
	if (minion.holyBlock > 0) usedWidth += statW; // <--- ADDED
	if (minion.ward > 0) usedWidth += statW;

	float hpW = totalWidth - usedWidth;
	float currentX = x;

	// --- HEALTH ---
	ofSetColor(40, 0, 0);
	ofDrawRectangle(currentX, barY, hpW, barHeight);
	float hpPct = (float)minion.health / minion.maxHealth;
	ofSetColor(ofColor::green);
	ofDrawRectangle(currentX, barY, hpW * hpPct, barHeight);
	string hpText = ofToString(minion.health) + "/" + ofToString(minion.maxHealth);
	drawStatText(uiFont, hpText, currentX, barY, hpW, barHeight, ofColor::white);
	currentX += hpW;

	// --- SHIELDS (With Tooltips) ---
	auto drawMinionSeg = [&](int val, ofColor c, string label) {
		if (val > 0) {
			ofSetColor(c);
			ofDrawRectangle(currentX, barY, statW, barHeight);
			drawStatText(uiFont, ofToString(val), currentX, barY, statW, barHeight, (c.getBrightness() > 200 ? ofColor::black : ofColor::white));

			// Tooltip Check
			if (ofRectangle(currentX, barY, statW, barHeight).inside(ofGetMouseX(), ofGetMouseY())) {
				isShowingTooltip = true;
				tooltipPos = { (float)ofGetMouseX(), (float)ofGetMouseY() };
				tooltipText = label;
			}
			currentX += statW;
		}
	};

	drawMinionSeg(minion.block, ofColor::gray, "Block (Physical)");
	drawMinionSeg(minion.fortification, ofColor(50, 50, 50), "Fortification (Phys/Pierce)");
	drawMinionSeg(minion.barrier, ofColor::hotPink, "Barrier (Non-Physical)");

	// --- FIX: Add Holy Block Drawing ---
	drawMinionSeg(minion.holyBlock, ofColor::yellow, "Holy Block (Holy)"); // <--- ADDED

	drawMinionSeg(minion.ward, ofColor::black, "Ward (All Damage)");

	// --- FORM BARS ---
	if (minion.inTortoiseForm || minion.inGhostForm) {
		float formY = barY + barHeight + (2 * scale);
		float formHeight = 15 * scale;

		if (minion.inTortoiseForm) {
			int rem = 5 - minion.tortoiseDamageTaken;
			ofSetColor(20, 40, 20);
			ofDrawRectangle(x, formY, totalWidth, formHeight);
			ofSetColor(ofColor::darkGreen);
			ofDrawRectangle(x, formY, totalWidth * (rem / 5.0f), formHeight);
			drawStatText(uiFont, "Tortoise: " + ofToString(rem) + "/5", x, formY, totalWidth, formHeight, ofColor::white);

			// Tooltip
			if (ofRectangle(x, formY, totalWidth, formHeight).inside(ofGetMouseX(), ofGetMouseY())) {
				isShowingTooltip = true;
				tooltipPos = { (float)ofGetMouseX(), (float)ofGetMouseY() };
				tooltipText = "Tortoise Form: Buffer HP";
			}

			// Stack next bar if needed
			formY += formHeight + (2 * scale);
		}

		if (minion.inGhostForm) {
			int rem = 4 - minion.ghostDamageTaken;
			ofSetColor(30, 30, 50);
			ofDrawRectangle(x, formY, totalWidth, formHeight);
			ofSetColor(150, 150, 255);
			ofDrawRectangle(x, formY, totalWidth * (rem / 4.0f), formHeight);
			drawStatText(uiFont, "Ghost: " + ofToString(rem) + "/4", x, formY, totalWidth, formHeight, ofColor::black);

			// Tooltip
			if (ofRectangle(x, formY, totalWidth, formHeight).inside(ofGetMouseX(), ofGetMouseY())) {
				isShowingTooltip = true;
				tooltipPos = { (float)ofGetMouseX(), (float)ofGetMouseY() };
				tooltipText = "Ghost Form: Immune to Physical/Piercing";
			}
		}
	}
}
//--------------------------------------------------------------
void ofApp::drawMinionManagerUI() {
	if (activeMinionUIs.empty()) return;

	float scale = ofGetHeight() / 1080.0f;
	float sfX = (float)ofGetViewportWidth() / ofGetWidth();
	float sfY = (float)ofGetViewportHeight() / ofGetHeight();

	for (size_t i = 0; i < activeMinionUIs.size(); i++) {
		auto & ui = activeMinionUIs[i];
		Player & minion = players[ui.playerIndex];

		bool isLeft = ui.bounds.x < ofGetWidth() / 2.0f;
		float topY = isLeft ? p0_minionTop : p1_minionTop;
		float viewH = isLeft ? p0_minionViewH : p1_minionViewH;

		// Skip if completely out of view bounds vertically
		if (ui.bounds.getBottom() < topY || ui.bounds.y > topY + viewH) continue;

		// --- Render Model to FBO ---
		modelFbo.begin();
		ofClear(0, 0, 0, 0);
		ofEnableDepthTest();
		ofDisableLighting();
		uiLight.disable();
		ofSetColor(255);

		ofPushMatrix();

		// --- TORTOISE FORM PREVIEW (overrides normal model) ---
		if (minion.inTortoiseForm) {
			ofTranslate(modelFbo.getWidth() / 2, modelFbo.getHeight() / 2 + 10);
			ofScale(21, -21, 21);
			ofRotateXDeg(-15);
			ofRotateYDeg(180 + ofGetElapsedTimef() * 30);
			if (tortoiseTexture.isAllocated()) tortoiseTexture.bind();
			tortoiseModel.drawFaces();
			if (tortoiseTexture.isAllocated()) tortoiseTexture.unbind();
		} else if (minion.isGolem) {
			// GOLEM: Raised position (100 -> 80)
			ofTranslate(modelFbo.getWidth() / 2, 80);
			ofScale(27, 27, 27);
			ofRotateXDeg(-15);
			ofRotateYDeg(ofGetElapsedTimef() * 30);
			if (minion.minionTexture) minion.minionTexture->bind();
			golemModel.drawFaces();
			if (minion.minionTexture) minion.minionTexture->unbind();

		} else if (minion.isWolf) {
			// WOLF: Decreased scale by 50% (2.2 -> 1.1), Lowered position (+10 -> +30)
			ofTranslate(modelFbo.getWidth() / 2, modelFbo.getHeight() / 2 + 30);
			ofScale(1.1f, -1.1f, 1.1f);

			ofRotateXDeg(-15);
			ofRotateYDeg(180 + ofGetElapsedTimef() * 30);

			// Draw skin meshes
			for (unsigned int i = 6; i < wolfModel.getMeshCount(); i++) {
				ofTexture * tex = (i == 6 || i == 7) ? &wolfBodyTex : &wolfFaceTex;
				if (tex->isAllocated()) tex->bind();
				wolfModel.getMeshHelper(i).cachedMesh.drawFaces();
				if (tex->isAllocated()) tex->unbind();
			}

			// Draw fur
			glDepthMask(GL_FALSE);
			ofEnableAlphaBlending();
			wolfFurTex.bind();
			for (unsigned int i = 0; i <= 5; i++) {
				wolfModel.getMeshHelper(i).cachedMesh.drawFaces();
			}
			wolfFurTex.unbind();
			ofDisableAlphaBlending();
			glDepthMask(GL_TRUE);

		}
		// --- KOBOLD KING PREVIEW ---
		else if (minion.isKoboldKing) {
			ofTranslate(modelFbo.getWidth() / 2, modelFbo.getHeight() / 2 + 30);

			// Reduced from 30.0f to 2.5f (since model is now 0.0042f)
			ofScale(2.5f, -2.5f, 2.5f);

			ofRotateXDeg(-15);
			ofRotateYDeg(180 + ofGetElapsedTimef() * 30);

			// CORRECTION HERE TOO if needed in UI
			ofRotateYDeg(-90);

			ofSetColor(255);
			if (koboldKingTexture.isAllocated()) koboldKingTexture.bind();
			koboldKingModel.drawFaces();
			if (koboldKingTexture.isAllocated()) koboldKingTexture.unbind();
		}
		// --- KOBOLD PREVIEW ---
		else if (minion.isKobold) {
			ofTranslate(modelFbo.getWidth() / 2, modelFbo.getHeight() / 2 + 30);
			// Preview scale reduced by ~30%
			ofScale(4.55f, -4.55f, 4.55f);
			ofRotateXDeg(-15);
			ofRotateYDeg(180 + ofGetElapsedTimef() * 30);
			koboldModel.drawFaces();
		}
		// --- HELLHOUND PREVIEW ---
		else if (minion.isHellhound) {
			ofTranslate(modelFbo.getWidth() / 2, modelFbo.getHeight() / 2 + 10);

			// HELLHOUND: Increased scale (18 -> 22)
			ofScale(22, -22, 22);

			ofRotateXDeg(-15);
			ofRotateYDeg(180 + ofGetElapsedTimef() * 30);
			hellhoundModel.drawFaces();
		}
		// --- DEMON PREVIEW ---
		else if (minion.isDemon) {
			ofTranslate(modelFbo.getWidth() / 2, modelFbo.getHeight() / 2 + 10);
			// DEMON: Increased scale (12 -> 16)
			ofScale(16, -16, 16);
			ofRotateXDeg(-15);
			ofRotateYDeg(180 + ofGetElapsedTimef() * 30);
			demonModel.drawFaces();
		}
		// --- WALL PREVIEW ---
		else if (minion.isWallUnit) {
			ofTranslate(modelFbo.getWidth() / 2, modelFbo.getHeight() / 2 + 10);
			// Reasonable preview scale for wall unit (tweakable)
			ofScale(6.0f, -6.0f, 6.0f);
			ofRotateXDeg(-15);
			ofRotateYDeg(180 + ofGetElapsedTimef() * 30);
			if (minion.minionTexture && minion.minionTexture->isAllocated()) minion.minionTexture->bind();
			wallUnitModel.drawFaces();
			if (minion.minionTexture && minion.minionTexture->isAllocated()) minion.minionTexture->unbind();

			// If this wall unit was created from a Magic Wall, draw a mesh-based purple glow
			if (minion.isMagicWallUnit) {
				ofEnableBlendMode(OF_BLENDMODE_ADD);
				ofSetColor(148, 0, 211, 120);
				glEnable(GL_POLYGON_OFFSET_FILL);
				glPolygonOffset(-1.0f, -1.0f);
				ofPushMatrix();
				// Draw at the preview model's scale so the glow matches the mesh
				// Draw the whole preview model again in purple so the glow follows model curves exactly
				wallUnitModel.drawFaces();
				ofPopMatrix();
				glDisable(GL_POLYGON_OFFSET_FILL);
				ofSetColor(255);
				ofDisableBlendMode();
			}
		}
		// --- ASSISTANT PREVIEW ---
		else if (minion.isAssistant) {
			ofTranslate(modelFbo.getWidth() / 2, modelFbo.getHeight() / 2 + 20);
			ofScale(35.0f, -35.0f, 35.0f);
			ofRotateXDeg(-15);
			ofRotateYDeg(180 + ofGetElapsedTimef() * 30);
			assistantModel.drawFaces();
		}
		// --- FAERIE PREVIEW ---
		else if (minion.isFaerie) {
			ofTranslate(modelFbo.getWidth() / 2, modelFbo.getHeight() / 2 + 20);
			// Faerie is likely small, so scale up slightly more than standard units
			ofScale(30.0f, -30.0f, 30.0f);
			ofRotateXDeg(-15);
			ofRotateYDeg(180 + ofGetElapsedTimef() * 30);
			if (faerieTexture.isAllocated()) faerieTexture.bind();
			faerieModel.drawFaces();
			if (faerieTexture.isAllocated()) faerieTexture.unbind();
		}
		// --- SKELETON PREVIEW --- Default
		else {
			ofSetColor(255);
			ofTranslate(modelFbo.getWidth() / 2, 90);
			// SKELETON: Increased scale by 20% (18 -> 22)
			ofScale(22, -22, 22);
			ofRotateXDeg(-15);
			ofRotateYDeg(ofGetElapsedTimef() * 30);
			skeletonTexture.bind();
			skeletonModel.drawFaces();
			skeletonTexture.unbind();
		}

		ofPopMatrix();
		ofDisableDepthTest();
		modelFbo.end();

		// Setup Scissor clipping to hide overflowing elements
		glEnable(GL_SCISSOR_TEST);
		int scX = (int)((isLeft ? p0_minionLeft - 30 : p1_minionLeft - 30) * sfX);
		int scW = (int)((minionPanelW + 60) * sfX);
		int scY = (int)((ofGetHeight() - (topY + viewH)) * sfY);
		int scH = (int)(viewH * sfY);
		glScissor(scX, scY, scW, scH);

		// --- Draw UI Panel ---
		ofPushStyle();
		ofEnableAlphaBlending();
		ofSetColor(0, 0, 0, 150);
		ofDrawRectRounded(ui.bounds, 10 * scale);
		ofPopStyle();

		// New Visual Outlines for Active and Hovered states
		bool isActive = (currentPlayerIndex == ui.playerIndex);
		bool isHovered = (hoveredUnitIndex == ui.playerIndex);

		if (isActive) {
			ofPushStyle();
			// Yellow outline for minions, white for players
			ofColor outlineColor = players[ui.playerIndex].isMinion ? ofColor::yellow : ofColor::white;
			// Draw glow background to ensure outline is fully visible
			ofSetColor(outlineColor.r, outlineColor.g, outlineColor.b, 80);
			float glow = 4.0f * scale;
			ofDrawRectRounded(ui.bounds.x - glow, ui.bounds.y - glow,
				ui.bounds.width + glow * 2.0f, ui.bounds.height + glow * 2.0f,
				(10 * scale) + glow);
			// Draw crisp outline on top
			ofNoFill();
			ofSetColor(outlineColor);
			ofSetLineWidth(3 * scale);
			ofDrawRectRounded(ui.bounds, 10 * scale);
			ofPopStyle();
		}

		if (isHovered && !isActive) {
			// Only show white outline when hovering (if not already active)
			ofPushStyle();
			ofNoFill();
			ofSetColor(ofColor::white);
			ofSetLineWidth(3 * scale);
			ofDrawRectRounded(ui.bounds, 10 * scale);
			ofPopStyle();
		}

		// --- DETERMINE NAME ---
		string name = "";
		if (minion.isGolem) {
			if (minion.minionTexture == &golemTexElectric)
				name = "Electric Golem ";
			else if (minion.minionTexture == &golemTexFire)
				name = "Fire Golem ";
			else if (minion.minionTexture == &golemTexRock)
				name = "Rock Golem ";
			else
				name = "Golem ";
		} else if (minion.isWolf) {
			name = "Wolf ";
		} else if (minion.isHellhound) {
			name = "Hellhound ";
		} else if (minion.isDemon) {
			name = "Demon ";
		} else if (minion.isKoboldKing) {
			name = "Kobold King ";
		} else if (minion.isKobold) {

			name = "Kobold ";
		} else if (minion.isWallUnit) {
			if (minion.isMagicWallUnit)
				name = "Magic Wall ";
			else
				name = "Wall ";
		} else if (minion.isAssistant) {
			name = "Assistant ";
		} else if (minion.isFaerie) {
			name = "Faerie ";
		} else {
			name = "Skeleton ";
		}
		name += ofToString(ui.displayNumber);

		// --- Draw Name Text ---
		float fontScale = 0.9f;
		float textBlockX = ui.bounds.x + 10 * scale;
		float textBlockY = ui.bounds.y + 5 * scale;
		ofRectangle nameBounds = uiFont.getStringBoundingBox(name, 0, 0);

		ofPushMatrix();
		ofTranslate(textBlockX, textBlockY + nameBounds.height * fontScale);
		ofScale(fontScale, fontScale);
		ofSetColor(ofColor::white);
		uiFont.drawString(name, 0, 0);
		ofPopMatrix();

		// (Minion luck/status moved to hover tooltip; no inline luck shown here)
		//
		// --- Draw Model FBO ---
		float textBlockBottom = textBlockY + (nameBounds.height * fontScale) + (25 * scale);
		float modelAreaHeight = ui.bounds.getBottom() - textBlockBottom - (5 * scale);

		ui.modelViewport.set(
			textBlockX + 15 * scale,
			textBlockBottom,
			modelAreaHeight,
			modelAreaHeight);
		ofSetColor(255);
		modelFbo.draw(ui.modelViewport);

		// --- Draw Icons ---
		float iconMargin = 8 * scale;
		float iconHeight = ui.bounds.height - (iconMargin * 2);
		float cardAspectRatio = cardBackImage.getWidth() / cardBackImage.getHeight();
		float iconWidth = iconHeight * cardAspectRatio;
		float iconsY = ui.bounds.y + iconMargin;

		ui.discardRect.set(ui.bounds.getRight() - (iconWidth + iconMargin), iconsY, iconWidth, iconHeight);
		ui.deckRect.set(ui.bounds.getRight() - (iconWidth * 2 + iconMargin + 5 * scale), iconsY, iconWidth, iconHeight);

		// --- Status Bars ---
		float availableWidth = ui.deckRect.x - textBlockX - (15 * scale);
		drawMinionStatusBars(minion, name, textBlockX, textBlockY, availableWidth);

		// Deck
		ofSetColor(255);
		if (!minion.deck.empty()) {
			cardBackImage.draw(ui.deckRect);
		} else {
			ofSetColor(20, 20, 20, 200);
			ofDrawRectRounded(ui.deckRect, 3);
		}
		if (ui.playerIndex == currentPlayerIndex && !players[ui.playerIndex].hasDrawnThisTurn) {
			ofPushStyle();
			ofNoFill();
			ofSetColor(ofColor::green);
			ofSetLineWidth(3 * scale);
			ofDrawRectRounded(ui.deckRect, 5);
			ofPopStyle();
		}

		// Discard
		if (!minion.discardPile.empty()) {
			cardSpriteSheet.getTexture().drawSubsection(ui.discardRect, minion.discardPile.back().textureRect);
		} else {
			ofSetColor(20, 20, 20, 200);
			ofDrawRectRounded(ui.discardRect, 3);
		}

		// (Minion status effects are shown only in the hover tooltip above the unit)
		glDisable(GL_SCISSOR_TEST);
	} // End of loop

	// --- Draw Scrollbars ---
	auto drawScrollbar = [&](float startX, float panelW, float topY, float viewH, float totalH, float scroll) {
		if (totalH <= viewH) return;
		float scrollbarW = 6.0f * scale;
		float scrollbarX = 0.0f;
		// Place scrollbar on the inner side for left panels, and on the outer edge for right panels
		if (startX + panelW * 0.5f < ofGetWidth() * 0.5f) {
			// left-side panel: scrollbar on the left of the panel
			scrollbarX = startX - scrollbarW - 8.0f * scale;
		} else {
			// right-side panel: place scrollbar on the right edge of the panel
			scrollbarX = startX + panelW + 8.0f * scale;
		}

		// Background Track
		ofSetColor(30, 30, 30, 200);
		ofDrawRectRounded(scrollbarX, topY, scrollbarW, viewH, scrollbarW / 2);

		// Movable Handle
		float handleH = std::max(20.0f * scale, (viewH / totalH) * viewH);
		float handleY = topY + (scroll / (totalH - viewH)) * (viewH - handleH);
		ofSetColor(150, 150, 150, 255);
		ofDrawRectRounded(scrollbarX, handleY, scrollbarW, handleH, scrollbarW / 2);
	};

	drawScrollbar(p0_minionLeft, minionPanelW, p0_minionTop, p0_minionViewH, p0_minionTotalH, p0_minionScroll);
	drawScrollbar(p1_minionLeft, minionPanelW, p1_minionTop, p1_minionViewH, p1_minionTotalH, p1_minionScroll);
}
//--------------------------------------------------------------
void ofApp::cancelMagicHand() {
	isMagicHandMenuOpen = false;
	pendingMagicHandCardIndex = -1;
}

void ofApp::resolveMagicHandPull() {
	Player & caster = players[currentPlayerIndex];
	glm::ivec2 wallPos = magicHandTargetTile;
	glm::ivec2 casterPos = { caster.x, caster.y };

	// Direction from Caster -> Wall
	glm::ivec2 dir = wallPos - casterPos;

	// Position BEHIND caster
	glm::ivec2 backPos = casterPos - dir;

	// Check bounds and occupancy for backPos
	bool isValid = true;
	if (backPos.x < 0 || backPos.x >= BOARD_WIDTH || backPos.y < 0 || backPos.y >= BOARD_HEIGHT)
		isValid = false;
	else if (board[backPos.x][backPos.y].hasWall || board[backPos.x][backPos.y].hasPlayer)
		isValid = false;

	if (!isValid) {
		spawnFloatingText(gridToWorld(caster.x, caster.y), "Blocked Behind!", ofColor::red);
		return; // Don't close menu, allow retry or cancel
	}

	// Execute Pull
	// 1. Move Caster to BackPos
	board[caster.x][caster.y].hasPlayer = false;
	caster.x = backPos.x;
	caster.y = backPos.y;
	board[caster.x][caster.y].hasPlayer = true;
	playerVisualPos = gridToWorld(caster.x, caster.y);

	// 2. Move Wall to Caster's Old Pos
	board[wallPos.x][wallPos.y].hasWall = false;
	board[casterPos.x][casterPos.y].hasWall = true;
	if (board[wallPos.x][wallPos.y].isMagicWall) {
		board[casterPos.x][casterPos.y].isMagicWall = true;
		board[wallPos.x][wallPos.y].isMagicWall = false;
	}

	// 3. Finalize
	buildLevelMesh();

	currentAP -= players[currentPlayerIndex].hand[pendingMagicHandCardIndex].cost;
	players[currentPlayerIndex].playedCardsPile.push_back(players[currentPlayerIndex].hand[pendingMagicHandCardIndex]);
	players[currentPlayerIndex].hand.erase(players[currentPlayerIndex].hand.begin() + pendingMagicHandCardIndex);

	// Notify opponent after local update so pkt.updatedAP contains the post-play AP
	sendMagicHandResolutionPacket(2);

	// Cleanup
	pendingMagicHandCardIndex = -1;
	isMagicHandMenuOpen = false;
	invalidateTargetCache();
}

void ofApp::resolveMagicHandPush() {
	Player & caster = players[currentPlayerIndex];
	glm::ivec2 wallPos = magicHandTargetTile;
	glm::ivec2 casterPos = { caster.x, caster.y };
	glm::ivec2 dir = wallPos - casterPos;
	glm::ivec2 targetPos = wallPos + dir; // Where the wall goes

	// Check bounds
	if (targetPos.x < 0 || targetPos.x >= BOARD_WIDTH || targetPos.y < 0 || targetPos.y >= BOARD_HEIGHT) {
		spawnFloatingText(gridToWorld(wallPos.x, wallPos.y), "Edge of World!", ofColor::red);
		return;
	}

	// Check if target has another wall
	if (board[targetPos.x][targetPos.y].hasWall) {
		spawnFloatingText(gridToWorld(wallPos.x, wallPos.y), "Blocked by Wall!", ofColor::red);
		return;
	}

	// Check for Unit
	if (board[targetPos.x][targetPos.y].hasPlayer) {
		// Find the unit
		for (size_t i = 0; i < players.size(); i++) {
			if (players[i].x == targetPos.x && players[i].y == targetPos.y) {
				magicHandPushedUnitIndex = (int)i;
				break;
			}
		}

		// Start Damage Roll (2d4 Physical)
		magicHandPushDir = dir;
		pendingMagicHandRollResult = startDiceRoll(2, 4, PURPOSE_MAGIC_HAND_DAMAGE, "Magic Hand Crush");
		isWaitingForMagicHandDamage = true;

		// Pay cost now (apply locally first so packet reflects post-play AP)
		currentAP -= caster.hand[pendingMagicHandCardIndex].cost;
		caster.playedCardsPile.push_back(caster.hand[pendingMagicHandCardIndex]);

		// Notify opponent after local update so pkt.updatedAP contains the post-play AP
		sendMagicHandResolutionPacket(1);

		// Finally remove from hand and finish
		caster.hand.erase(caster.hand.begin() + pendingMagicHandCardIndex);
		pendingMagicHandCardIndex = -1;
		isMagicHandMenuOpen = false;

		// Move Caster and Wall happens AFTER dice logic to sync animations
		return;
	}

	// Empty Space: Just Move
	board[caster.x][caster.y].hasPlayer = false;

	// Move Caster to Wall Pos
	caster.x = wallPos.x;
	caster.y = wallPos.y;
	board[caster.x][caster.y].hasPlayer = true;
	playerVisualPos = gridToWorld(caster.x, caster.y);

	// Move Wall to Target Pos
	board[wallPos.x][wallPos.y].hasWall = false;
	board[targetPos.x][targetPos.y].hasWall = true;
	if (board[wallPos.x][wallPos.y].isMagicWall) {
		board[targetPos.x][targetPos.y].isMagicWall = true;
		board[wallPos.x][wallPos.y].isMagicWall = false;
	}

	buildLevelMesh();

	// Pay cost & finalize locally first
	currentAP -= caster.hand[pendingMagicHandCardIndex].cost;
	caster.playedCardsPile.push_back(caster.hand[pendingMagicHandCardIndex]);

	// Notify opponent after local update so pkt.updatedAP contains the post-play AP
	sendMagicHandResolutionPacket(1);

	// Now remove card from hand and finish
	caster.hand.erase(caster.hand.begin() + pendingMagicHandCardIndex);
	pendingMagicHandCardIndex = -1;

	isMagicHandMenuOpen = false;
	invalidateTargetCache();
}
//--------------------------------------------------------------
void ofApp::generateDraftOptions(int classTier, const std::vector<int> * forcedIndices) {
	draftAcceptLocked = false;
	draftAcceptApplied = false;

	draftAcceptLocked = false;
	draftAcceptApplied = false;

	draftOptions.clear();
	currentDraftClassTier = classTier;
	currentDraftOptionPoolIndices = { -1, -1, -1 };
	const std::vector<Card> * pool = &class1Cards;
	if (classTier == 2) pool = &class2Cards;
	if (classTier == 3) pool = &class3Cards;

	if (pool->empty()) return;

	std::vector<int> indices(pool->size());
	std::iota(indices.begin(), indices.end(), 0);

	if (forcedIndices && !forcedIndices->empty()) {
		int slot = 0;
		for (int idx : *forcedIndices) {
			if (idx >= 0 && idx < (int)pool->size()) {
				draftOptions.push_back((*pool)[idx]);
				if (slot < 3) currentDraftOptionPoolIndices[slot] = idx;
				slot++;
			}
		}
	} else {
		// Deterministic draft generation derived from the shared map seed and draft context.
		draftGenerationCounter++;
		uint32_t derivedSeed = currentMapSeed;
		derivedSeed ^= (uint32_t)classTier * 2654435761u;
		derivedSeed ^= ((uint32_t)draftPlayerIndex << 16);
		derivedSeed ^= ((uint32_t)draftStage << 24);
		derivedSeed ^= draftGenerationCounter * 1103515245u;

		std::mt19937 draftRng(derivedSeed);
		deterministic_shuffle(indices, draftRng);

		for (int i = 0; i < 3 && i < (int)indices.size(); ++i) {
			draftOptions.push_back((*pool)[indices[i]]);
			currentDraftOptionPoolIndices[i] = indices[i];
		}
	}

	if (classTier == 1)
		draftPicksRemaining = 2;
	else
		draftPicksRemaining = 1;

	selectedDraftIndices.clear();
	currentState = STATE_DRAFTING;
	waitingForDraftOptions = false; // Client no longer waits

	// Initialize per-option visual animation state
	draftOptionUI.clear();
	draftOptionUI.resize(draftOptions.size());
	for (size_t ai = 0; ai < draftOptionUI.size(); ++ai) {
		draftOptionUI[ai].startScale = 0.25f;
		draftOptionUI[ai].currentScale = draftOptionUI[ai].startScale;
		draftOptionUI[ai].targetScale = 1.0f;
		draftOptionUI[ai].startTime = ofGetElapsedTimef();
		draftOptionUI[ai].state = DRAFT_ANIM_APPEARING;
		draftOptionUI[ai].hidden = false;
	}

	// The host still sends a packet, but it's for redundancy and state sync,
	// not to provide the options themselves.
	if (isHost()) {
		DraftOptionsPacket dp = {};
		dp.type = PKT_DRAFT_OPTIONS;
		dp.playerID = myLocalPlayerID;
		dp.classTier = classTier;
		dp.mapSeed = currentMapSeed; // Send deterministic params
		dp.draftPlayerIdx = draftPlayerIndex;
		dp.draftPlayerID = (draftPlayerIndex >= 0 && draftPlayerIndex < (int)players.size()) ? players[draftPlayerIndex].playerID : -1;
		dp.picksRemaining = draftPicksRemaining;
		dp.draftStage = draftStage;
		dp.isInGameDraft = isInGameDraft ? 1 : 0;
		dp.draftGenCounter = draftGenerationCounter;
		// Include explicit option pool indices so clients can display options even
		// if deterministic generation would diverge. -1 means "no explicit index".
		dp.optionIdx0 = (currentDraftOptionPoolIndices.size() > 0) ? currentDraftOptionPoolIndices[0] : -1;
		dp.optionIdx1 = (currentDraftOptionPoolIndices.size() > 1) ? currentDraftOptionPoolIndices[1] : -1;
		dp.optionIdx2 = (currentDraftOptionPoolIndices.size() > 2) ? currentDraftOptionPoolIndices[2] : -1;
		{
			bool ok = steamManager.sendPacket(&dp, sizeof(dp));
			ofLogNotice("NetTrace") << "Host: sent PKT_DRAFT_OPTIONS seq=? optIdxs=" << dp.optionIdx0 << "," << dp.optionIdx1 << "," << dp.optionIdx2 << " ok=" << ok;
		}

		DraftStatePacket dsp;
		dsp.type = PKT_DRAFT_STATE;
		dsp.playerID = myLocalPlayerID;
		dsp.classTier = classTier;
		dsp.draftPlayerIdx = draftPlayerIndex;
		dsp.draftPlayerID = (draftPlayerIndex >= 0 && draftPlayerIndex < (int)players.size()) ? players[draftPlayerIndex].playerID : -1;
		dsp.picksRemaining = draftPicksRemaining;
		dsp.draftStage = draftStage;
		dsp.isInGameDraft = isInGameDraft ? 1 : 0;
		dsp.currentPlayerIndex = currentPlayerIndex;
		{
			bool ok2 = steamManager.sendPacket(&dsp, sizeof(dsp));
			ofLogNotice("NetTrace") << "Host: sent PKT_DRAFT_STATE seq=? class=" << dsp.classTier << " picks=" << dsp.picksRemaining << " ok=" << ok2;
		}
	}
}

// Apply authoritative option indices sent by host (clients call this when receiving DraftOptionsPacket)
void ofApp::applyDraftOptionsFromPool(int classTier, const std::vector<int> & indices, int picksRemaining, int draftingPlayerIdx) {
	draftOptions.clear();
	currentDraftClassTier = classTier;
	// --- FIX: Correct vector initialization syntax ---
	currentDraftOptionPoolIndices = { -1, -1, -1 };
	const std::vector<Card> * pool = &class1Cards;
	if (classTier == 2) pool = &class2Cards;
	if (classTier == 3) pool = &class3Cards;

	// --- FIX: Logic Safety Check ---
	if (pool->empty()) {
		ofLogError("Draft") << "CRITICAL: Card pool for Class " << classTier << " is empty on Client! Check cards.json.";
		return; // Avoid crashing or applying invalid indices
	}

	// If we've already completed the initial draft and are in gameplay (and
	// this isn't an in-game draft), ignore late DraftOptions so we don't
	// re-enter drafting on the client. However, if the packet carries a
	// non-zero classTier, it represents a new drafting phase (e.g. Class 2
	// or an in-game key draft) and must be applied.
	if (initialDraftComplete && currentState == STATE_GAMEPLAY && !isInGameDraft && classTier == 0) {
		ofLogNotice("Draft") << "applyDraftOptionsFromPool: ignoring late DraftOptions (gameplay active, no tier).";
		return;
	}

	int slot = 0;
	for (int idx : indices) {
		if (idx >= 0 && idx < (int)pool->size()) {
			draftOptions.push_back((*pool)[idx]);
			if (slot < 3) currentDraftOptionPoolIndices[slot] = idx;
			slot++;
		}
	}

	// --- FIX: Authoritatively apply ALL state from the packet ---
	draftPicksRemaining = picksRemaining;
	draftPlayerIndex = draftingPlayerIdx;
	selectedDraftIndices.clear();
	currentState = STATE_DRAFTING; // Force state transition
	waitingForDraftOptions = false; // We have the options now
	draftAcceptLocked = false;
	draftAcceptApplied = false;
	// -------------------------------------------------------------

	// Log applied options for debugging (helps determine whether Windows client actually applied options)
	if ((int)draftOptions.size() != lastLoggedDraftOptionsCount) {
		lastLoggedDraftOptionsCount = (int)draftOptions.size();
		std::string names = "";
		for (size_t i = 0; i < draftOptions.size(); ++i) {
			if (i) names += ", ";
			names += draftOptions[i].name;
		}
		ofLogNotice("Draft") << "applyDraftOptionsFromPool: applied " << draftOptions.size() << " options for player=" << draftPlayerIndex << " stage=" << draftStage << " names=" << names;
	}
}

void ofApp::onCardPicked(int optionIndex) {
	if (optionIndex < 0 || optionIndex >= (int)draftOptions.size()) return;

	// Diagnostic: log which actor index is being used for this pick
	if (draftPlayerIndex >= 0 && draftPlayerIndex < (int)players.size()) {
		ofLogNotice("Draft") << "onCardPicked: draftPlayerIndex=" << draftPlayerIndex
							 << " isMinion=" << players[draftPlayerIndex].isMinion
							 << " ownerID=" << players[draftPlayerIndex].ownerID
							 << " playerID=" << players[draftPlayerIndex].playerID
							 << " deckSize=" << players[draftPlayerIndex].deck.size();
	} else {
		ofLogNotice("Draft") << "onCardPicked: draftPlayerIndex=" << draftPlayerIndex << " (out of range)";
	}

	Player & p = players[draftPlayerIndex];
	Card picked = draftOptions[optionIndex];

	// IN-GAME DRAFT LOGIC
	if (isInGameDraft) {
		// Keep game logic immediate (card is added and deck shuffled),
		// but also spawn the picked-card visual move so the player sees the card fly into the deck.
		p.deck.push_back(picked);

		// Check if this pick belongs to a minion actor
		bool targetIsMinion = (draftPlayerIndex >= 0 && draftPlayerIndex < (int)players.size() && players[draftPlayerIndex].isMinion);

		// Shuffle deck to include new card (host-authoritative will also send PKT_SHUFFLE)
		shuffleGameVector(p.deck, draftPlayerIndex);

		// Create visual move using same layout math as drawDraftScreen so startPos matches slot
		float uiScale = std::min(ofGetWidth() / 1920.0f, ofGetHeight() / 1080.0f);
		float cardW = std::clamp(340.0f * uiScale, 160.0f, 420.0f);
		float cardH = cardW * 1.4f;
		float spacing = std::clamp(60.0f * uiScale, 20.0f, 96.0f);
		float startX = (ofGetWidth() - (3 * cardW + 2 * spacing)) / 2;
		// Recompute vertical layout used by drawDraftScreen
		float ty = ofGetHeight() * 0.25f;
		float lineH = titleFont.getLineHeight();
		float instrTy = ty + lineH + 8;
		float classTy = instrTy + lineH + 12;
		(void)classTy; // unused
		float topTextBottom = ty + lineH;
		(void)topTextBottom; // unused
		// if any of the text lines are present adjust position
		// (we can't exactly know inGame vs tier text here, but use instr as default)
		float startY = instrTy + lineH + 24.0f;
		// Compute slot center for the picked optionIndex
		int i = optionIndex;
		if (i < 0) i = 0;
		float cx = startX + static_cast<float>(i) * (cardW + spacing);
		glm::vec2 center(cx + cardW / 2.0f, startY + cardH / 2.0f);

		DraftPickedMove mv;
		mv.card = picked;
		mv.startTime = ofGetElapsedTimef();
		mv.delay = draftAnimHoldDuration;
		mv.duration = 0.35f;
		mv.startPos = center;
		mv.endScale = 1.0f; // Default to full size

		// Determine end position and prepare shuffle animation timing
		float shuffleAnimStartDelay = 0.0f; // When to start the shuffle animation

		// If the drafting actor is a minion, target its MinionUI deck rect
		if (targetIsMinion) {
			bool found = false;
			for (const auto & mui : activeMinionUIs) {
				if (mui.playerIndex == draftPlayerIndex) {
					mv.endPos = glm::vec2(mui.deckRect.x + mui.deckRect.width / 2.0f, mui.deckRect.y + mui.deckRect.height / 2.0f);
					// Scale down to fit minion UI deck
					float uiScale = std::min(ofGetWidth() / 1920.0f, ofGetHeight() / 1080.0f);
					float cardW = std::clamp(340.0f * uiScale, 160.0f, 420.0f);
					float cardH = cardW * 1.4f;
					mv.endScale = std::min(mui.deckRect.width, mui.deckRect.height) / std::max(cardW, cardH);
					found = true;
					break;
				}
			}
			if (!found) {
				mv.endPos = glm::vec2(-100, -100);
			}
			mv.finished = false;
			// mark ownerIndex as the minion actor so we can avoid flashing main decks
			mv.ownerIndex = draftPlayerIndex;

			// Schedule shuffle animation to start after card animation completes
			shuffleAnimStartDelay = mv.delay + mv.duration;
		} else if (draftPlayerIndex >= 0 && draftPlayerIndex < (int)players.size()) {
			int ownerID = players[draftPlayerIndex].playerID;
			ofRectangle deckRect = (ownerID == myLocalPlayerID) ? p0_deckRect : p1_deckRect;
			if (!isMultiplayer) deckRect = (ownerID == 0) ? p0_deckRect : p1_deckRect;
			mv.endPos = glm::vec2(deckRect.x + deckRect.width / 2.0f, deckRect.y + deckRect.height / 2.0f);
			// Scale down to fit player deck
			float uiScale = std::min(ofGetWidth() / 1920.0f, ofGetHeight() / 1080.0f);
			float cardW = std::clamp(340.0f * uiScale, 160.0f, 420.0f);
			float cardH = cardW * 1.4f;
			mv.endScale = std::min(deckRect.width, deckRect.height) / std::max(cardW, cardH);
			mv.finished = false;
			mv.ownerIndex = draftPlayerIndex;
		} else {
			mv.endPos = glm::vec2(-100, -100);
			mv.finished = false;
			mv.ownerIndex = draftPlayerIndex;
		}
		activeDraftPickedMoves.push_back(mv);

		// Create shuffle animation for minion, scheduled to start after card animation
		if (targetIsMinion) {
			ShuffleAnimation s;
			s.playerIndex = draftPlayerIndex;
			bool assignedRect = false;
			for (const auto & mui : activeMinionUIs) {
				if (mui.playerIndex == draftPlayerIndex) {
					s.deckRect = mui.deckRect;
					assignedRect = true;
					break;
				}
			}
			if (!assignedRect) {
				int ownerSlot = findPlayerIndexByID(players[draftPlayerIndex].ownerID);
				if (ownerSlot >= 0)
					s.deckRect = (players[ownerSlot].playerID == 0) ? p0_deckRect : p1_deckRect;
				else
					s.deckRect = (players[draftPlayerIndex].ownerID == 0) ? p0_deckRect : p1_deckRect;
			}
			s.startTime = ofGetElapsedTimef() + shuffleAnimStartDelay;
			s.duration = 0.9f;
			s.currentAlpha = 255.0f;
			s.currentScale = 1.0f;
			s.rotation = 0.0f;
			activeShuffleAnimations.push_back(s);
		}
		// Return to game
		currentState = STATE_GAMEPLAY;
		return;
	}
	// Remove picked card from options so it can't be picked again this round
	draftOptions.erase(draftOptions.begin() + optionIndex);

	draftPicksRemaining--;

	if (draftPicksRemaining <= 0) {
		// Stage Complete
		draftStage++;
		// allow visuals to complete before showing next draft
		float delay = draftAnimHoldDuration + 0.35f + 0.9f + 0.1f;
		if (draftStage == 1) {
			// Move to Class 2
			scheduleGenerateDraftOptions(2, delay);
		} else {
			// Player Finished Drafting
			// Check if both players drafted
			// The logic: Winner goes first. If P1 went, check if P2 deck empty.
			int otherPlayer = (draftPlayerIndex + 1) % 2;
			if (players[otherPlayer].deck.empty()) {
				// Switch to other player
				draftPlayerIndex = otherPlayer;
				draftStage = 0;
				scheduleGenerateDraftOptions(1, delay);
			} else {
				// Both done! Start Game.

				// Defer final shuffling and transition until pick animations finish.
				// We'll perform shuffles when `pendingDraftFinalize` resolves in `update()`.
				pendingDraftFinalize = true;
				pendingDraftShuffleNeeded = true;
			}
		}
	}
}
//--------------------------------------------------------------
void ofApp::drawInitiativeRoll() {
	if (activeDiceRolls.size() >= 2) {

		// Position labels so that the local player is always on the left
		glm::vec3 leftPos(-6.0f, 11.0f, 0.0f);
		glm::vec3 rightPos(6.0f, 11.0f, 0.0f);

		// Player 0 is die index 0, player 1 is die index 1
		bool player0OnLeft = (myLocalPlayerID == 0);
		glm::vec3 player0Pos = player0OnLeft ? leftPos : rightPos;
		glm::vec3 player1Pos = player0OnLeft ? rightPos : leftPos;

		glm::vec2 localScreen = getActiveCamera().worldToScreen((myLocalPlayerID == 0) ? player0Pos : player1Pos);
		glm::vec2 opponentScreen = getActiveCamera().worldToScreen((myLocalPlayerID == 0) ? player1Pos : player0Pos);

		// Standardized Text Drawer (Smaller scale)
		auto drawLabel = [&](string text, float x, float y, ofColor col) {
			float fontScale = 0.7f; // Smaller size
			ofRectangle bbox = titleFont.getStringBoundingBox(text, 0, 0);
			float tx = x - (bbox.width * fontScale / 2.0f);
			float ty = y;

			ofPushMatrix();
			ofTranslate(tx, ty);
			ofScale(fontScale, fontScale);

			// Shadow
			ofSetColor(0, 0, 0, 255);
			titleFont.drawString(text, 3, 3);

			// Main Text (Standard UI White/Gold/Grey scheme)
			ofSetColor(col);
			titleFont.drawString(text, 0, 0);

			ofPopMatrix();
		};

		// Draw local player on left, opponent on right
		ofColor localPlayerColor = (myLocalPlayerID == 0) ? ofColor(70, 160, 255) : ofColor(255, 80, 80);
		ofColor opponentColor = (myLocalPlayerID == 0) ? ofColor(255, 80, 80) : ofColor(70, 160, 255);
		string localPlayerName = (myLocalPlayerID == 0) ? getPlayerSteamName(0) : getPlayerSteamName(1);
		string opponentPlayerName = (myLocalPlayerID == 0) ? getPlayerSteamName(1) : getPlayerSteamName(0);

		drawLabel(localPlayerName, localScreen.x, localScreen.y, localPlayerColor);
		drawLabel(opponentPlayerName, opponentScreen.x, opponentScreen.y, opponentColor);

		// Draw Result Message
		if (activeDiceRolls[0].isFinishedVisual && activeDiceRolls[1].isFinishedVisual) {
			string msg = "";

			if (activeDiceRolls[0].result > activeDiceRolls[1].result)
				msg = getPlayerSteamName(0) + " goes first.";
			else if (activeDiceRolls[1].result > activeDiceRolls[0].result)
				msg = getPlayerSteamName(1) + " goes first.";
			else
				msg = "Tie! Rerolling...";

			// Draw in Instruction Area (Top Center)
			ofRectangle mBox = titleFont.getStringBoundingBox(msg, 0, 0);
			float tx = (ofGetWidth() / 2.0f) - (mBox.width / 2.0f);
			float ty = ofGetHeight() * 0.25f;

			ofSetColor(0, 0, 0, 255);
			titleFont.drawString(msg, tx + 2, ty + 2);
			ofSetColor(ofColor::gold);
			titleFont.drawString(msg, tx, ty);
		}
	}
}
//--------------------------------------------------------------
void ofApp::drawDraftScreen() {
	// 1. Construct Specific Instruction Text
	string pName = (draftPlayerIndex == 0) ? player0SteamName : player1SteamName;
	string header = "";
	string instr = "";

	if (isInGameDraft) {
		header = pName + ": Key Found!";
		instr = "Choose 1 Card (Get 1 Copy)";
	} else {
		// Header shows which draft this is for the player whose draft it is.
		// If it's the local player's draft, display "Your first/second draft" instead of their Steam name.
		bool isMyTurnToDraft = (!players.empty() && players[draftPlayerIndex].playerID == myLocalPlayerID);
		if (draftStage == 0) {
			header = isMyTurnToDraft ? "Your first draft" : (pName + "'s first draft");
			instr = isMyTurnToDraft ? "Choose 2 (Get 2 Copies)" : "Choosing 2 (Gets 2 Copies)";
		} else {
			header = isMyTurnToDraft ? "Your second draft" : (pName + "'s second draft");
			instr = isMyTurnToDraft ? "Choose 1 (Get 1 Copy)" : "Choosing 1 (Gets 1 Copy)";
		}
	}

	// 2. Draw Header (Top Center, Shadowed)
	ofRectangle headerBox = titleFont.getStringBoundingBox(header, 0, 0);
	float tx = (ofGetWidth() / 2.0f) - (headerBox.width / 2.0f);
	float ty = ofGetHeight() * 0.25f;
	ofSetColor(0, 0, 0, 255);
	titleFont.drawString(header, tx + 2, ty + 2);
	ofSetColor(ofColor::white);
	titleFont.drawString(header, tx, ty);

	// Use a stable line height for vertical layout so small bounding-box
	// variations (different glyphs) don't shift the card area up/down.
	float lineH = titleFont.getLineHeight();

	// 2b. Draw Instruction line below header
	ofRectangle instrBox = titleFont.getStringBoundingBox(instr, 0, 0);
	float instrTx = (ofGetWidth() / 2.0f) - (instrBox.width / 2.0f);
	float instrTy = ty + lineH + 8; // use fixed line height instead of headerBox.height
	ofSetColor(0, 0, 0, 255);
	titleFont.drawString(instr, instrTx + 2, instrTy + 2);
	ofSetColor(ofColor::white);
	titleFont.drawString(instr, instrTx, instrTy);

	// 2b. Draw Class Tier Text Below Prompt
	std::string classTierText = "";
	ofColor classTierColor = ofColor::white;
	// Predeclare so we can use values for layout later
	ofRectangle classBox;
	float classTx = 0, classTy = 0;
	if (!isInGameDraft) {
		if (draftStage == 0) {
			classTierText = "Class 1";
			classTierColor = ofColor(205, 127, 50); // Bronze
		} else if (draftStage == 1) {
			classTierText = "Class 2";
			classTierColor = ofColor(192, 192, 192); // Silver
		}
	}

	if (!classTierText.empty()) {
		classBox = titleFont.getStringBoundingBox(classTierText, 0, 0);
		classTx = (ofGetWidth() / 2.0f) - (classBox.width / 2.0f);
		// Position class tier text below the instruction line using stable line height
		classTy = instrTy + lineH + 12;
		ofSetColor(0, 0, 0, 255);
		titleFont.drawString(classTierText, classTx + 2, classTy + 2);
		ofSetColor(classTierColor);
		titleFont.drawString(classTierText, classTx, classTy);
	}

	// 3. Draw Cards
	// Standardize card sizing relative to screen so UI scales across resolutions
	float uiScale = std::min(ofGetWidth() / 1920.0f, ofGetHeight() / 1080.0f);
	float cardW = std::clamp(340.0f * uiScale, 160.0f, 420.0f);
	float cardH = cardW * 1.4f;
	float spacing = std::clamp(60.0f * uiScale, 20.0f, 96.0f);
	float startX = (ofGetWidth() - (3 * cardW + 2 * spacing)) / 2;

	// Ensure cards are always positioned consistently below the header/instruction
	// Calculate the bottom of the top text area and use it as the starting Y so
	// both players' drafts render at the same vertical level.
	// Compute bottom of top text area using the stable line height to avoid
	// frame-to-frame shifts caused by glyph bounding-box variation.
	float topTextBottom = ty + lineH;
	if (!instr.empty()) topTextBottom = instrTy + lineH;
	// Keep draft card/button layout stable across stage transitions by reserving
	// class-tier line space for setup drafts, even when class text is empty.
	if (!isInGameDraft) topTextBottom = classTy + lineH;
	float startY = topTextBottom + 24.0f; // fixed padding below text

	// Throttled debug: if we're in draft state but have no options, log mapping once per second
	float nowDbg = ofGetElapsedTimef();
	if (draftOptions.empty() && currentState == STATE_DRAFTING && (nowDbg - lastDraftDrawLogTime) > 1.0f) {
		lastDraftDrawLogTime = nowDbg;
		ofLogNotice("DraftDebug") << "drawDraftScreen: called but draftOptions.empty() currentState=" << currentState << " draftPlayerIndex=" << draftPlayerIndex << " localIdx=" << getLocalPlayerIndex() << " myLocalPlayerID=" << myLocalPlayerID << " waitingForDraftOptions=" << waitingForDraftOptions;
	}

	// Animate per-slot UI and draw scaled cards
	float nowAnim = ofGetElapsedTimef();
	for (size_t i = 0; i < draftOptions.size(); ++i) {
		float x = startX + i * (cardW + spacing);
		ofRectangle cardRect(x, startY, cardW, cardH);

		// Update animation state for this slot
		if (i < draftOptionUI.size()) {
			auto & ui = draftOptionUI[i];
			if (ui.state == DRAFT_ANIM_APPEARING) {
				float t = (nowAnim - ui.startTime) / draftAnimAppearDuration;
				if (t >= 1.0f) {
					ui.currentScale = ui.targetScale;
					ui.state = DRAFT_ANIM_IDLE;
				} else {
					ui.currentScale = ui.startScale + t * (ui.targetScale - ui.startScale);
				}
			} else if (ui.state == DRAFT_ANIM_VANISHING) {
				float t = (nowAnim - ui.startTime) / draftAnimVanishDuration;
				if (t >= 1.0f) {
					ui.currentScale = ui.targetScale;
					ui.hidden = true;
					ui.state = DRAFT_ANIM_IDLE;
				} else {
					ui.currentScale = ui.startScale + t * (ui.targetScale - ui.startScale);
				}
			}
		}

		// Compute scaled rect
		float scale = 1.0f;
		if (i < draftOptionUI.size()) scale = draftOptionUI[i].currentScale;
		float w = cardW * scale;
		float h = cardH * scale;
		float drawX = x + (cardW - w) / 2.0f;
		float drawY = startY + (cardH - h) / 2.0f;

		// Check Selection: compare against authoritative pool index for this slot
		int slotPoolIdx = (i < currentDraftOptionPoolIndices.size()) ? currentDraftOptionPoolIndices[i] : -1;
		bool isSelected = false;
		if (slotPoolIdx >= 0) {
			for (int sel : selectedDraftIndices) {
				if (sel == slotPoolIdx) {
					isSelected = true;
					break;
				}
			}
		}

		// Selection Highlight (Yellow) around scaled rect
		if (isSelected) {
			ofPushStyle();
			ofNoFill();
			ofSetColor(ofColor::yellow);
			ofSetLineWidth(6);
			ofDrawRectRounded(drawX - 8, drawY - 8, w + 16, h + 16, 12);
			ofPopStyle();
		}
		// Hover Highlight (White/Subtle) using unscaled hit area
		else if (cardRect.inside(ofGetMouseX(), ofGetMouseY())) {
			ofPushStyle();
			ofNoFill();
			ofSetColor(ofColor::white);
			ofSetLineWidth(3);
			ofDrawRectRounded(x - 5, startY - 5, cardW + 10, cardH + 10, 10);
			ofPopStyle();
		}

		// Skip hidden slots
		if (i < draftOptionUI.size() && draftOptionUI[i].hidden) continue;

		// Draw Card Sprite scaled
		ofSetColor(255);
		cardSpriteSheet.drawSubsection(drawX, drawY, w, h,
			draftOptions[i].textureRect.x, draftOptions[i].textureRect.y,
			draftOptions[i].textureRect.width, draftOptions[i].textureRect.height);
	}

	// Draw active picked-card move animations (on top)
	this->drawActiveDraftPickedMoves();

	// Deck flash visual
	if (deckFlashStartTime > 0.0f) {
		float t = (ofGetElapsedTimef() - deckFlashStartTime) / deckFlashDuration;
		if (t < 1.0f) {
			ofRectangle deckRect = (deckFlashOwnerIndex == 0) ? p0_deckRect : p1_deckRect;
			float a = (1.0f - t) * 200.0f;
			ofPushStyle();
			ofNoFill();
			ofSetColor(255, 220, 120, (int)a);
			ofSetLineWidth(6);
			ofDrawRectRounded(deckRect.x - 4, deckRect.y - 4, deckRect.width + 8, deckRect.height + 8, 8);
			ofPopStyle();
		} else {
			deckFlashStartTime = 0.0f;
			deckFlashOwnerIndex = -1;
		}
	}

	// Throttled draw-time debug: log if we are drawing non-empty options but haven't logged recently
	float now = ofGetElapsedTimef();
	if (!draftOptions.empty() && (now - lastDraftDrawLogTime) > 1.0f) {
		lastDraftDrawLogTime = now;
		std::string names = "";
		for (size_t i = 0; i < draftOptions.size(); ++i) {
			if (i) names += ", ";
			names += draftOptions[i].name;
		}
		ofLogNotice("Draft") << "drawDraftScreen: drawing " << draftOptions.size() << " options (player=" << draftPlayerIndex << " stage=" << draftStage << ") names=" << names;
	}

	// 4. Draw Accept Button
	int required = 1;
	if (!isInGameDraft && draftStage == 0) required = 2;

	bool canAccept = ((int)selectedDraftIndices.size() == required);

	// Only show the Accept button to the drafting player (or in singleplayer)
	bool showAccept = true;
	if (isMultiplayer) {
		if (!players.empty() && players[draftPlayerIndex].playerID != myLocalPlayerID) showAccept = false;
	}

	if (showAccept && !draftOptions.empty()) {
		float btnW = std::clamp(220.0f * uiScale, 140.0f, 320.0f);
		float btnH = std::clamp(60.0f * uiScale, 40.0f, 96.0f);
		float btnX = (ofGetWidth() - btnW) / 2.0f;
		// Use a fixed calculation based on screen height to prevent jumping
		float btnY = ofGetHeight() * 0.75f;

		// Ensure button isn't placed off-screen on short displays
		float minBottomMargin = 20.0f * uiScale;
		float maxBtnY = ofGetHeight() - btnH - minBottomMargin;
		if (btnY > maxBtnY) btnY = maxBtnY;
		// Also ensure it's below the cards
		float minBtnY = startY + cardH + std::clamp(24.0f * uiScale, 12.0f, 48.0f);
		if (btnY < minBtnY) btnY = minBtnY;

		draftAcceptButtonRect.set(btnX, btnY, btnW, btnH);

		ofSetColor(canAccept ? ofColor(70, 160, 255) : ofColor(100, 100, 100));
		ofDrawRectRounded(draftAcceptButtonRect, 12);

		ofSetColor(ofColor::white);
		ofRectangle acceptTextBox = uiFont.getStringBoundingBox("Accept", 0, 0);
		uiFont.drawString("Accept", btnX + (btnW - acceptTextBox.width) / 2, btnY + (btnH + acceptTextBox.height) / 2 - 6);
	} else {
		// Hide accept: clear the rect so hits are ignored
		draftAcceptButtonRect.set(0, 0, 0, 0);
	}

	if (isShowingPileView && currentPileViewPlayerIndex != -1) {
		drawPileViewFor(currentPileViewPlayerIndex, currentPileView);
	}
}

// Draw and advance active draft-picked move animations (visual only)
void ofApp::drawActiveDraftPickedMoves() {
	// Use layout math consistent with drawDraftScreen (cardW/cardH computed there)
	float uiScale = std::min(ofGetWidth() / 1920.0f, ofGetHeight() / 1080.0f);
	float cardW = std::clamp(340.0f * uiScale, 160.0f, 420.0f);
	float cardH = cardW * 1.4f;

	for (auto & mv : activeDraftPickedMoves) {
		if (mv.finished) continue;
		float now = ofGetElapsedTimef();
		if (now < mv.startTime + mv.delay) {
			float drawW = cardW;
			float drawH = cardH;
			float dx = mv.startPos.x - drawW / 2.0f;
			float dy = mv.startPos.y - drawH / 2.0f;
			ofSetColor(255);
			cardSpriteSheet.drawSubsection(dx, dy, drawW, drawH,
				mv.card.textureRect.x, mv.card.textureRect.y,
				mv.card.textureRect.width, mv.card.textureRect.height);
		} else {
			float t = (now - mv.startTime - mv.delay) / mv.duration;
			if (t >= 1.0f) t = 1.0f;
			glm::vec2 pos = mv.startPos * (1.0f - t) + mv.endPos * t;
			float scale = 1.0f * (1.0f - t) + mv.endScale * t;
			float drawW = cardW * scale;
			float drawH = cardH * scale;
			float dx = pos.x - drawW / 2.0f;
			float dy = pos.y - drawH / 2.0f;
			ofSetColor(255);
			cardSpriteSheet.drawSubsection(dx, dy, drawW, drawH,
				mv.card.textureRect.x, mv.card.textureRect.y,
				mv.card.textureRect.width, mv.card.textureRect.height);
			if (t >= 1.0f) {
				mv.finished = true;
				// Only flash main player decks; minion targets use their own shuffle visuals
				if (mv.ownerIndex >= 0 && mv.ownerIndex < (int)players.size() && !players[mv.ownerIndex].isMinion) {
					deckFlashStartTime = now;
					deckFlashOwnerIndex = mv.ownerIndex;
				}
			}
		}
	}

	// Remove finished moves
	for (size_t i = activeDraftPickedMoves.size(); i-- > 0;) {
		if (activeDraftPickedMoves[i].finished) activeDraftPickedMoves.erase(activeDraftPickedMoves.begin() + i);
	}
}
// Draw the pile view panel for a given player and view mode (consolidated helper)
void ofApp::drawPileViewFor(int viewPlayerIndex, PileViewMode viewMode) {
	if (viewPlayerIndex < 0 || viewPlayerIndex >= (int)players.size()) return;
	Player & viewPlayer = players[viewPlayerIndex];
	string viewTitle;
	std::vector<Card> cardsToShow;

	float handBaseCardWidth = 120;
	float aspectRatio = 585.0f / 409.0f;
	float baseCardHeight = handBaseCardWidth * aspectRatio;

	if (viewMode == VIEW_DECK) {
		viewTitle = "Deck";
		cardsToShow = viewPlayer.deck;
		std::sort(cardsToShow.begin(), cardsToShow.end(), [](const Card & a, const Card & b) {
			if (a.cost != b.cost) return a.cost < b.cost;
			return a.name < b.name;
		});
	} else {
		viewTitle = "Discard Pile";
		cardsToShow = viewPlayer.discardPile;
		std::reverse(cardsToShow.begin(), cardsToShow.end());
	}

	// Prefer human-friendly names. For minions, prefer the same numbering used in the Minion UI
	if (viewPlayer.isMinion) {
		// Find the matching MinionUI to reuse its displayNumber (ensures Assistant 1/2 match the side UI)
		int foundNumber = 0;
		for (const auto & mui : activeMinionUIs) {
			if (mui.playerIndex == viewPlayerIndex) {
				foundNumber = mui.displayNumber;
				break;
			}
		}
		std::string prefix = "Minion";
		if (viewPlayer.isFaerie)
			prefix = "Faerie";
		else if (viewPlayer.isWallUnit)
			prefix = "Wall";
		else if (viewPlayer.isKobold)
			prefix = "Kobold";
		else if (viewPlayer.isAssistant)
			prefix = "Assistant";
		else if (viewPlayer.isWolf)
			prefix = "Wolf";
		else if (viewPlayer.isHellhound)
			prefix = "Hellhound";
		else if (viewPlayer.isGolem)
			prefix = "Golem";
		else if (viewPlayer.isSkeleton)
			prefix = "Skeleton";
		else if (viewPlayer.isDemon)
			prefix = "Demon";

		if (foundNumber > 0) {
			viewTitle = prefix + " " + ofToString(foundNumber) + "'s " + viewTitle;
		} else {
			// Fallback to existing display-name logic
			viewTitle = getPlayerDisplayName(viewPlayerIndex) + "'s " + viewTitle;
		}
	} else {
		int vpIdx = -1;
		for (int i = 0; i < (int)players.size(); ++i) {
			if (players[i].playerID == viewPlayer.playerID && !players[i].isMinion) {
				vpIdx = i;
				break;
			}
		}
		viewTitle = (vpIdx != -1) ? getPlayerSteamName(vpIdx) : ("Player " + ofToString(viewPlayer.playerID)) + "'s " + viewTitle;
	}

	if (cardsToShow.empty()) {
		isShowingPileView = false;
		return;
	}

	float panelPadding = 20.0f;
	float titleHeight = 40.0f;
	float viewCardScale = 1.6f;
	float availableHeight = ofGetHeight() - (2 * panelPadding) - titleHeight;
	float availableWidth = ofGetWidth() * 0.7f;

	while (viewCardScale > 0.5f) {
		float cardW = handBaseCardWidth * viewCardScale;
		float cardH = baseCardHeight * viewCardScale;
		float padding = 15.0f * (viewCardScale / 1.6f);
		int cols = std::max(1, (int)floor((availableWidth - padding) / (cardW + padding)));
		int rows = ceil((float)cardsToShow.size() / cols);
		if (rows * (cardH + padding) - padding <= availableHeight) break;
		viewCardScale -= 0.1f;
	}

	float viewCardWidth = handBaseCardWidth * viewCardScale;
	float viewCardHeight = baseCardHeight * viewCardScale;
	float padding = 15.0f * (viewCardScale / 1.6f);
	int gridWidthInCards = std::max(1, (int)floor((availableWidth - padding) / (viewCardWidth + padding)));
	gridWidthInCards = std::min(gridWidthInCards, (int)cardsToShow.size());
	if (gridWidthInCards <= 0) gridWidthInCards = 1;
	int gridHeightInCards = ceil((float)cardsToShow.size() / gridWidthInCards);
	float totalContentWidth = (gridWidthInCards * viewCardWidth) + ((gridWidthInCards - 1) * padding);
	float totalContentHeight = (gridHeightInCards * viewCardHeight) + ((gridHeightInCards - 1) * padding);

	float startX;
	bool anchored = false;
	if (viewPlayer.isMinion) {
		for (const auto & mui : activeMinionUIs) {
			if (mui.playerIndex == viewPlayerIndex) {
				float rightSpace = ofGetWidth() - mui.deckRect.getRight();
				if (rightSpace > totalContentWidth + 60.0f) {
					startX = mui.deckRect.getRight() + 30.0f;
				} else {
					startX = mui.deckRect.getLeft() - totalContentWidth - 30.0f - (2 * panelPadding);
				}
				anchored = true;
				break;
			}
		}
	}
	if (!anchored) {
		bool viewingLocal = (viewPlayer.playerID == myLocalPlayerID);
		if (viewingLocal)
			startX = p0_deckRect.getRight() + 30.0f;
		else
			startX = p1_deckRect.getLeft() - totalContentWidth - 30.0f - (2 * panelPadding);
	}
	float startY = ofGetHeight() / 2.0f - totalContentHeight / 2.0f;

	pileViewRect.set(startX, startY - titleHeight - panelPadding, totalContentWidth + 2 * panelPadding, totalContentHeight + titleHeight + 2 * panelPadding);

	ofSetColor(20, 20, 20, 220);
	ofDrawRectRounded(pileViewRect, 15);
	ofSetColor(ofColor::white);
	uiFont.drawString(viewTitle + " (" + ofToString(cardsToShow.size()) + " cards)", startX + panelPadding, startY - 15);

	for (size_t i = 0; i < cardsToShow.size(); ++i) {
		int row = i / gridWidthInCards;
		int col = i % gridWidthInCards;
		float drawX = startX + panelPadding + col * (viewCardWidth + padding);
		float drawY = startY + row * (viewCardHeight + padding);
		const Card & card = cardsToShow[i];
		cardSpriteSheet.drawSubsection(drawX, drawY, viewCardWidth, viewCardHeight, card.textureRect.x, card.textureRect.y, card.textureRect.width, card.textureRect.height);
	}
}
//--------------------------------------------------------------
void ofApp::drawTrainMenuUI() {
	ofEnableBlendMode(OF_BLENDMODE_ALPHA);
	// Dark Overlay
	ofSetColor(0, 0, 0, 180);
	ofDrawRectangle(0, 0, ofGetWidth(), ofGetHeight());

	// Title & Desc
	string title = "Train";
	string desc = "Choose your training path:";

	// Colors: Yellow for AP, Bronze/Orange for Class 1 Draft
	ofColor apColor(255, 215, 0);
	ofColor draftColor(205, 127, 50);

	// Ensure buttons are positioned if not already set (safety check)
	if (trainMenuRect.width == 0) {
		float w = 600, h = 300;
		float x = ofGetWidth() / 2 - w / 2, y = ofGetHeight() / 2 - h / 2;
		trainMenuRect.set(x, y, w, h);
		float btnW = 260, btnH = 80, spacing = 30;
		float startX = x + (w - (btnW * 2 + spacing)) / 2;
		float btnY = y + 130;
		trainBtnAP.set(startX, btnY, btnW, btnH);
		trainBtnDraft.set(startX + btnW + spacing, btnY, btnW, btnH);
	}

	drawCardChoicePanel(trainMenuRect, title, desc, trainBtnAP, trainBtnDraft,
		"+3 AP Next Turn", "Draft Class 1",
		apColor, draftColor, true, true);
}
//--------------------------------------------------------------
void ofApp::exit() {
	// Save settings on exit
	saveSettings();
	steamManager.cleanup();
	// Ensure the Steam API is fully shut down on app exit
	steamManager.shutdownAPI();
}
// --------------------------------------------------------------
void ofApp::updateAndSendHover(HoverType type, int gridX, int gridY, int cardIndex) {
	// Check if hover state changed
	if (type != localHoverType || gridX != localHoverGridX || gridY != localHoverGridY || cardIndex != localHoverCardIndex) {

		// Update local hover state
		localHoverType = type;
		localHoverGridX = gridX;
		localHoverGridY = gridY;
		localHoverCardIndex = cardIndex;

		// Send hover packet to opponent if in multiplayer
		if (isMultiplayer && steamManager.isConnected()) {
			HoverPacket pkt = {};
			pkt.type = PKT_HOVER;
			pkt.playerID = myLocalPlayerID;
			pkt.hoverType = static_cast<uint8_t>(type);
			pkt.gridX = static_cast<int8_t>(gridX);
			pkt.gridY = static_cast<int8_t>(gridY);
			pkt.cardIndex = static_cast<int8_t>(cardIndex);
			steamManager.sendPacket(&pkt, sizeof(pkt));
		}
	}
}
// Networking / player helpers
int ofApp::getLocalPlayerIndex() const {
	for (int i = 0; i < (int)players.size(); ++i) {
		if (players[i].playerID == myLocalPlayerID) return i;
	}
	return -1;
}

bool ofApp::isLocalDraftingPlayer(int draftIndex) const {
	if (!isMultiplayer) return true;
	int localIdx = getLocalPlayerIndex();
	// Accept if either the slot index matches or the playerID at the slot matches local ID.
	if (localIdx >= 0 && localIdx == draftIndex) return true;
	if (draftIndex >= 0 && draftIndex < (int)players.size() && players[draftIndex].playerID == myLocalPlayerID) return true;
	return false;
}
// --------------------------------------------------------------
void ofApp::processNetworkPackets() {
	// Diagnostic: report incoming queue size so we can see if packets are piling up
	if (!steamManager.packetQueue.empty()) {
		ofLogNotice("NetTrace") << "processNetworkPackets: queueSize=" << steamManager.packetQueue.size();
	}
	// Temporary reusable packet used for state syncs (declare once so it's in scope for the whole function)
	DraftStatePacket tempDraftStatePkt = {};
	while (!steamManager.packetQueue.empty()) {
		std::vector<char> buffer = steamManager.packetQueue.front();
		steamManager.packetQueue.pop();

		// --- FIX: Only handle REQ_SEED (8 bytes) ---
		if (buffer.size() == 8) {
			string msg(buffer.begin(), buffer.end());
			if (msg == "REQ_SEED" && steamManager.isHost()) {
				ofLogNotice("Network") << "Host: Received Seed Request. Resending Seed: " << currentMapSeed;
				HandshakePacket pkt = {};
				pkt.type = PKT_HANDSHAKE;
				pkt.playerID = myLocalPlayerID;
				pkt.seq = 0;
				pkt.seed = currentMapSeed;
				steamManager.sendPacket(&pkt, sizeof(pkt));
				continue; // Done with this packet
			}
		}
		// -------------------------------------------------------------------

		if (buffer.size() < sizeof(PacketHeader)) continue;

		PacketHeader * header = (PacketHeader *)buffer.data();

		// Mark that we're actively processing a network packet. This allows us to
		// enforce the "Zombie Client" rule: clients must not execute authoritative
		// logic (draws, dice, turn starts) except while handling host packets.
		{
			struct PacketProcessingGuard {
				bool * flag;
				PacketProcessingGuard(bool * f)
					: flag(f) { *flag = true; }
				~PacketProcessingGuard() { *flag = false; }
			} packetGuard(&processingNetworkPacket);

			// EARLY: defensively handle DraftOptions so clients reliably apply them
			if (header->type == PKT_DRAFT_OPTIONS) {
				if (buffer.size() < sizeof(DraftOptionsPacket)) {
					// Malformed/truncated packet: request snapshot on client
					if (isClient()) {
						SnapshotRequestPacket req = {};
						req.type = PKT_SNAPSHOT_REQUEST;
						req.playerID = myLocalPlayerID;
						req.requestedTurn = globalTurnCounter;
						steamManager.sendPacket(&req, sizeof(req));
						waitingForSnapshot = true;
					}
					continue;
				}

				DraftOptionsPacket * dp = (DraftOptionsPacket *)buffer.data();
				// Sync deterministic params from host
				draftGenerationCounter = dp->draftGenCounter - 1; // generateDraftOptions will ++
				currentMapSeed = dp->mapSeed;
				draftStage = dp->draftStage;
				// Map draft player id to local index on clients
				if (isClient()) {
					int incomingPlayerID = dp->draftPlayerID;
					int mappedIdx = -1;
					for (int i = 0; i < (int)players.size(); ++i) {
						if (players[i].playerID == incomingPlayerID) {
							mappedIdx = i;
							break;
						}
					}
					if (mappedIdx >= 0)
						draftPlayerIndex = mappedIdx;
					else
						draftPlayerIndex = dp->draftPlayerIdx;
				} else {
					draftPlayerIndex = dp->draftPlayerIdx;
				}
				draftPicksRemaining = dp->picksRemaining;
				isInGameDraft = (dp->isInGameDraft != 0);
				// Apply explicit indices if provided, otherwise generate deterministically
				if (dp->optionIdx0 != -1 || dp->optionIdx1 != -1 || dp->optionIdx2 != -1) {
					std::vector<int> indices;
					if (dp->optionIdx0 != -1) indices.push_back(dp->optionIdx0);
					if (dp->optionIdx1 != -1) indices.push_back(dp->optionIdx1);
					if (dp->optionIdx2 != -1) indices.push_back(dp->optionIdx2);
					applyDraftOptionsFromPool(dp->classTier, indices, dp->picksRemaining, draftPlayerIndex);
				} else {
					generateDraftOptions(dp->classTier);
				}
				continue; // handled
			}

			// Verbose packet tracing for debugging desyncs
			if (header->type == PKT_ACTION || header->type == PKT_DRAFT_ACTION || header->type == PKT_DRAFT_STATE || header->type == PKT_DRAFT_OPTIONS || header->type == PKT_DRAFT_ACK || header->type == PKT_RENEWED_INSPIRATION || header->type == PKT_DRAW_CARDS || header->type == PKT_SHUFFLE || header->type == PKT_TURN_START || header->type == PKT_PLACE_SUMMONED_MINION || header->type == PKT_DICE_ROLL || header->type == PKT_CHECKSUM_CHECK || header->type == PKT_SNAPSHOT_BEGIN || header->type == PKT_SNAPSHOT_CHUNK || header->type == PKT_SNAPSHOT_END || header->type == PKT_MOVE_UNIT || header->type == PKT_AMNESIA_CHOICE || header->type == PKT_PLACE_SUMMONED_BEGIN) {
				ofLogNotice("NetTrace") << "RECV pkt type=" << (int)header->type << " player=" << header->playerID << " seq=" << header->seq << " size=" << buffer.size();
				if (header->type == PKT_ACTION && buffer.size() >= sizeof(ActionPacket)) {
					ActionPacket * ap = (ActionPacket *)buffer.data();
					ofLogNotice("NetTrace") << "  ACTION card='" << ap->cardName << "' actor=" << ap->actorIndex << " target=(" << ap->targetX << "," << ap->targetY << ") menu=" << ap->menuChoice << " updatedAP=" << ap->updatedAP;
				} else if (header->type == PKT_SHUFFLE && buffer.size() >= sizeof(ShufflePacket)) {
					ShufflePacket * spk = (ShufflePacket *)buffer.data();
					ofLogNotice("NetTrace") << "  SHUFFLE playerIndex=" << spk->playerIndex << " nonce=" << spk->nonce;
				} else if (header->type == PKT_TURN_START && buffer.size() >= sizeof(TurnStartPacket)) {
					TurnStartPacket * tsp = (TurnStartPacket *)buffer.data();
					ofLogNotice("NetTrace") << "  TURN_START currentPlayerIndex=" << tsp->currentPlayerIndex << " diceNum=" << (int)tsp->diceNum << " diceSides=" << (int)tsp->diceSides << " finalTotal=" << tsp->finalTotal;
				} else if (header->type == PKT_DRAW_CARDS && buffer.size() >= sizeof(DrawCardsPacket)) {
					DrawCardsPacket * dcp = (DrawCardsPacket *)buffer.data();
					ofLogNotice("NetTrace") << "  DRAW_CARDS playerIndex=" << dcp->playerIndex << " numCards=" << (int)dcp->numCards;
				} else if (header->type == PKT_RENEWED_INSPIRATION && buffer.size() >= sizeof(RenewedInspirationPacket)) {
					RenewedInspirationPacket * rip = (RenewedInspirationPacket *)buffer.data();
					ofLogNotice("NetTrace") << "  RINSP playerIndex=" << rip->playerIndex << " count=" << (int)rip->count;
				} else if (header->type == PKT_PLACE_SUMMONED_MINION && buffer.size() >= sizeof(PlaceSummonedMinionPacket)) {
					PlaceSummonedMinionPacket * psp = (PlaceSummonedMinionPacket *)header;
					ofLogNotice("NetTrace") << "  PLACE_SUMMONED minionType=" << (int)psp->minionType << " ownerID=" << psp->ownerPlayerID << " target=(" << psp->targetX << "," << psp->targetY << ") HP=" << psp->minionHP << " AP=" << psp->minionAP;
				} else if (header->type == PKT_DICE_ROLL && buffer.size() >= sizeof(DiceRollPacket)) {
					DiceRollPacket * drp = (DiceRollPacket *)buffer.data();
					ofLogNotice("NetTrace") << "  DICE_ROLL owner=" << drp->ownerIndex << " numDice=" << (int)drp->numDice << " sides=" << (int)drp->sides;
				} else if (header->type == PKT_CHECKSUM_CHECK && buffer.size() >= sizeof(ChecksumPacket)) {
					ChecksumPacket * ckp = (ChecksumPacket *)buffer.data();
					ofLogNotice("NetTrace") << "  CHECKSUM turn=" << ckp->turnNumber << " value=" << ckp->checksum;
				} else if (header->type == PKT_SNAPSHOT_BEGIN && buffer.size() >= sizeof(SnapshotBeginPacket)) {
					SnapshotBeginPacket * sb = (SnapshotBeginPacket *)buffer.data();
					ofLogNotice("NetTrace") << "  SNAPSHOT_BEGIN id=" << sb->snapshotId << " totalSize=" << sb->totalSize;
				} else if (header->type == PKT_SNAPSHOT_CHUNK && buffer.size() >= sizeof(SnapshotChunkPacket)) {
					SnapshotChunkPacket * sc = (SnapshotChunkPacket *)buffer.data();
					ofLogNotice("NetTrace") << "  SNAPSHOT_CHUNK id=" << sc->snapshotId << " offset=" << sc->offset << " chunkSize=" << sc->chunkSize;
				} else if (header->type == PKT_SNAPSHOT_END && buffer.size() >= sizeof(SnapshotEndPacket)) {
					SnapshotEndPacket * se = (SnapshotEndPacket *)buffer.data();
					ofLogNotice("NetTrace") << "  SNAPSHOT_END id=" << se->snapshotId;
				} else if (header->type == PKT_MOVE_UNIT && buffer.size() >= sizeof(MoveUnitPacket)) {
					MoveUnitPacket * mup = (MoveUnitPacket *)buffer.data();
					ofLogNotice("NetTrace") << "  MOVE from=(" << mup->fromX << "," << mup->fromY << ") to=(" << mup->toX << "," << mup->toY << ")";
				} else if (header->type == PKT_AMNESIA_CHOICE && buffer.size() >= sizeof(AmnesiaChoicePacket)) {
					AmnesiaChoicePacket * apc = (AmnesiaChoicePacket *)buffer.data();
					ofLogNotice("NetTrace") << "  AMNESIA targetPlayer=" << apc->targetPlayerIndex << " numRemove=" << (int)apc->numCardsToRemove;
				} else if (header->type == PKT_PLACE_SUMMONED_BEGIN && buffer.size() >= sizeof(PlaceSummonedBeginPacket)) {
					PlaceSummonedBeginPacket * psb = (PlaceSummonedBeginPacket *)buffer.data();
					ofLogNotice("NetTrace") << "  PLACE_SUMMON_BEGIN minionType=" << (int)psb->minionType << " ownerID=" << psb->ownerPlayerID << " numToPlace=" << psb->numToPlace;
				} else if (header->type == PKT_DRAFT_STATE && buffer.size() >= sizeof(DraftStatePacket)) {
					DraftStatePacket * sp = (DraftStatePacket *)buffer.data();
					ofLogNotice("NetTrace") << "  DRAFT_STATE class=" << sp->classTier << " player=" << sp->draftPlayerIdx << " picks=" << sp->picksRemaining << " stage=" << sp->draftStage << " ingame=" << (int)sp->isInGameDraft << " curPlayer=" << sp->currentPlayerIndex;
				} else if (header->type == PKT_DRAFT_OPTIONS && buffer.size() >= sizeof(DraftOptionsPacket)) {
					DraftOptionsPacket * dp = (DraftOptionsPacket *)buffer.data();
					ofLogNotice("NetTrace") << "  DRAFT_OPTIONS class=" << dp->classTier << " player=" << dp->draftPlayerIdx << " picks=" << dp->picksRemaining << " stage=" << dp->draftStage << " ingame=" << (int)dp->isInGameDraft << " genC=" << dp->draftGenCounter << " mapSeed=" << dp->mapSeed;
				}
			}
			// ACK handling removed; rely on SteamNetworkingSockets reliability.

			// Only check duplicates for PKT_ACTION (card plays) to prevent duplicate card plays.
			// STRICT: rely solely on clientActionID for deduplication on the host.
			// Network seq numbers are not used for dedupe because they can be
			// unrelated and much larger than client-local monotonic IDs.
			if (header->type == PKT_ACTION && buffer.size() >= sizeof(ActionPacket)) {
				ActionPacket * ap = (ActionPacket *)buffer.data();
				int sender = (header->playerID == 0 || header->playerID == 1) ? (int)header->playerID : -1;
				if (sender >= 0 && isHost()) {
					if (ap->clientActionID != 0) {
						if (ap->clientActionID <= lastReceivedSeqByPlayer[sender]) {
							ofLogNotice("Network") << "DROPPED DUPLICATE ACTION PACKET (clientActionID): clientActionID=" << ap->clientActionID << " lastReceived[" << sender << "]=" << lastReceivedSeqByPlayer[sender];
							// Re-ACK the clientActionID so the originating client stops resending
							AckPacket ack = {};
							ack.type = PKT_ACK;
							ack.playerID = myLocalPlayerID;
							ack.ackSeq = ap->clientActionID; // echo the client ID
							ack.ackType = PKT_ACTION;
							steamManager.sendPacket(&ack, sizeof(ack));
							ofLogNotice("NetTrace") << "Host: re-sent ACK for ActionPacket clientActionID=" << ack.ackSeq;
							continue;
						}
						lastReceivedSeqByPlayer[sender] = ap->clientActionID;
					} else {
						// No clientActionID present: cannot safely dedupe. Accept packet but
						// do not update lastReceivedSeqByPlayer to avoid corrupting the ID timeline.
						ofLogNotice("NetTrace") << "Host: Received ActionPacket without clientActionID; skipping dedupe.";
					}
				}
			}
			// Handle Shuffle packets early so clients can deterministically apply them without touching gameplayRNG
			if (header->type == PKT_SHUFFLE) {
				ShufflePacket * spk = (ShufflePacket *)header;
				ofLogNotice("Network") << "Shuffle packet received: player=" << spk->playerIndex << " nonce=" << spk->nonce;
				if (spk->playerIndex >= 0 && spk->playerIndex < (int)players.size()) {
					// Diagnostic: dump deck sample before applying/queueing
					{
						std::string sample;
						for (size_t i = 0; i < players[spk->playerIndex].deck.size() && i < 8; ++i) {
							if (!sample.empty()) sample += ",";
							sample += players[spk->playerIndex].deck[i].name;
						}
						if (players[spk->playerIndex].deck.size() > 8) sample += ",...";
						ofLogNotice("Network") << "  Deck sample before shuffle (player " << spk->playerIndex << "): " << sample << " (size=" << players[spk->playerIndex].deck.size() << ")";
					}
					// If we're a client and drafting hasn't been accepted yet, queue the nonce
					if (isClient() && (currentState == STATE_DRAFTING || isInGameDraft) && !draftAcceptApplied) {
						pendingShuffleNonces[spk->playerIndex].push_back(spk->nonce);
						ofLogNotice("Network") << "Client: Queued shuffle nonce for player " << spk->playerIndex << " (queued count=" << pendingShuffleNonces[spk->playerIndex].size() << ")";
						continue;
					}
					// If the nonce was already applied or is already queued, ignore
					if (isClient()) {
						if (lastAppliedShuffleNonce[spk->playerIndex] == spk->nonce) {
							ofLogNotice("Network") << "Client: Ignoring duplicate shuffle nonce for player " << spk->playerIndex << " (already applied)";
							continue;
						}
						bool alreadyQueued = false;
						for (auto qn : pendingShuffleNonces[spk->playerIndex])
							if (qn == spk->nonce) {
								alreadyQueued = true;
								break;
							}
						if (alreadyQueued) {
							ofLogNotice("Network") << "Client: Ignoring duplicate shuffle nonce for player " << spk->playerIndex << " (already queued)";
							continue;
						}
					}
					std::mt19937 shuffleRng(spk->nonce);
					deterministic_shuffle(players[spk->playerIndex].deck, shuffleRng);
					// Diagnostic: dump deck sample after applying
					{
						std::string sampleAfter;
						for (size_t i = 0; i < players[spk->playerIndex].deck.size() && i < 8; ++i) {
							if (!sampleAfter.empty()) sampleAfter += ",";
							sampleAfter += players[spk->playerIndex].deck[i].name;
						}
						if (players[spk->playerIndex].deck.size() > 8) sampleAfter += ",...";
						ofLogNotice("Network") << "  Deck sample after shuffle (player " << spk->playerIndex << "): " << sampleAfter << " (size=" << players[spk->playerIndex].deck.size() << ")";
					}
					if (isClient()) {
						lastAppliedShuffleNonce[spk->playerIndex] = spk->nonce;
					}
					// Clear any 'needs shuffle' marker now that we've applied the authoritative shuffle
					players[spk->playerIndex].deckNeedsShuffle = false;
					// Only clear the per-player skip guard if it was set for this player
					if (skipClientShuffleFor == spk->playerIndex) {
						skipClientShuffleFor = -1;
						ofLogNotice("Network") << "Client: Applied shuffle nonce for player " << spk->playerIndex << " and cleared skip flag";
					} else {
						ofLogNotice("Network") << "Client: Applied shuffle nonce for player " << spk->playerIndex;
					}

					// CLIENT: send ACK back to host to confirm we've applied the shuffle
					if (isClient()) {
						AckPacket ack = {};
						ack.type = PKT_ACK;
						ack.playerID = myLocalPlayerID;
						ack.ackSeq = spk->seq;
						ack.ackType = PKT_SHUFFLE;
						steamManager.sendPacket(&ack, sizeof(ack));
						ofLogNotice("NetTrace") << "Client: sent ACK for Shuffle seq=" << ack.ackSeq;
					}
				}
				continue; // Done with this packet
			}

			// Handle Renewed Inspiration selection
			if (header->type == PKT_RENEWED_INSPIRATION) {
				RenewedInspirationPacket * rpk = (RenewedInspirationPacket *)header;
				// Prevent the originating client from applying their own selection twice
				if (isClient() && rpk->playerID == static_cast<uint32_t>(myLocalPlayerID)) {
					ofLogNotice("Network") << "Client: Ignoring echo of own RenewedInspiration packet.";
					continue;
				}

				// Host-side deduplication: ignore retransmitted watchdog packets already processed
				if (isHost() && rpk->clientActionID != 0) {
					uint32_t pid = rpk->playerID;
					if (pid < (uint32_t)(sizeof(lastProcessedActionID) / sizeof(lastProcessedActionID[0])) && rpk->clientActionID <= lastProcessedActionID[pid]) {
						ofLogNotice("Network") << "Host: Ignoring duplicate RenewedInspiration clientActionID=" << rpk->clientActionID << " from playerID=" << pid;
						// Still ACK so client stops resending (keep legacy ack=seq behaviour)
						AckPacket ackDup = {};
						ackDup.type = PKT_ACK;
						ackDup.playerID = myLocalPlayerID;
						ackDup.ackSeq = rpk->clientActionID; // echo clientActionID
						ackDup.ackType = PKT_RENEWED_INSPIRATION;
						steamManager.sendPacket(&ackDup, sizeof(ackDup));
						continue;
					}
				}
				if (rpk->playerIndex >= 0 && rpk->playerIndex < (int)players.size()) {
					// If we're the host, forward this packet to all clients so everyone
					// (including the original sender) applies the effect authoritatively.
					if (isHost()) {
						RenewedInspirationPacket outPkt = *rpk;
						steamManager.sendPacket(&outPkt, sizeof(outPkt));
						ofLogNotice("Network") << "Host: Forwarded RenewedInspiration to clients.";
						// Send ACK back to originating client so it stops resending if it expects one
						AckPacket ack = {};
						ack.type = PKT_ACK;
						ack.playerID = myLocalPlayerID;
						ack.ackSeq = rpk->clientActionID; // echo clientActionID so client can match
						ack.ackType = PKT_RENEWED_INSPIRATION;
						steamManager.sendPacket(&ack, sizeof(ack));
						ofLogNotice("NetTrace") << "Host: sent ACK for RenewedInspiration clientActionID=" << ack.ackSeq;
						// Record processed clientActionID so retransmits are ignored
						if (rpk->clientActionID != 0) {
							uint32_t pid = rpk->playerID;
							if (pid < (uint32_t)(sizeof(lastProcessedActionID) / sizeof(lastProcessedActionID[0]))) {
								lastProcessedActionID[pid] = rpk->clientActionID;
								ofLogNotice("Network") << "Host: recorded lastProcessedActionID[" << pid << "]=" << lastProcessedActionID[pid];
							}
						}
					}

					Player & p = players[rpk->playerIndex];
					// Packet contains card names to discard to avoid hand-index mismatches
					int discarded = 0;
					for (int i = 0; i < rpk->count && i < 16; ++i) {
						std::string name = rpk->cardNames[i];
						if (name.empty()) continue;
						// Find the first matching card in hand and remove it
						for (auto it = p.hand.begin(); it != p.hand.end(); ++it) {
							if (it->name == name) {
								p.discardPile.push_back(*it);
								p.hand.erase(it);
								discarded++;
								break;
							}
						}
					}
					ofLogNotice("Network") << "Renewed Inspiration: Opponent discarded " << discarded << " cards. Drawing deterministically.";

					// Deterministically draw replacements using the synchronized deck
					int cardsToDraw = discarded * 2;
					int prevCurrentPlayerIndex = currentPlayerIndex;
					currentPlayerIndex = rpk->playerIndex;
					for (int i = 0; i < cardsToDraw; ++i) {
						drawCard();
					}
					currentPlayerIndex = prevCurrentPlayerIndex;
				}

				// Record processed clientActionID for watchdog deduplication (host only)
				if (isHost() && rpk->clientActionID != 0) {
					uint32_t pid = rpk->playerID;
					if (pid < (uint32_t)(sizeof(lastProcessedActionID) / sizeof(lastProcessedActionID[0]))) {
						lastProcessedActionID[pid] = rpk->clientActionID;
						ofLogNotice("Network") << "Host: recorded lastProcessedActionID[" << pid << "]=" << lastProcessedActionID[pid];
					}
				}

				continue;
			}

			// Handle Amnesia choices: clients send selection to host; host applies and forwards
			if (header->type == PKT_AMNESIA_CHOICE) {
				AmnesiaChoicePacket * apk = (AmnesiaChoicePacket *)header;
				ofLogNotice("Network") << "AmnesiaChoice packet received: sender=" << apk->playerID << " targetPlayerIndex=" << apk->targetPlayerIndex << " count=" << (int)apk->numCardsToRemove;
				int tIdx = apk->targetPlayerIndex;
				if (tIdx >= 0 && tIdx < (int)players.size()) {
					// Host applies changes and forwards to clients
					if (isHost()) {
						// Apply removals authoritatively
						Player & p = players[tIdx];
						std::vector<int> indices;
						for (int i = 0; i < apk->numCardsToRemove && i < 8; ++i)
							indices.push_back(apk->selectedIndices[i]);
						std::sort(indices.begin(), indices.end(), std::greater<int>());
						for (int idx : indices) {
							if (idx >= 0 && idx < (int)p.deck.size()) {
								Card c = p.deck[idx];
								RemovedCardAnimation anim;
								anim.card = c;
								anim.startPos = glm::vec2(ofGetWidth() / 2, ofGetHeight() / 2); // best-effort placement
								anim.startTime = ofGetElapsedTimef();
								activeRemovedCardAnimations.push_back(anim);
								p.deck.erase(p.deck.begin() + idx);
							}
						}
						// Broadcast the same packet to clients so they can mirror the removals
						AmnesiaChoicePacket outPkt = *apk;
						outPkt.playerID = myLocalPlayerID;
						steamManager.sendPacket(&outPkt, sizeof(outPkt));
						ofLogNotice("Network") << "Host applied Amnesia and forwarded packet.";
					} else {
						// Client applying the host-forwarded packet (or possibly echo of own send) -- apply visuals
						Player & p = players[tIdx];
						std::vector<int> indices;
						for (int i = 0; i < apk->numCardsToRemove && i < 8; ++i)
							indices.push_back(apk->selectedIndices[i]);
						std::sort(indices.begin(), indices.end(), std::greater<int>());
						for (int idx : indices) {
							if (idx >= 0 && idx < (int)p.deck.size()) {
								Card c = p.deck[idx];
								RemovedCardAnimation anim;
								anim.card = c;
								anim.startPos = glm::vec2(ofGetWidth() / 2, ofGetHeight() / 2);
								anim.startTime = ofGetElapsedTimef();
								activeRemovedCardAnimations.push_back(anim);
								p.deck.erase(p.deck.begin() + idx);
							}
						}
						ofLogNotice("Network") << "Client applied Amnesia removals locally.";
					}
				}
			}

			// Handle TurnStart packets (Host -> Client): authoritative AP dice for starting player
			if (header->type == PKT_TURN_START) {
				TurnStartPacket * tpk = (TurnStartPacket *)header;
				ofLogNotice("Network") << "TurnStart packet received: player=" << tpk->currentPlayerIndex << " dice=" << (int)tpk->diceNum << " total=" << tpk->finalTotal;

				// Prevent duplicate processing: only ignore truly identical TurnStart
				// packets. Compare the player + authoritative finalTotal rather than
				// the local `globalTurnCounter` which may have been changed
				// optimistically on clients (causing legitimate authoritative
				// updates to be ignored). Use `continue` to keep processing other
				// queued packets instead of `return` which exits packet loop.
				static int lastProcessedTurnPlayer = -1;
				static uint32_t lastProcessedTurnSeq = 0;
				if (tpk->currentPlayerIndex == lastProcessedTurnPlayer && header->seq == lastProcessedTurnSeq) {
					ofLogNotice("Network") << "Ignoring duplicate TurnStart packet (player=" << tpk->currentPlayerIndex << " seq=" << header->seq << ")";
					continue;
				}
				lastProcessedTurnPlayer = tpk->currentPlayerIndex;
				lastProcessedTurnSeq = header->seq;

				if (tpk->currentPlayerIndex >= 0 && tpk->currentPlayerIndex < (int)players.size()) {
					// Set up turn state
					waitingForTurnStartFromHost = false;
					endTurnLocked = false;
					currentState = STATE_GAMEPLAY; // Transition to gameplay state
					currentPlayerIndex = tpk->currentPlayerIndex;
					// Clamp incoming dice count to the size of the arrays carried in the packet
					const int MAX_DICE_RESULTS = 8; // defensive: packet arrays are 8 long
					lastAPDiceNum = std::min((int)tpk->diceNum, MAX_DICE_RESULTS);
					lastAPDiceSides = (int)tpk->diceSides;

					// Complete turn setup (same as continueNewTurn does)
					Player & startingPlayer = players[currentPlayerIndex];
					ofLogNotice("Game") << "Player " << startingPlayer.playerID << "'s turn begins (from TurnStart).";
					ofLogNotice("Game") << "Client state: currentState=" << currentState << " myLocalPlayerID=" << myLocalPlayerID << " currentPlayerID=" << startingPlayer.playerID;
					hasDrawnCardsThisTurn = false;
					selectedCardIndex = -1;
					draggedCardIndex = -1;
					playerAction = NONE;
					clearHighlights();
					calculateTargetHighlights();
					playerVisualPos = gridToWorld(startingPlayer.x, startingPlayer.y);
					animationPath.clear();
					isPlayerAnimating = false;
					animatingPlayerIndex = -1;
					activeDiceRolls.clear();
					currentAP = 0;

					// CLIENT: Create visual dice rolls from host-provided results
					// This ensures the client sees the AP roll animation even though the host rolled it
					std::string diceLabel = "";
					if (startingPlayer.isWolf) {
						diceLabel = "Wolf AP Roll";
					} else if (startingPlayer.isHellhound) {
						diceLabel = "Hellhound AP Roll";
					} else if (startingPlayer.isDemon) {
						diceLabel = "Demon AP Roll";
					} else if (startingPlayer.isKobold) {
						diceLabel = "Kobold AP Roll";
					} else if (startingPlayer.isWallUnit) {
						diceLabel = startingPlayer.isMagicWallUnit ? "Magic Wall Unit AP" : "Wall Unit AP";
					} else if (startingPlayer.isKoboldKing) {
						diceLabel = "Kobold King AP";
					} else if (startingPlayer.isAssistant) {
						diceLabel = "Assistant AP (Coin)";
					} else if (startingPlayer.isFaerie) {
						diceLabel = "Faerie AP Roll";
					} else if (startingPlayer.isMinion) {
						diceLabel = getPlayerDisplayName(currentPlayerIndex) + " AP Roll";
					} else {
						diceLabel = "Player AP Roll";
					}

					currentDiceLabel = diceLabel;

					// Create DiceRoll objects with host-provided results
					int numDiceToCreate = std::min((int)tpk->diceNum, MAX_DICE_RESULTS);
					for (int i = 0; i < numDiceToCreate; ++i) {
						DiceRoll newRoll;
						newRoll.purpose = PURPOSE_AP;
						newRoll.sides = (int)tpk->diceSides;
						newRoll.rawResult = (int)tpk->rawResults[i];
						newRoll.result = (int)tpk->finalResults[i];
						newRoll.startTime = ofGetElapsedTimef();
						newRoll.isFinishedVisual = false;
						newRoll.associatedUnit = currentPlayerIndex;

						// Use shared helper to compute face rotation and add visual wobble/axis
						std::uniform_real_distribution<float> axisDist(-1.0f, 1.0f);
						glm::vec3 rndAxis(axisDist(visualRNG), axisDist(visualRNG), axisDist(visualRNG));
						if (glm::length(rndAxis) < 0.01f) rndAxis = glm::vec3(0, 1, 0);
						newRoll.rotationAxis = glm::normalize(rndAxis);

						std::uniform_real_distribution<float> wobbleDist(-25.0f, 25.0f);
						float wobbleAmount = wobbleDist(visualRNG);

						newRoll.finalQuat = getDiceFaceRotation(newRoll.sides, newRoll.rawResult, wobbleAmount);

						activeDiceRolls.push_back(newRoll);
					}

					// Advance gameplay RNG to mirror host's AP dice consumption so client
					// RNG state stays aligned with host for future deterministic rolls.
					if (isMultiplayer && isClient()) {
						for (int i = 0; i < numDiceToCreate; ++i) {
							(void)getGameRandom(1, lastAPDiceSides);
						}
					}

					int hostTotal = 0;
					for (int i = 0; i < numDiceToCreate; ++i) {
						hostTotal += (int)tpk->finalResults[i];
					}
					ofLogNotice("Game") << "TurnStart applied locally: player=" << currentPlayerIndex << " AP total=" << hostTotal;
					currentAP = hostTotal;
					if (startingPlayer.nextTurnAPBonus > 0) {
						currentAP += startingPlayer.nextTurnAPBonus;
						startingPlayer.nextTurnAPBonus = 0;
					}
					// Sync AP to player struct for multiplayer
					if (currentPlayerIndex >= 0 && currentPlayerIndex < (int)players.size()) {
						updatePlayerAP(players[currentPlayerIndex], currentAP);
					}

					// Clear transient defensive stats on turn START (clients must mirror host)
					// Tortoise form preserves defensive stats so only clear when not in tortoise form
					if (currentPlayerIndex >= 0 && currentPlayerIndex < (int)players.size()) {
						Player & sp = players[currentPlayerIndex];
						if (!sp.inTortoiseForm) {
							sp.block = 0;
							sp.holyBlock = 0;
							sp.ward = 0;
							sp.fortification = 0;
							sp.barrier = 0;
						}
					}

					// Mark dice as DEBUG to prevent recalculation when animation finishes
					for (auto & roll : activeDiceRolls) {
						if (roll.purpose == PURPOSE_AP && roll.associatedUnit == currentPlayerIndex) {
							roll.purpose = PURPOSE_DEBUG;
						}
					}
				}
				continue; // Done with this packet
			}

			if (header->type == PKT_SNAPSHOT_BEGIN) {
				SnapshotBeginPacket * bp = (SnapshotBeginPacket *)header;
				incomingSnapshotId = bp->snapshotId;
				incomingSnapshotExpectedSize = bp->totalSize;
				incomingSnapshotReceivedSize = 0;
				incomingSnapshotBuffer.assign(bp->totalSize, '\0');
				ofLogNotice("Network") << "Snapshot begin (id=" << incomingSnapshotId << ", bytes=" << incomingSnapshotExpectedSize << ")";
				continue;
			}

			if (header->type == PKT_SNAPSHOT_CHUNK) {
				SnapshotChunkPacket * cp = (SnapshotChunkPacket *)header;
				if (cp->snapshotId == incomingSnapshotId && !incomingSnapshotBuffer.empty()) {
					uint32_t end = cp->offset + cp->chunkSize;
					if (end <= incomingSnapshotBuffer.size()) {
						memcpy(&incomingSnapshotBuffer[cp->offset], cp->data, cp->chunkSize);
						incomingSnapshotReceivedSize += cp->chunkSize;
					}
				}
				continue;
			}

			if (header->type == PKT_SNAPSHOT_END) {
				SnapshotEndPacket * ep = (SnapshotEndPacket *)header;
				if (ep->snapshotId == incomingSnapshotId && incomingSnapshotExpectedSize > 0) {
					ofLogNotice("Network") << "Snapshot end (id=" << incomingSnapshotId << ")";
					applySnapshotString(incomingSnapshotBuffer);
					// Clear waiting flag if we had requested this snapshot
					waitingForSnapshot = false;
					addGameLog("Recovered game state from host snapshot");
					spawnFloatingText(glm::vec3(0, 5, 0), "Snapshot Applied", ofColor::green);
					incomingSnapshotBuffer.clear();
					incomingSnapshotExpectedSize = 0;
					incomingSnapshotReceivedSize = 0;
				}
				continue;
			}

			if (header->type == PKT_SNAPSHOT_REQUEST) {
				SnapshotRequestPacket * rp = (SnapshotRequestPacket *)header;
				ofLogNotice("Network") << "Snapshot request received from player " << rp->playerID << " requestedTurn=" << rp->requestedTurn;
				if (isHost()) {
					// Send the authoritative snapshot to the requesting client
					sendSnapshotToClient();
					ofLogNotice("Network") << "Host: Sent authoritative snapshot to client.";
				}
				continue;
			}

			if (header->type == PKT_HANDSHAKE) {
				HandshakePacket * pkt = (HandshakePacket *)header;
				ofLogNotice("Net") << "Handshake received: type=" << (int)pkt->type << " playerID=" << pkt->playerID << " seq=" << pkt->seq << " seed=" << pkt->seed << " platform=" << MAGEFIGHT_PLATFORM;
				if (hasReceivedHandshake) {
					// The map seed must never change during a session. If we receive a later
					// handshake with a different seed, ignore it and log an error.
					if (pkt->seed != currentMapSeed) {
						ofLogError("Net") << "Handshake seed changed after initialization! previous=" << currentMapSeed << " new=" << pkt->seed << " -- IGNORING new seed.";
					} else {
						ofLogNotice("Net") << "Ignoring duplicate handshake (already initialized).";
					}
					continue;
				}

				// FIX: Seed the gameplay RNG and store map seed so derived draft RNG matches the host
				gameplayRNG.seed(pkt->seed);
				currentMapSeed = pkt->seed;
				hasReceivedHandshake = true;
				gameplaySeededByHost = true;
				handshakeRequestInterval = 1.0f;
				isMultiplayer = true;
				myLocalPlayerID = 1;

				// Get Steam names
				player0SteamName = steamManager.getOpponentName(); // Host is opponent for client
				player1SteamName = steamManager.getLocalPlayerName(); // Client is player 1

				// Only initialize game if we're not already in a game (reconnection case)
				if (currentState == STATE_MAIN_MENU) {
					// Initialize game state for the client now that we have the seed.
					// NOTE: Do NOT force a state transition here; the host will
					// send authoritative DraftState/Initiative packets when it's
					// time to move into drafting or gameplay. Forcing a leave
					// from the main menu caused clients to miss the proper
					// sequence on reconnects.
					ofLogNotice("Network") << "Client: Handshake received. Initializing game (seed=" << currentMapSeed << ") - staying in main menu until host signals next state.";
					setupGame();

					// Client: notify host that we've finished local setup and are ready to see the board
					if (!clientSentReady) {
						ClientReadyPacket r = {};
						r.type = PKT_CLIENT_READY;
						r.playerID = myLocalPlayerID;
						r.ready = 1;
						steamManager.sendPacket(&r, sizeof(r));
						clientSentReady = true;
						ofLogNotice("Network") << "Client: Sent ClientReady to host.";
					}
				} else {
					ofLogNotice("Network") << "Client: Handshake received on reconnect. Staying in current game state: " << currentState;
				}
				continue;
			}
			// Handle ClientReady: Host receives client confirmation that it's ready to start
			if (header->type == PKT_CLIENT_READY && buffer.size() >= sizeof(ClientReadyPacket)) {
				ClientReadyPacket * cr = (ClientReadyPacket *)header;
				ofLogNotice("Network") << "ClientReady received from playerID=" << cr->playerID;
				if (isHost() && hostWaitingForClientsReady) {
					clientsReady.insert(cr->playerID);
					// For 2-player matches, start when we have any client ready
					if (!clientsReady.empty()) {
						ofLogNotice("Network") << "All clients ready - starting initiative phase.";
						hostWaitingForClientsReady = false;
						startInitiativePhase();
					}
				}
				continue;
			}
			if (header->type == PKT_ACTION) {
				ActionPacket * pkt = (ActionPacket *)header;

				// Check if this is a movement action (cardIndex < 0) or card play (cardIndex >= 0)
				if (pkt->cardIndex < 0) {
					// MOVEMENT ACTION: Receive opponent's movement and apply it locally
					ofLogNotice("Network") << "Received movement from opponent to (" << pkt->targetX << "," << pkt->targetY << ") with AP=" << pkt->cost;
					int actorIndex = (pkt->actorIndex >= 0 && pkt->actorIndex < (int)players.size()) ? pkt->actorIndex : -1;
					if (actorIndex < 0) {
						for (size_t i = 0; i < players.size(); i++) {
							if (static_cast<uint32_t>(players[i].playerID) == pkt->playerID) {
								actorIndex = (int)i;
								break;
							}
						}
					}
					if (actorIndex >= 0) {
						applyMovement(actorIndex, pkt->targetX, pkt->targetY, pkt->cost, nullptr);
						ofLogNotice("Network") << "Applied movement for player " << pkt->playerID << " to (" << pkt->targetX << "," << pkt->targetY << ")";
						// Host: send ACK for movement so client stops resending
						if (isHost()) {
							AckPacket ack = {};
							ack.type = PKT_ACK;
							ack.playerID = myLocalPlayerID;
							ack.ackSeq = pkt->clientActionID; // echo clientActionID
							ack.ackType = PKT_ACTION;
							steamManager.sendPacket(&ack, sizeof(ack));
							ofLogNotice("NetTrace") << "Host: sent ACK for Movement clientActionID=" << ack.ackSeq;
						}
					}
				} else {
					// CARD PLAY ACTION: Execute card play
					ofLogNotice("Sync") << "Opponent played card index: " << pkt->cardIndex;
					// Special-case: Shell Spike pseudo-action (cardIndex == -2)
					if (pkt->cardIndex == -2 && std::string(pkt->cardName) == "Shell Spike") {
						// Find the target at the provided coordinates and apply physical damage
						Player * target = nullptr;
						for (auto & p : players) {
							if (p.x == pkt->targetX && p.y == pkt->targetY) {
								target = &p;
								break;
							}
						}
						if (target) {
							applyDamageTo(*target, 3, DAMAGE_PHYSICAL, pkt->actorIndex);
							ofLogNotice("Network") << "Applied Shell Spike damage from network packet to unit at (" << pkt->targetX << "," << pkt->targetY << ")";
						} else {
							ofLogWarning("Network") << "Shell Spike packet target not found at (" << pkt->targetX << "," << pkt->targetY << ")";
						}
						continue;
					}
					// EXECUTE REMOTE MOVE
					// Because gameplayRNG is synced, if this card causes a dice roll,
					// it will roll the exact same number here as it did on the opponent's screen.
					executeAction(*pkt);

					// Host: send ACK back to originating client so they stop resending
					if (isHost()) {
						AckPacket ack = {};
						ack.type = PKT_ACK;
						ack.playerID = myLocalPlayerID;
						// If client provided a clientActionID, echo it so the client can match ACKs
						ack.ackSeq = pkt->clientActionID;
						ack.ackType = PKT_ACTION;
						steamManager.sendPacket(&ack, sizeof(ack));
						ofLogNotice("NetTrace") << "Host: sent ACK for ActionPacket clientActionID=" << ack.ackSeq;
					}
				}
			} else if (header->type == PKT_DRAW_CARDS) {
				DrawCardsPacket * dcpkt = (DrawCardsPacket *)header;

				// --- MULTIPLAYER FIX ---
				// If the host receives a DrawCards packet from a client, ACK it so the client
				// knows the host processed it. Also ignore the echo locally if it's our own draw.
				if (isHost()) {
					AckPacket ack = {};
					ack.type = PKT_ACK;
					ack.playerID = myLocalPlayerID;
					ack.ackSeq = dcpkt->clientActionID; // echo clientActionID
					ack.ackType = PKT_DRAW_CARDS;
					steamManager.sendPacket(&ack, sizeof(ack));
					ofLogNotice("NetTrace") << "Host: sent ACK for DrawCards clientActionID=" << ack.ackSeq;
				}

				// If this DrawCards was sent by ourselves, ignore the echo to avoid double-processing.
				if (dcpkt->playerID == static_cast<uint32_t>(myLocalPlayerID)) {
					ofLogNotice("Network") << "Ignoring own DrawCards echo for playerID=" << dcpkt->playerID;
					continue;
				}

				// Host-side deduplication: ignore retransmitted watchdog packets already processed
				if (isHost() && dcpkt->clientActionID != 0) {
					uint32_t pid = dcpkt->playerID;
					if (pid < (uint32_t)(sizeof(lastProcessedActionID) / sizeof(lastProcessedActionID[0])) && dcpkt->clientActionID <= lastProcessedActionID[pid]) {
						ofLogNotice("Network") << "Host: Ignoring duplicate DrawCards clientActionID=" << dcpkt->clientActionID << " from playerID=" << pid;
						continue;
					}
				}

				// Host-side validation: only allow draws from the active player
				if (isHost()) {
					if (currentPlayerIndex < 0 || currentPlayerIndex >= (int)players.size()) {
						ofLogWarning("Network") << "Host: Received DrawCards but no active player. Ignoring.";
						continue;
					}
					int activePlayerID = players[currentPlayerIndex].playerID;
					if (static_cast<int>(dcpkt->playerID) != activePlayerID) {
						ofLogWarning("Network") << "Host: Ignoring DrawCards from non-active player (player=" << dcpkt->playerID << ") active=" << activePlayerID;
						continue;
					}
					// Prevent clients from drawing on behalf of minion actors
					if (players[currentPlayerIndex].isMinion) {
						ofLogWarning("Network") << "Host: Active actor is a minion; ignoring client DrawCards.";
						continue;
					}
				}
				ofLogNotice("Network") << "Received DrawCards from opponent: playerIdx=" << dcpkt->playerIndex << " num=" << dcpkt->numCards;

				// UI Flag for opponent drawing
				if (isMultiplayer) {
					opponentHasDrawnCardsThisTurn = true;
				}

				// Find the target player (Authoritative index from packet)
				int targetPlayerIndex = dcpkt->playerIndex;

				// Fallback search if index is invalid
				if (targetPlayerIndex < 0 || targetPlayerIndex >= (int)players.size()) {
					for (size_t i = 0; i < players.size(); ++i) {
						if (static_cast<uint32_t>(players[i].playerID) == dcpkt->playerID && !players[i].isMinion) {
							targetPlayerIndex = (int)i;
							break;
						}
					}
				}

				if (targetPlayerIndex >= 0 && targetPlayerIndex < (int)players.size()) {
					Player & p = players[targetPlayerIndex];

					// Deterministic Sync: Move cards from Deck -> Hand based on local state
					// (We assume deck order is already synced via shared Seed or Shuffle packets)
					for (int i = 0; i < dcpkt->numCards; ++i) {

						// Handle empty deck case (Reshuffle logic should have been triggered by Shuffle packet,
						// but we check discard here just in case to prevent crash). To avoid a draw-vs-shuffle
						// race, apply the next pending shuffle nonce for this player (if any) before moving
						// cards from discard -> deck so the client never draws from an unshuffled pile.
						if (p.deck.empty()) {
							if (!p.discardPile.empty()) {
								int pid = targetPlayerIndex;
								// If we're a client and have a pending authoritative shuffle nonce for this player,
								// apply it to the discard pile before making it the new deck.
								if (isClient() && pid >= 0) {
									auto it = pendingShuffleNonces.find(pid);
									if (it != pendingShuffleNonces.end() && !it->second.empty()) {
										uint32_t nonceToApply = it->second.front();
										it->second.pop_front();
										std::mt19937 shuffleRng(nonceToApply);
										deterministic_shuffle(p.discardPile, shuffleRng);
										lastAppliedShuffleNonce[pid] = nonceToApply;
										ofLogNotice("Network") << "Client: Applied deferred shuffle nonce for player " << pid << " before drawing (nonce=" << nonceToApply << ")";
									} else {
										// No authoritative nonce available: fall back to local shuffle to keep UI consistent.
										shuffleGameVector(p.discardPile, targetPlayerIndex);
										// Spawn shuffle animation for this player's deck (local fallback)
										{
											ShuffleAnimation s;
											s.playerIndex = pid;
											s.deckRect = (pid == 0) ? p0_deckRect : p1_deckRect;
											s.startTime = ofGetElapsedTimef();
											s.duration = 0.9f;
											activeShuffleAnimations.push_back(s);
										}
										ofLogNotice("Network") << "Applied local fallback shuffle for player " << targetPlayerIndex << " before drawing.";
									}
									// Move shuffled discard into deck
									p.deck = p.discardPile;
									p.discardPile.clear();
								} else {
									break; // No cards left to draw
								}
							}

							if (!p.deck.empty()) {
								// Pop from back of deck (Deterministic)
								Card newCard = p.deck.back();
								p.deck.pop_back();
								newCard.drawnThisTurn = true;
								// Commit to opponent's hand immediately (visual-only animation)
								p.hand.push_back(newCard);
								p.hand.back().currentScale = 1.5f;
								p.hand.back().targetScale = 1.5f;
								p.hand.back().isAnimating = true;

								// --- Animation Setup (Opponent draws appear from Top Right, quick, above hand) ---
								DrawCardAnimation anim;
								anim.card = newCard;
								anim.startTime = ofGetElapsedTimef();
								anim.duration = 0.36f;
								anim.ownerIndex = targetPlayerIndex;
								anim.toMinionHand = false; // not a minion
								float scale = ofGetHeight() / 1080.0f;
								float staticUICardWidth = (120 * 1.3f) * scale;
								float staticUICardHeight = ((120 * (585.0f / 409.0f)) * 1.3f) * scale;
								float discardX = ofGetWidth() - staticUICardWidth - (30 * scale);
								float discardY = 40 * scale;
								float deckX = discardX;
								float deckY = discardY + staticUICardHeight + (40 * scale);
								// Offset simultaneous opponent draws so multiple flying cards are visible
								int animatingToThis = 0;
								for (const auto & a : activeDrawCardAnimations) {
									if (a.ownerIndex == targetPlayerIndex && !a.toMinionHand) animatingToThis++;
								}
								float uiScaleLocal = ofGetHeight() / 1080.0f;
								float perCardOffset = std::clamp(84.0f * uiScaleLocal, 36.0f, 160.0f);
								float offsetPixels = animatingToThis * perCardOffset;
								anim.startPos = glm::vec3(deckX + staticUICardWidth / 2 + offsetPixels, deckY + staticUICardHeight / 2, 0);
								anim.startIsScreenSpace = true; // ensure UI-origin animation uses screen coords
								anim.currentPos = glm::vec2(anim.startPos.x, anim.startPos.y);
								// compute final hand index as if the card were present (hand.size + 1)
								// but also account for other ongoing draw animations targeting this player's hand
								size_t numCards = p.hand.size() + 1 + animatingToThis;
								float handCenterY = ofGetHeight() - 160;
								float handBaseCardWidth = 120;
								float handAreaWidth = ofGetWidth() * 0.6f;
								float totalCardWidths = numCards * handBaseCardWidth;
								float padding = (numCards > 1) ? (handAreaWidth - totalCardWidths) / (numCards - 1) : 0;
								padding = std::min(padding, 16.0f);
								float totalHandWidth = (numCards * handBaseCardWidth) + ((numCards - 1) * padding);
								float startX = (ofGetWidth() - totalHandWidth) / 2.0f;
								float cardCenterX = startX + (numCards - 1) * (handBaseCardWidth + padding) + (handBaseCardWidth / 2.0f);
								anim.targetPos = glm::vec2(cardCenterX, handCenterY);
								anim.endPos = anim.startPos;
								anim.currentPos = glm::vec2(anim.startPos.x, anim.startPos.y);
								anim.currentScale = 1.0f;
								anim.commitOnFinish = false; // card already pushed to hand above
								activeDrawCardAnimations.push_back(anim);
								ofLogNotice("Network") << "Opponent (Player " << targetPlayerIndex << ") drew " << newCard.name;
							}
						}
					}
					continue;
				} else if (header->type == PKT_EARTHQUAKE_BEGIN) {
					EarthquakeBeginPacket * eb = (EarthquakeBeginPacket *)header;
					ofLogNotice("Network") << "Received EarthquakeBegin: units=" << eb->numUnits;
					// Initialize earthquake units on client to match host directions
					earthquakeUnits.clear();
					int n = std::min((int)eb->numUnits, (int)16);
					for (int i = 0; i < n; ++i) {
						EarthquakeState st;
						st.playerIndex = eb->playerIndex[i];
						st.startGrid = { players[st.playerIndex].x, players[st.playerIndex].y };
						st.visualPos = gridToWorld(st.startGrid.x, st.startGrid.y);
						st.isMoving = true;
						st.crashed = false;
						st.tilesToMove = 0;
						st.originalDistance = 0;
						st.diceIndex = -1;
						st.direction = { (int)eb->dirX[i], (int)eb->dirY[i] };
						earthquakeUnits.push_back(st);
					}
					isEarthquakeActive = true;
					isEarthquakeDiceRolling = true;
					isEarthquakeAnimatingStep = false;
					earthquakeDiceAssignCounter = 0;
					isWaitingForEarthquakeBegin = false;

					// Advance gameplay RNG to mirror host's direction choices and upcoming
					// earthquake distance rolls so client RNG sequence stays aligned.
					// Host consumes one dirDist(0..3) per unit, then one 1..4 distance roll
					// per unit via getGameRandom(1,4) inside startDiceRoll.
					if (isMultiplayer && isClient()) {
						for (int i = 0; i < n; ++i) {
							(void)getGameRandom(0, 3);
						}
						for (int i = 0; i < n; ++i) {
							(void)getGameRandom(1, 4);
						}
					}
					continue;
				} else if (header->type == PKT_CARD_ACTION_BEGIN) {
					CardActionBeginPacket * pkt = (CardActionBeginPacket *)header;
					ofLogNotice("Network") << "Received CardActionBegin from opponent: cardType=" << pkt->cardType;

					// This is primarily for the client to apply host-authoritative effects.
					if (isClient()) {
						Player * target = getPlayer(pkt->actorIndex);
						if (target) {
							glm::vec3 tPos = gridToWorld(target->x, target->y);
							int extraDamage = pkt->param0;

							switch (pkt->cardType) {
							case CARD_SHOCK:
								applyDamageTo(*target, extraDamage, DAMAGE_ELECTRIC, -1); // -1 attacker, as it's an effect
								target->isParalyzed = true;
								target->paralysisHeadsCount = 0;
								spawnFloatingText(tPos + glm::vec3(0, 0.6f, 0), "-" + ofToString(extraDamage) + " Electric", ofColor::orange);
								spawnFloatingText(tPos + glm::vec3(0, 1.0f, 0), "PARALYZED!", ofColor::yellow);
								break;
							case CARD_FLAME_HIT:
								applyDamageTo(*target, extraDamage, DAMAGE_FIRE, -1);
								target->onFire = true;
								spawnFloatingText(tPos + glm::vec3(0, 0.6f, 0), "-" + ofToString(extraDamage) + " Fire", ofColor::red);
								spawnFloatingText(tPos + glm::vec3(0, 1.0f, 0), "ON FIRE!", ofColor::orange);
								break;
							case CARD_ADD_POISON:
								applyDamageTo(*target, extraDamage, DAMAGE_POISON, -1);
								target->isPoisoned = true;
								target->poisonReduction = 0;
								spawnFloatingText(tPos + glm::vec3(0, 0.6f, 0), "-" + ofToString(extraDamage) + " Poison", ofColor::green);
								spawnFloatingText(tPos + glm::vec3(0, 1.0f, 0), "POISONED!", ofColor::green);
								break;
							default:
								break;
							}
						}
					}
					continue;
				} else if (header->type == PKT_DICE_ROLL) {
					DiceRollPacket * drp = (DiceRollPacket *)header;
					ofLogNotice("Network") << "Received DiceRollPacket: " << (int)drp->numDice << "d" << (int)drp->sides << " label=" << drp->label;

					// Ignore initiative debug rolls (we roll deterministically locally)
					if (drp->purpose == PURPOSE_DEBUG && currentState == STATE_INITIATIVE_ROLL) {
						ofLogNotice("Network") << "Ignoring incoming initiative DiceRollPacket (client rolls locally).";
						continue;
					}

					// Ignore AP DiceRollPackets since AP visuals are created from PKT_TURN_START
					if (drp->purpose == PURPOSE_AP) {
						ofLogNotice("Network") << "Ignoring incoming AP DiceRollPacket (use TurnStart for AP visuals).";
						continue;
					}

					// Recreate the dice rolls on opponent's screen for visual display
					for (int i = 0; i < drp->numDice && i < 8; i++) {
						DiceRoll newRoll;
						newRoll.purpose = (DicePurpose)drp->purpose;
						newRoll.sides = drp->sides;
						newRoll.startTime = ofGetElapsedTimef();
						// FIX: Use the ownerIndex provided by the packet — playCard/startDiceRoll now assigns owner correctly.
						newRoll.associatedUnit = drp->ownerIndex;
						newRoll.rawResult = drp->rawResults[i];
						newRoll.result = drp->finalResults[i];

						// Generate visual rotation (using visualRNG for unsync'd visuals)
						std::uniform_real_distribution<float> axisDist(-1.0f, 1.0f);
						glm::vec3 rndAxis(axisDist(visualRNG), axisDist(visualRNG), axisDist(visualRNG));
						if (glm::length(rndAxis) < 0.01f) rndAxis = glm::vec3(0, 1, 0);
						newRoll.rotationAxis = glm::normalize(rndAxis);

						// Generate wobble
						std::uniform_real_distribution<float> wobbleDist(-25.0f, 25.0f);
						float wobbleAmount = wobbleDist(visualRNG);

						// Compute a proper face rotation matching the face to camera
						newRoll.finalQuat = getDiceFaceRotation(newRoll.sides, newRoll.rawResult, wobbleAmount);

						// De-duplication: if we recently created a matching local roll, skip adding this networked duplicate.
						bool isDuplicate = false;
						for (auto & existing : activeDiceRolls) {
							if (existing.purpose == newRoll.purpose && existing.sides == newRoll.sides && existing.rawResult == newRoll.rawResult && existing.result == newRoll.result && existing.associatedUnit == newRoll.associatedUnit) {
								if (ofGetElapsedTimef() - existing.startTime < 0.5f) {
									isDuplicate = true;
									break;
								}
							}
						}
						if (!isDuplicate) {
							activeDiceRolls.push_back(newRoll);
						} else {
							ofLogNotice("Network") << "Ignored duplicate DiceRollPacket entry: " << (int)newRoll.rawResult << " (purpose=" << (int)newRoll.purpose << ")";
						}
					}

					// Set the label
					if (strlen(drp->label) > 0) {
						currentDiceLabel = drp->label;
					}

					continue;
				} else if (header->type == PKT_PLACE_SUMMONED_MINION) {
					PlaceSummonedMinionPacket * psk = (PlaceSummonedMinionPacket *)header;
					ofLogNotice("Network") << "Received PlaceSummonedMinion: type=" << (int)psk->minionType << " owner=" << psk->ownerPlayerID << " target=(" << psk->targetX << "," << psk->targetY << ")";
					int tx = psk->targetX;
					int ty = psk->targetY;
					if (tx >= 0 && tx < BOARD_WIDTH && ty >= 0 && ty < BOARD_HEIGHT) {
						if (!board[tx][ty].hasPlayer) {
							// Create the minion locally to mirror host (use authoritative HP/AP when provided)
							Player minion;
							minion.playerID = 300 + (int)players.size();
							minion.x = tx;
							minion.y = ty;
							// Use authoritative values if present in packet, otherwise fall back to defaults
							minion.maxHealth = (psk->minionHP > 0) ? psk->minionHP : 1;
							minion.health = minion.maxHealth;
							minion.ap = (psk->minionAP >= 0) ? psk->minionAP : 0;
							minion.isMinion = true;
							// Decode minion type into flags so clients reconstruct the correct model/behavior
							switch (psk->minionType) {
							case 1: // Kobold
								minion.isKobold = true;
								minion.isSkeleton = false;
								break;
							case 2: // Wolf
								minion.isWolf = true;
								break;
							case 3: // Hellhound
								minion.isHellhound = true;
								break;
							case 4: // Demon
								minion.isDemon = true;
								break;
							case 5: // Kobold King
								minion.isKoboldKing = true;
								break;
							case 6: // Assistant
								minion.isAssistant = true;
								break;
							case 7: // Faerie
								minion.isFaerie = true;
								minion.minionTexture = nullptr; // Defensive: faerie uses model, not texture pointer
								ofLogNotice("Network") << "Created Faerie minion (network sync) at (" << tx << "," << ty << ")";
								break;
							case 8: // Golem
								minion.isGolem = true;
								break;
							case 9: // Skeleton / Raise Dead
								minion.isSkeleton = true;
								minion.hasRegeneration = true;
								break;
							case 10: // Wall Unit
								minion.isWallUnit = true;
								minion.isMagicWallUnit = false;
								break;
							case 11: // Magic Wall Unit
								minion.isWallUnit = true;
								minion.isMagicWallUnit = true;
								break;
							default:
								break;
							}
							minion.ownerID = psk->ownerPlayerID;
							minion.summonedOnTurnCycle = globalTurnCounter;
							minion.summonOrder = ++nextSummonOrder;
							// Build basic kobold deck
							Card hb, pu, callCard;
							for (const auto & c : allCards) {
								if (c.name == "Hand Block") hb = c;
								if (c.name == "Punch") pu = c;
								if (c.type == CARD_CALL_FOR_KOBOLDS) callCard = c;
							}
							minion.deck = { hb, hb, pu, callCard };
							// Place on board and add
							board[tx][ty].hasPlayer = true;
							players.push_back(minion);
							int newIdx = (int)players.size() - 1;

							// Initialize visual position for remote-synced minion
							players[newIdx].visualPos = gridToWorld(players[newIdx].x, players[newIdx].y);
							ofLogNotice("Network") << "Initialized visualPos for remote minion idx=" << newIdx << " pos=" << players[newIdx].visualPos.x << "," << players[newIdx].visualPos.y << "," << players[newIdx].visualPos.z;
							ofLogNotice("Network") << "Placed summoned minion (client-side): idx=" << newIdx << " type=" << (int)psk->minionType << " owner=" << minion.ownerID << " HP=" << minion.maxHealth << " AP=" << minion.ap;
							shuffleGameVector(players[newIdx].deck, newIdx);
							checkKeyPickupAndDraftAfterSummon(minion.x, minion.y, minion.ownerID);
							// Re-sort turn order to match host
							int currentID = players[currentPlayerIndex].playerID;
							std::sort(players.begin(), players.end(), [](const Player & a, const Player & b) {
								int ownerA = a.isMinion ? a.ownerID : a.playerID;
								int ownerB = b.isMinion ? b.ownerID : b.playerID;
								if (ownerA != ownerB) return ownerA < ownerB;
								if (a.isMinion && !b.isMinion) return true;
								if (!a.isMinion && b.isMinion) return false;
								return a.summonOrder < b.summonOrder;
							});
							for (size_t i = 0; i < players.size(); i++) {
								if (players[i].playerID == currentID) {
									currentPlayerIndex = i;
									break;
								}
							}
							invalidateTargetCache();
							ofLogNotice("Network") << "Placed remote kobold at (" << tx << "," << ty << ")";
							// If this was part of a remote placement sequence, decrement remaining
							if (remoteIsPlacingKobolds && psk->minionType == 1) {
								remoteKoboldsRemaining = std::max(0, remoteKoboldsRemaining - 1);
								ofLogNotice("Network") << "Remote kobolds remaining=" << remoteKoboldsRemaining;
								if (remoteKoboldsRemaining <= 0) {
									remoteIsPlacingKobolds = false;
									remoteKoboldPlacementSourceX = -1;
									remoteKoboldPlacementSourceY = -1;
								}
							}

							// If we're a client waiting for the host's TurnStart and our restored
							// currentPlayerIndex now points to a minion (possible due to sorting),
							// advance to the next non-minion so the client doesn't think it's a minion's turn.
							if (isClient() && waitingForTurnStartFromHost && currentPlayerIndex >= 0 && currentPlayerIndex < (int)players.size() && players[currentPlayerIndex].isMinion) {
								bool found = false;
								for (int off = 1; off < (int)players.size(); ++off) {
									int idx = (currentPlayerIndex + off) % (int)players.size();
									if (!players[idx].isMinion) {
										currentPlayerIndex = idx;
										found = true;
										break;
									}
								}
								if (found) ofLogNotice("Network") << "Adjusted client currentPlayerIndex to non-minion after remote summon: " << players[currentPlayerIndex].playerID;
							}
						}
						// If a minion already exists at this tile (client predicted placement), update its authoritative stats
					} else {
						for (auto & p : players) {
							if (p.x == tx && p.y == ty && p.isMinion) {
								p.maxHealth = (psk->minionHP > 0) ? psk->minionHP : p.maxHealth;
								p.health = p.maxHealth;
								p.ap = (psk->minionAP >= 0) ? psk->minionAP : p.ap;
								// Ensure Magic Wall status is synced
								if (psk->minionType == 11)
									p.isMagicWallUnit = true;
								else if (psk->minionType == 10)
									p.isMagicWallUnit = false;
								break;
							}
						}
					}
				}
			}
			continue;
		}
		if (header->type == PKT_END_TURN) {
			ofLogNotice("Net") << "Opponent ended turn.";

			// Host-side validation: only the currently active player may end the turn.
			if (isHost()) {
				if (currentPlayerIndex >= 0 && currentPlayerIndex < (int)players.size()) {
					int activePlayerID = players[currentPlayerIndex].playerID;
					if (static_cast<int>(header->playerID) != activePlayerID) {
						ofLogWarning("Network") << "Ignoring END_TURN from non-active player (player=" << header->playerID << ") active=" << activePlayerID;
						continue;
					}
				}
			}
			// CLIENT: Always wait for host's TurnStart packet (contains authoritative dice)
			// Never roll dice locally for any turn - host controls all RNG
			if (isClient()) {
				ofLogNotice("Network") << "CLIENT FIX ACTIVE: Waiting for host TurnStart packet (will NOT roll dice locally).";
				waitingForTurnStartFromHost = true;
				// Apply opponent hand cleanup locally so their hand disappears on our screen
				// NOTE: Do NOT clear defensive stats (block, ward, barrier, holyBlock, fortification) here
				// All defensive stats persist until the opponent's next turn starts in startNewTurn()
				for (size_t i = 0; i < players.size(); i++) {
					Player & opp = players[i];
					if (opp.playerID == static_cast<int>(header->playerID) && !opp.isMinion) {
						opp.discardPile.insert(opp.discardPile.end(), opp.hand.begin(), opp.hand.end());
						opp.hand.clear();
						opp.discardPile.insert(opp.discardPile.end(), opp.playedCardsPile.begin(), opp.playedCardsPile.end());
						opp.playedCardsPile.clear();
						break;
					}
				}
				// Don't call startNewTurn() - let PKT_TURN_START handle it
			} else {
				// Host: can proceed with local turn start
				ofLogNotice("Network") << "Host: Processing END_TURN, calling startNewTurn()";
				startNewTurn();

				// Note: TurnStart packet is now sent from the update loop after dice finish
				// (see line ~3914 where it checks allDiceFinished and sends TurnStartPacket)
				// This ensures the packet contains actual rolled results from continueNewTurn()
			}
		} else if (header->type == PKT_CHECKSUM_CHECK) {
			ChecksumPacket * pkt = (ChecksumPacket *)header;
			if (isClient() && waitingForTurnStartFromHost) continue;
			if (skipChecksumValidation) continue;

			long long mySum = calculateChecksum();

			if (mySum != pkt->checksum) {
				ofLogError("Net") << "DESYNC DETECTED! Rewinding to start of turn...";

				if (isHost()) {
					// 1. Host rewinds ITSELF to the start of the turn
					if (!turnStartBackupSnapshot.empty()) {
						applySnapshotString(turnStartBackupSnapshot);
						ofLogNotice("Network") << "Host rewound local state.";
					}

					// 2. Host forcefully pushes this restored state to the Client
					sendSnapshotToClient();

					// 3. Visual notification
					spawnFloatingText(glm::vec3(0, 5, 0), "SYNC ERROR: TURN REWOUND", ofColor::red);
				} else {
					// Client detected a desync on its own end. Request the host to fix it.
					SnapshotRequestPacket req = {};
					req.type = PKT_SNAPSHOT_REQUEST;
					req.playerID = myLocalPlayerID;
					req.requestedTurn = pkt->turnNumber;
					steamManager.sendPacket(&req, sizeof(req));

					waitingForSnapshot = true;
					spawnFloatingText(glm::vec3(0, 5, 0), "Requesting Resync...", ofColor::yellow);
				}
			} else {
				// If checksums match mid-turn, update the backup so we don't lose progress on a good move!
				if (isHost()) {
					turnStartBackupSnapshot = buildSnapshotString();
				}
			}
		} else if (header->type == PKT_KEY_PICKUP) {
			KeyPickupPacket * kpkt = (KeyPickupPacket *)header;
			ofLogNotice("Network") << "KeyPickup packet received: player=" << kpkt->playerIndex << " class=" << kpkt->classTier << " pos=(" << kpkt->keyX << "," << kpkt->keyY << ")";

			// CLIENT: Apply key pickup from host
			if (isClient()) {
				// Remove the key from client's floatingKeyInstances
				for (size_t k = 0; k < floatingKeyInstances.size(); ++k) {
					FloatingKey & fk = floatingKeyInstances[k];
					if (fk.pos.x == kpkt->keyX && fk.pos.y == kpkt->keyY) {
						floatingKeyInstances.erase(floatingKeyInstances.begin() + k);
						break;
					}
				}

				// Schedule in-game draft (don't open UI immediately) so the summoned minion's
				// HP roll / minion UI can appear first.
				pendingKeyDraftAccept = true;
				// Prefer a mapping that preserves minion-targeting: if the host provided
				// an actor index that refers to a minion currently sitting on the key
				// tile, prefer that mapping. Otherwise prefer the stable playerID mapping
				// and finally fallback to the raw actor index.
				pendingKeyDraftPlayer = -1;
				pendingKeyDraftPlayerID = -1;

				// 1) Prefer the local minion sitting on the key tile, if any
				for (int i = 0; i < (int)players.size(); ++i) {
					if (players[i].isMinion && players[i].x == kpkt->keyX && players[i].y == kpkt->keyY) {
						pendingKeyDraftPlayer = i;
						pendingKeyDraftPlayerID = players[i].playerID;
						break;
					}
				}

				// 2) If not resolved yet, prefer stable playerID mapping (authoritative)
				if (pendingKeyDraftPlayer == -1 && kpkt->playerID >= 0) {
					for (int i = 0; i < (int)players.size(); ++i) {
						if (players[i].playerID == kpkt->playerID) {
							pendingKeyDraftPlayer = i;
							pendingKeyDraftPlayerID = kpkt->playerID;
							break;
						}
					}
				}

				// 3) Fallback: use the provided actor index (may be out-of-range)
				if (pendingKeyDraftPlayer == -1) {
					pendingKeyDraftPlayer = kpkt->playerIndex;
					if (kpkt->playerIndex >= 0 && kpkt->playerIndex < (int)players.size())
						pendingKeyDraftPlayerID = players[kpkt->playerIndex].playerID;
					else
						pendingKeyDraftPlayerID = -1;
				}
				pendingKeyDraftClass = kpkt->classTier;
				pendingKeyDraftTriggerTime = ofGetElapsedTimef();
				pendingKeyDraftKeyX = kpkt->keyX;
				pendingKeyDraftKeyY = kpkt->keyY;

				// If an Accept arrived before this KeyPickup, close immediately.
				// Match by host index OR by playerID OR by key coordinates to be robust
				if (pendingKeyDraftAccept && pendingKeyDraftClass == kpkt->classTier) {
					bool match = false;
					if (pendingKeyDraftPlayer == kpkt->playerIndex) match = true;
					if (!match && pendingKeyDraftPlayerID >= 0 && pendingKeyDraftPlayerID == kpkt->playerID) match = true;
					if (!match && pendingKeyDraftKeyX == kpkt->keyX && pendingKeyDraftKeyY == kpkt->keyY) match = true;
					if (match) {
						pendingKeyDraftAccept = false;
						pendingKeyDraftPlayer = -1;
						pendingKeyDraftClass = 0;
						selectedDraftIndices.clear();
						draftOptions.clear();
						isInGameDraft = false;
						pendingDraftFinalize = true; // will transition to gameplay once animations complete
						pendingKeyDraftKeyX = -1;
						pendingKeyDraftKeyY = -1;
					}
				}

				// Color by tier: 1=gold,2=silver,3=bronze
				{
					ofColor pickupCol = ofColor::gold;
					if (kpkt->classTier == 2)
						pickupCol = ofColor(192, 192, 192);
					else if (kpkt->classTier == 3)
						pickupCol = ofColor(205, 127, 50);
					spawnFloatingText(gridToWorld(kpkt->keyX, kpkt->keyY), "Key Found!", pickupCol);
				}
				ofLogNotice("Key") << "Client: Player " << kpkt->playerIndex << " picked up key (Class " << kpkt->classTier << ")";
			}
		} else if (header->type == PKT_CHAT_MESSAGE) {
			ChatMessagePacket * pkt = (ChatMessagePacket *)header;
			ofLogNotice("Net") << "Received chat message from player " << pkt->playerID << ": " << pkt->message;

			ChatMessage msg;
			// Find player index for this playerID
			int senderIndex = -1;
			for (size_t i = 0; i < players.size(); i++) {
				if (players[i].playerID == static_cast<int>(pkt->playerID) && !players[i].isMinion) {
					senderIndex = i;
					break;
				}
			}
			msg.playerName = (senderIndex >= 0) ? getPlayerSteamName(senderIndex) : ("Player " + ofToString(pkt->playerID));
			msg.message = pkt->message;
			msg.timestamp = ofGetElapsedTimef();
			chatHistory.push_back(msg);
			if (chatHistory.size() > static_cast<size_t>(maxChatMessages)) {
				chatHistory.erase(chatHistory.begin());
			}
			// Show chat for 5 seconds when message received
			lastChatInteractionTime = ofGetElapsedTimef();
		} else if (header->type == PKT_HOVER) {
			// Ignore hover packets in singleplayer builds
			if (!isMultiplayer) continue;
			HoverPacket * pkt = (HoverPacket *)header;
			int hoverTypeInt = static_cast<int>(pkt->hoverType);
			if (hoverTypeInt >= HOVER_NONE && hoverTypeInt <= HOVER_UNIT_SELECTED) {
				opponentHoverType = static_cast<HoverType>(hoverTypeInt);
			}
			opponentHoverGridX = static_cast<int>(pkt->gridX);
			opponentHoverGridY = static_cast<int>(pkt->gridY);
			opponentHoverCardIndex = static_cast<int>(pkt->cardIndex);

			// If opponent selected a unit for movement, show their movement highlights
			if (opponentHoverType == HOVER_UNIT_SELECTED) {
				// Store current player state to restore after
				int savedPlayerX = -1, savedPlayerY = -1;
				if (currentPlayerIndex >= 0 && currentPlayerIndex < static_cast<int>(players.size())) {
					savedPlayerX = players[currentPlayerIndex].x;
					savedPlayerY = players[currentPlayerIndex].y;
					// Temporarily move current player to opponent's selected position
					players[currentPlayerIndex].x = opponentHoverGridX;
					players[currentPlayerIndex].y = opponentHoverGridY;
					calculateHighlights();
					// Restore position
					players[currentPlayerIndex].x = savedPlayerX;
					players[currentPlayerIndex].y = savedPlayerY;
				}
			}
			// If opponent is hovering a card, show their targeting highlights
			else if (opponentHoverType == HOVER_HAND_CARD && opponentHoverCardIndex >= 0) {
				if (currentPlayerIndex >= 0 && currentPlayerIndex < static_cast<int>(players.size())) {
					Player & currentPlayer = players[currentPlayerIndex];
					if (opponentHoverCardIndex < static_cast<int>(currentPlayer.hand.size())) {
						calculateTargetHighlights(opponentHoverCardIndex);
					}
				}
			}
			// If opponent cleared hover, clear highlights
			else if (opponentHoverType == HOVER_NONE) {
				clearHighlights();
			}
		}

		else if (header->type == PKT_DRAFT_ACK) {
			DraftAckPacket * dap = (DraftAckPacket *)header;
			ofLogNotice("Network") << "Draft ACK received: clientActionID=" << dap->clientActionID << " type=" << (int)dap->actionType << " opt=" << dap->optionIndex << " playerSlot=" << dap->draftPlayerIdx;

			// CLIENT: clear resend state if this ACK matches our last sent draft action
			if (isClient() && lastSentDraftActionValid && lastSentDraftActionPacket.clientActionID == dap->clientActionID) {
				lastSentDraftActionValid = false;
				ofLogNotice("Network") << "Client: DraftAction (clientActionID=" << dap->clientActionID << ") acknowledged by host";
			}

			continue;
		} else if (header->type == PKT_DRAFT_STATE) {
			DraftStatePacket * sp = (DraftStatePacket *)header;
			ofLogNotice("Network") << "Draft state received: class=" << sp->classTier << " player=" << sp->draftPlayerIdx << " picks=" << sp->picksRemaining << " stage=" << sp->draftStage << " ingame=" << (int)sp->isInGameDraft << " curPlayer=" << sp->currentPlayerIndex;

			// Debug: log player mapping and local index to diagnose mapping/race issues
			{
				std::stringstream ss;
				ss << "Players mapping (slot:playerID): ";
				for (int i = 0; i < (int)players.size(); ++i) {
					ss << i << ":" << players[i].playerID << " ";
				}
				ss << " | myLocalPlayerID=" << myLocalPlayerID << " localSlot=" << getLocalPlayerIndex() << " draftSlot=" << sp->draftPlayerIdx;
				ofLogNotice("DraftDebug") << ss.str();
			}

			// Ignore late normal-draft packets after the initial draft is complete
			if (initialDraftComplete && currentState == STATE_GAMEPLAY && sp->classTier > 0 && sp->isInGameDraft == 0) {
				ofLogNotice("Draft") << "Ignoring late normal DraftState (initial draft already complete).";
				continue;
			}

			bool optionsMatch = (!draftOptions.empty() && currentDraftClassTier == sp->classTier && draftPlayerIndex == sp->draftPlayerIdx && draftStage == sp->draftStage && isInGameDraft == (sp->isInGameDraft != 0));

			// Debug trace: log decision state for draft packet handling
			ofLogNotice("DraftTrace") << "PKT_DRAFT_STATE: optionsMatch=" << optionsMatch
									  << " currentState=" << currentState << " initialDraftComplete=" << initialDraftComplete
									  << " waitingForDraftOptions=" << waitingForDraftOptions << " draftAcceptApplied=" << draftAcceptApplied
									  << " draftOptions.size=" << draftOptions.size() << " draftPlayerIdx(pkt)=" << sp->draftPlayerIdx;

			// Client applies host state directly
			// Prefer mapping via the host-provided `draftPlayerID` (if present).
			if (isClient()) {
				int mappedIdx = -1;
				// draftPlayerID may be -1 when unset; treat >=0 as valid
				if (sp->draftPlayerID >= 0) {
					for (int i = 0; i < (int)players.size(); ++i) {
						if (players[i].playerID == sp->draftPlayerID) {
							mappedIdx = i;
							break;
						}
					}
				}
				if (mappedIdx >= 0) {
					draftPlayerIndex = mappedIdx;
				} else {
					draftPlayerIndex = sp->draftPlayerIdx;
				}
			} else {
				draftPlayerIndex = sp->draftPlayerIdx;
			}
			draftStage = sp->draftStage;
			draftPicksRemaining = sp->picksRemaining;
			isInGameDraft = (sp->isInGameDraft != 0);

			ofLogNotice("DraftDebug") << "Applied DraftState -> draftPlayerIndex=" << draftPlayerIndex
									  << " draftPlayerID(pkt)=" << sp->draftPlayerID
									  << " draftStage=" << draftStage << " picksRemaining=" << draftPicksRemaining
									  << " isInGameDraft=" << isInGameDraft << " optionsMatch=" << optionsMatch
									  << " waitingForDraftOptions=" << waitingForDraftOptions << " draftAcceptApplied=" << draftAcceptApplied;

			if (sp->classTier > 0) {
				// Clear visual dice left over from initiative to prevent them lingering forever
				if (currentState == STATE_INITIATIVE_ROLL) {
					activeDiceRolls.clear();
				}

				// Enter drafting with host-provided class tier
				currentState = STATE_DRAFTING;

				if (!optionsMatch) {
					selectedDraftIndices.clear();
					// Update current draft tier
					currentDraftClassTier = sp->classTier;
					ofLogNotice("Draft") << "Generating deterministic DraftOptions locally for class=" << sp->classTier;
					generateDraftOptions(sp->classTier);
				} else {
					// Update current draft tier
					currentDraftClassTier = sp->classTier;
					ofLogNotice("Draft") << "Client already has matching DraftOptions; using cached options (class=" << sp->classTier << ")";
				}
			} else {
				// classTier==0 => exit drafting and host tells us who is the active player
				draftOptions.clear();
				selectedDraftIndices.clear();
				currentState = STATE_GAMEPLAY;
				initialDraftComplete = true;
				// Host should include who starts; set it
				currentPlayerIndex = sp->currentPlayerIndex;
				// In multiplayer clients: DO NOT call startNewTurn(); wait for host TurnStart packet
				if (isClient()) {
					waitingForTurnStartFromHost = true;
					ofLogNotice("Network") << "Client: Drafting ended. Waiting for TurnStart packet from host (player=" << currentPlayerIndex << ")";
				}
				// Host handles transition in its own draft-accept logic and sends TurnStart
			}
		} else if (header->type == PKT_DRAFT_OPTIONS) {
			// Defensive: ensure packet buffer is large enough before casting
			if (buffer.size() < sizeof(DraftOptionsPacket)) {
				ofLogError("Network") << "PKT_DRAFT_OPTIONS truncated: size=" << buffer.size() << " expected=" << sizeof(DraftOptionsPacket) << " seq=" << header->seq;
				// If we're a client, request authoritative snapshot to recover
				if (isClient()) {
					ofLogNotice("Network") << "Client: requesting snapshot due to truncated DraftOptions packet.";
					SnapshotRequestPacket req = {};
					req.type = PKT_SNAPSHOT_REQUEST;
					req.playerID = myLocalPlayerID;
					req.requestedTurn = globalTurnCounter;
					steamManager.sendPacket(&req, sizeof(req));
					waitingForSnapshot = true;
				}
				continue;
			}

			DraftOptionsPacket * dp = (DraftOptionsPacket *)header;
			ofLogNotice("Network") << "DraftOptions received (deterministic): class=" << dp->classTier << " draftGenCounter=" << dp->draftGenCounter << " mapSeed=" << dp->mapSeed;

			// Sync the draft generation counter and map seed from host
			draftGenerationCounter = dp->draftGenCounter - 1; // Sub 1 because generateDraftOptions increments it
			currentMapSeed = dp->mapSeed;
			draftStage = dp->draftStage;
			// Map draft player index to local index when running as client
			if (isClient()) {
				int incomingPlayerID = dp->draftPlayerID;
				int mappedIdx = -1;
				for (int i = 0; i < (int)players.size(); ++i) {
					if (!players[i].isMinion && players[i].playerID == incomingPlayerID) {
						mappedIdx = i;
						break;
					}
				}
				if (mappedIdx >= 0)
					draftPlayerIndex = mappedIdx;
				else
					draftPlayerIndex = dp->draftPlayerIdx;
			} else {
				draftPlayerIndex = dp->draftPlayerIdx;
			}
			draftPicksRemaining = dp->picksRemaining;
			isInGameDraft = (dp->isInGameDraft != 0);
			draftAcceptLocked = false;
			draftAcceptApplied = false;
			waitingForDraftOptions = false;

			ofLogNotice("DraftTrace") << "PKT_DRAFT_OPTIONS: received class=" << dp->classTier << " draftGenCounter=" << dp->draftGenCounter << " mapSeed=" << dp->mapSeed << " optIdxs=" << dp->optionIdx0 << "," << dp->optionIdx1 << "," << dp->optionIdx2;

			// If the host included explicit option indices, apply them directly.
			// Otherwise fall back to deterministic local generation.
			if (dp->optionIdx0 != -1 || dp->optionIdx1 != -1 || dp->optionIdx2 != -1) {
				std::vector<int> indices;
				if (dp->optionIdx0 != -1) indices.push_back(dp->optionIdx0);
				if (dp->optionIdx1 != -1) indices.push_back(dp->optionIdx1);
				if (dp->optionIdx2 != -1) indices.push_back(dp->optionIdx2);
				ofLogNotice("DraftTrace") << "PKT_DRAFT_OPTIONS: applying explicit indices: " << dp->optionIdx0 << "," << dp->optionIdx1 << "," << dp->optionIdx2;
				applyDraftOptionsFromPool(dp->classTier, indices, dp->picksRemaining, draftPlayerIndex);

				// If the client still ended up with no options (e.g., indices invalid), request a snapshot
				if (draftOptions.empty()) {
					ofLogError("Draft") << "Client: applied explicit indices but draftOptions is empty (class=" << dp->classTier << "). Requesting snapshot.";
					if (isClient()) {
						SnapshotRequestPacket req = {};
						req.type = PKT_SNAPSHOT_REQUEST;
						req.playerID = myLocalPlayerID;
						req.requestedTurn = globalTurnCounter;
						steamManager.sendPacket(&req, sizeof(req));
						waitingForSnapshot = true;
					}
				}
			} else {
				ofLogNotice("DraftTrace") << "PKT_DRAFT_OPTIONS: no explicit indices, generating deterministically.";
				generateDraftOptions(dp->classTier);
				if (draftOptions.empty()) {
					ofLogError("Draft") << "Client: deterministic generation produced zero options (class=" << dp->classTier << "). Requesting snapshot.";
					if (isClient()) {
						SnapshotRequestPacket req = {};
						req.type = PKT_SNAPSHOT_REQUEST;
						req.playerID = myLocalPlayerID;
						req.requestedTurn = globalTurnCounter;
						steamManager.sendPacket(&req, sizeof(req));
						waitingForSnapshot = true;
					}
				}
			}
			ofLogNotice("DraftDebug") << "PKT_DRAFT_OPTIONS: applied -> size=" << draftOptions.size() << " currentState=" << currentState << " draftPlayerIndex=" << draftPlayerIndex << " localIdx=" << getLocalPlayerIndex() << " myLocalPlayerID=" << myLocalPlayerID;
		} else if (header->type == PKT_DRAFT_ACTION) {
			DraftActionPacket * pkt = (DraftActionPacket *)header;
			ofLogNotice("Network") << "Draft action received: hdr.seq=" << header->seq << " bufSize=" << buffer.size() << " type=" << (int)pkt->actionType << " opt=" << pkt->optionIndex << " player=" << pkt->draftPlayerIdx << " sel=" << (int)pkt->selectFlag << " clientActionID=" << pkt->clientActionID << " pkt.playerID=" << pkt->playerID;

			if (isHost()) {
				// Host-side deduplication for draft actions
				if (pkt->clientActionID != 0) {
					uint32_t pid = pkt->playerID;
					if (pid < (uint32_t)(sizeof(lastProcessedActionID) / sizeof(lastProcessedActionID[0])) && pkt->clientActionID <= lastProcessedActionID[pid]) {
						// Re-send DraftAck to ensure client stops resending
						DraftAckPacket ackDup = {};
						ackDup.type = PKT_DRAFT_ACK;
						ackDup.playerID = myLocalPlayerID;
						ackDup.clientActionID = pkt->clientActionID;
						ackDup.actionType = pkt->actionType;
						ackDup.optionIndex = pkt->optionIndex;
						ackDup.draftPlayerIdx = pkt->draftPlayerIdx;
						ackDup.selectFlag = pkt->selectFlag;
						steamManager.sendPacket(&ackDup, sizeof(ackDup));
						ofLogNotice("Network") << "Host: Ignoring duplicate DraftAction clientActionID=" << pkt->clientActionID << " from playerID=" << pid;
						continue;
					}
				}
				ofLogNotice("NetTrace") << "Host: processing DraftActionPacket from playerID=" << pkt->playerID << " actionType=" << (int)pkt->actionType << " clientActionID=" << pkt->clientActionID << " currentState=" << currentState << " draftStage=" << draftStage << " draftPlayerIndex=" << draftPlayerIndex;
				// Ignore any draft inputs if we're not actively drafting
				if (currentState != STATE_DRAFTING && !isInGameDraft) {
					ofLogNotice("Network") << "Host: Ignoring draft input outside draft state (type=" << (int)pkt->actionType << ", playerID=" << pkt->playerID << ", draftPlayerIdx=" << pkt->draftPlayerIdx << ", currentState=" << currentState << ")";
					continue;
				}
				// Host: apply the client's input, then forward to the client(s)
				if (pkt->actionType == 0) {
					// Toggle selection for the current drafting player (in-game drafts wait for Accept)
					int requiredPicks = 1;
					if (!isInGameDraft && draftStage == 0) requiredPicks = 2;
					int opt = pkt->optionIndex;
					if (pkt->selectFlag) {
						auto it = std::find(selectedDraftIndices.begin(), selectedDraftIndices.end(), opt);
						if (it == selectedDraftIndices.end() && (int)selectedDraftIndices.size() < requiredPicks) {
							selectedDraftIndices.push_back(opt);
						}
					} else {
						auto it = std::find(selectedDraftIndices.begin(), selectedDraftIndices.end(), opt);
						if (it != selectedDraftIndices.end()) selectedDraftIndices.erase(it);
					}
					// Forward toggle to clients (including host's own selections)
					DraftActionPacket outPkt = *pkt;
					ofLogNotice("NetTrace") << "Host: forwarding DraftToggle to clients: opt=" << outPkt.optionIndex << " sel=" << (int)outPkt.selectFlag;
					{
						bool ok = steamManager.sendPacket(&outPkt, sizeof(outPkt));
						ofLogNotice("NetTrace") << "Host forwarding DraftActionPacket to clients: opt=" << outPkt.optionIndex << " sel=" << (int)outPkt.selectFlag << " ok=" << ok;
					}
					// Send explicit ACK back to the originating client so they stop resending
					DraftAckPacket ack = {};
					ack.type = PKT_DRAFT_ACK;
					ack.playerID = myLocalPlayerID;
					ack.clientActionID = pkt->clientActionID;
					ack.actionType = pkt->actionType;
					ack.optionIndex = pkt->optionIndex;
					ack.draftPlayerIdx = pkt->draftPlayerIdx;
					ack.selectFlag = pkt->selectFlag;
					{
						ofLogNotice("NetTrace") << "Host: sending DraftAck to client: clientActionID=" << ack.clientActionID << " actionType=" << (int)ack.actionType << " opt=" << ack.optionIndex << " draftPlayer=" << ack.draftPlayerIdx;
						bool ok = steamManager.sendPacket(&ack, sizeof(ack));
						ofLogNotice("NetTrace") << "  DraftAck send ok=" << ok;
					}
					// Record processed clientActionID for deduplication
					if (pkt->clientActionID != 0) {
						uint32_t pid = pkt->playerID;
						if (pid < (uint32_t)(sizeof(lastProcessedActionID) / sizeof(lastProcessedActionID[0]))) {
							lastProcessedActionID[pid] = pkt->clientActionID;
							ofLogNotice("Network") << "Host: recorded lastProcessedActionID[" << pid << "]=" << lastProcessedActionID[pid];
						}
					}
					// Also send updated draft state after every selection
					DraftStatePacket dsp;
					dsp.type = PKT_DRAFT_STATE;
					dsp.playerID = myLocalPlayerID;
					dsp.classTier = currentDraftClassTier; // FIX: Was incorrectly hardcoded based on draftStage
					dsp.draftPlayerIdx = draftPlayerIndex;
					dsp.picksRemaining = draftPicksRemaining;
					dsp.draftStage = draftStage;
					dsp.isInGameDraft = isInGameDraft ? 1 : 0;
					dsp.currentPlayerIndex = currentPlayerIndex;
					steamManager.sendPacket(&dsp, sizeof(dsp));
				} else if (pkt->actionType == 1) {
					// Client accepted draft with choices -> apply on host
					ofLogNotice("Draft") << "HOST: Received client AcceptDraft from player=" << pkt->playerID << " draftPlayerIdx=" << pkt->draftPlayerIdx << " picks=" << (int)pkt->numSelected << " indices=" << (int)pkt->selectedIdx0 << "," << (int)pkt->selectedIdx1 << "," << (int)pkt->selectedIdx2;
					ofLogNotice("Draft") << "HOST: isInGameDraft=" << isInGameDraft << " inGameDraftTargetIdx=" << inGameDraftTargetIdx;
					int picks = pkt->numSelected;
					std::vector<int> sel;
					if (picks > 0) sel.push_back(pkt->selectedIdx0);
					if (picks > 1) sel.push_back(pkt->selectedIdx1);
					if (picks > 2) sel.push_back(pkt->selectedIdx2);

					// Resolve the intended drafting target robustly. Clients send a
					// `draftPlayerIdx` that may be a local index; map it to the
					// host's authoritative index.
					int targetIdx = pkt->draftPlayerIdx;
					bool needsRemap = false;

					// If this is an in-game key draft, use the pre-determined target
					if (isInGameDraft && inGameDraftTargetIdx >= 0 && inGameDraftTargetIdx < (int)players.size()) {
						targetIdx = inGameDraftTargetIdx;
						ofLogNotice("Draft") << "HOST: In-game draft - using pre-determined target idx=" << targetIdx;
					} else {
						// Otherwise, validate or remap the client-provided index
						if (targetIdx < 0 || targetIdx >= (int)players.size())
							needsRemap = true;
						else if (!(players[targetIdx].playerID == (int)pkt->playerID || players[targetIdx].ownerID == (int)pkt->playerID))
							needsRemap = true;

						if (needsRemap) {
							// Try to find a player whose playerID matches the integer sent
							int found = -1;
							for (int i = 0; i < (int)players.size(); ++i) {
								if (players[i].playerID == pkt->draftPlayerIdx) {
									found = i;
									break;
								}
							}
							if (found == -1) {
								// Otherwise, try to find ANY minion owned by the sending player
								for (int i = 0; i < (int)players.size(); ++i) {
									if (players[i].isMinion && players[i].ownerID == (int)pkt->playerID) {
										found = i;
										break;
									}
								}
							}
							if (found == -1) {
								// Fallback: find the owner/player index for the sending client
								for (int i = 0; i < (int)players.size(); ++i) {
									if (players[i].playerID == (int)pkt->playerID) {
										found = i;
										break;
									}
								}
							}
							if (found != -1) {
								ofLogNotice("Draft") << "HOST: remapped draftPlayerIdx " << pkt->draftPlayerIdx << " -> " << found;
								targetIdx = found;
							} else {
								ofLogWarning("Draft") << "HOST: unable to remap draftPlayerIdx " << pkt->draftPlayerIdx << ". Using as-is.";
							}
						}
					}
					Player & p = players[targetIdx];
					ofLogNotice("Draft") << "HOST: Adding cards to targetIdx=" << targetIdx << " playerID=" << p.playerID << " isMinion=" << p.isMinion << " ownerID=" << p.ownerID;
					int copiesPerCard = 1;
					if (!isInGameDraft && pkt->classTier == 1) copiesPerCard = 2;
					const std::vector<Card> * pool = &class1Cards;
					if (pkt->classTier == 2) pool = &class2Cards;
					if (pkt->classTier == 3) pool = &class3Cards;
					for (int idx : sel) {
						if (idx >= 0 && idx < (int)pool->size()) {
							for (int k = 0; k < copiesPerCard; ++k) {
								p.deck.push_back((*pool)[idx]);
							}
						}
					}

					// Immediately shuffle the host's authoritative deck for the target player/minion
					shuffleGameVector(p.deck, targetIdx);

					// Send an authoritative DraftState first so clients can map player indices
					DraftStatePacket dsp = {};
					dsp.type = PKT_DRAFT_STATE;
					dsp.playerID = myLocalPlayerID;
					dsp.classTier = pkt->classTier;
					dsp.draftPlayerIdx = targetIdx;
					dsp.draftPlayerID = (dsp.draftPlayerIdx >= 0 && dsp.draftPlayerIdx < (int)players.size()) ? players[dsp.draftPlayerIdx].playerID : -1;
					dsp.picksRemaining = draftPicksRemaining;
					dsp.draftStage = draftStage;
					dsp.isInGameDraft = isInGameDraft ? 1 : 0;
					dsp.currentPlayerIndex = currentPlayerIndex;
					steamManager.sendPacket(&dsp, sizeof(dsp));

					// Now forward the AcceptDraft with the host-authoritative index
					DraftActionPacket outPkt = *pkt;
					outPkt.draftPlayerIdx = targetIdx;
					ofLogNotice("NetTrace") << "Host: forwarding AcceptDraft to clients: draftPlayer=" << outPkt.draftPlayerIdx << " numSelected=" << (int)outPkt.numSelected;
					steamManager.sendPacket(&outPkt, sizeof(outPkt));

					// Send explicit ACK for this Accept back to the origin client
					DraftAckPacket ack = {};
					ack.type = PKT_DRAFT_ACK;
					ack.playerID = myLocalPlayerID;
					ack.clientActionID = pkt->clientActionID;
					ack.actionType = pkt->actionType;
					ack.draftPlayerIdx = targetIdx;
					ack.numSelected = (uint8_t)pkt->numSelected;
					ack.selectedIdx0 = pkt->selectedIdx0;
					ack.selectedIdx1 = pkt->selectedIdx1;
					ack.selectedIdx2 = pkt->selectedIdx2;
					{
						ofLogNotice("NetTrace") << "Host sending DraftAck (Accept): clientActionID=" << ack.clientActionID << " actionType=" << (int)ack.actionType << " draftPlayer=" << ack.draftPlayerIdx << " numSelected=" << (int)ack.numSelected;
						bool ok = steamManager.sendPacket(&ack, sizeof(ack));
						ofLogNotice("NetTrace") << "  DraftAck (Accept) send ok=" << ok;
					}
					// Record processed clientActionID for dedupe
					if (pkt->clientActionID != 0) {
						uint32_t pid = pkt->playerID;
						if (pid < (uint32_t)(sizeof(lastProcessedActionID) / sizeof(lastProcessedActionID[0]))) {
							lastProcessedActionID[pid] = pkt->clientActionID;
							ofLogNotice("Network") << "Host: recorded lastProcessedActionID[" << pid << "]=" << lastProcessedActionID[pid];
						}
					}

					selectedDraftIndices.clear();
					draftOptions.clear();
					if (isInGameDraft) {
						isInGameDraft = false;
						currentState = STATE_GAMEPLAY;
						continue;
					}

					draftStage++;
					// allow time for pick-move + shuffle visuals to finish before showing next draft
					float delay = draftAnimHoldDuration + 0.35f + 0.9f + 0.1f;
					if (draftStage == 1) {
						// Move to Class 2
						scheduleGenerateDraftOptions(2, delay);

					} else {
						// Check if other player needs to draft
						int nextPlayerIdx = (draftPlayerIndex + 1) % 2;
						if (players[nextPlayerIdx].deck.empty()) {
							draftPlayerIndex = nextPlayerIdx;
							draftStage = 0;
							scheduleGenerateDraftOptions(1, delay);

						} else {
							currentPlayerIndex = nextPlayerIdx;
							currentState = STATE_GAMEPLAY;
							continueNewTurn();
						}
					}
					// Also send an additional state sync with currentPlayerIndex to ensure clients transition
					// (Use the shared temporary `tempDraftStatePkt` below - avoid duplicate sends)
					tempDraftStatePkt.type = PKT_DRAFT_STATE;
					tempDraftStatePkt.playerID = myLocalPlayerID;
					// classTier: 0 == none, 1/2 == class tiers
					if (currentState == STATE_GAMEPLAY)
						tempDraftStatePkt.classTier = 0;
					else if (draftStage == 0)
						tempDraftStatePkt.classTier = 1;
					else
						tempDraftStatePkt.classTier = 2;
					tempDraftStatePkt.draftPlayerIdx = (currentState == STATE_GAMEPLAY) ? -1 : draftPlayerIndex;
					tempDraftStatePkt.draftPlayerID = (tempDraftStatePkt.draftPlayerIdx >= 0 && tempDraftStatePkt.draftPlayerIdx < (int)players.size()) ? players[tempDraftStatePkt.draftPlayerIdx].playerID : -1;
					tempDraftStatePkt.picksRemaining = draftPicksRemaining;
					tempDraftStatePkt.draftStage = draftStage;
					tempDraftStatePkt.isInGameDraft = isInGameDraft ? 1 : 0;
					tempDraftStatePkt.currentPlayerIndex = currentPlayerIndex;
					steamManager.sendPacket(&tempDraftStatePkt, sizeof(tempDraftStatePkt));
					// NOTE: TurnStart packet and checksum send are now handled in updateGame()
					// once AP dice finish naturally. Removing the manual TurnStart/Checksum
					// send here prevents duplicate TurnStart packets when dice are still
					// animating after draft completion.
				}
			} else {
				// Client: apply actions forwarded by host
				if (pkt->actionType == 0) {

					// If this forwarded toggle matches a packet we sent, clear resend state early
					if (lastSentDraftActionValid && pkt->playerID == static_cast<uint32_t>(myLocalPlayerID) && pkt->actionType == 0) {
						lastSentDraftActionValid = false;
						ofLogNotice("Network") << "Client: Received host-forwarded DraftToggle ack for our packet (early)";
					}
					// if (draftAcceptLocked) { continue; }
					// ------------------------

					// Host forwarded selection toggle or in-game pick
					if (isInGameDraft) {
						// For in-game drafts, just toggle the selection and show/hide the card highlight
						int opt = pkt->optionIndex;
						if (pkt->selectFlag) {
							auto it = std::find(selectedDraftIndices.begin(), selectedDraftIndices.end(), opt);
							if (it == selectedDraftIndices.end()) selectedDraftIndices.push_back(opt);
						} else {
							auto it = std::find(selectedDraftIndices.begin(), selectedDraftIndices.end(), opt);
							if (it != selectedDraftIndices.end()) selectedDraftIndices.erase(it);
						}
						// Wait for the accept, don't clear draftOptions yet
					} else {
						int opt = pkt->optionIndex;
						if (pkt->selectFlag) {
							auto it = std::find(selectedDraftIndices.begin(), selectedDraftIndices.end(), opt);
							if (it == selectedDraftIndices.end()) selectedDraftIndices.push_back(opt);
						} else {
							auto it = std::find(selectedDraftIndices.begin(), selectedDraftIndices.end(), opt);
							if (it != selectedDraftIndices.end()) selectedDraftIndices.erase(it);
						}
					}
				} else if (pkt->actionType == 1) {
					// Client: host forwarded an Accept. Apply any cards and then WAIT for host authoritative state/options.
					ofLogNotice("Draft") << "CLIENT: Received forwarded AcceptDraft from host player=" << pkt->draftPlayerIdx << " picks=" << (int)pkt->numSelected << " indices=" << (int)pkt->selectedIdx0 << "," << (int)pkt->selectedIdx1 << "," << (int)pkt->selectedIdx2 << " classTier=" << (int)pkt->classTier;
					if (draftAcceptApplied) {
						ofLogNotice("Draft") << "CLIENT: Ignoring duplicate Accept (already applied).";
						continue;
					}
					if (initialDraftComplete && currentState == STATE_GAMEPLAY && !isInGameDraft) {
						ofLogNotice("Draft") << "CLIENT: Ignoring late normal Accept after initial draft completed.";
						continue;
					}
					draftAcceptApplied = true;
					// If this forwarded accept matches our last sent Accept, clear the resend state
					if (lastSentDraftActionValid && pkt->playerID == static_cast<uint32_t>(myLocalPlayerID) && pkt->actionType == 1) {
						lastSentDraftActionValid = false;
						ofLogNotice("Network") << "Client: Received host-forwarded AcceptDraft ack for our packet";
					}
					int picks = pkt->numSelected;
					std::vector<int> sel;
					if (picks > 0) sel.push_back(pkt->selectedIdx0);
					if (picks > 1) sel.push_back(pkt->selectedIdx1);
					if (picks > 2) sel.push_back(pkt->selectedIdx2);

					int localTargetIdx = pkt->draftPlayerIdx;
					// Client: remap host-provided index to our local index.
					// The host sends pkt->draftPlayerIdx which is the host's player array index.
					// We need to map this to OUR local player array index by matching playerID.
					if (isClient()) {
						// First, try to extract the playerID from the host's player at that index.
						// If pkt->draftPlayerIdx is valid and matches a playerID, map it.
						// (Note: host index space might differ from client's if players joined in different order)

						// If we have pending key coords (pickup), prefer the minion at that tile.
						bool foundByKeyCoords = false;
						if (pendingKeyDraftKeyX >= 0 && pendingKeyDraftKeyY >= 0) {
							for (int i = 0; i < (int)players.size(); ++i) {
								if (players[i].isMinion && players[i].x == pendingKeyDraftKeyX && players[i].y == pendingKeyDraftKeyY) {
									localTargetIdx = i;
									foundByKeyCoords = true;
									ofLogNotice("Draft") << "CLIENT: Mapped Accept to minion at key tile (" << pendingKeyDraftKeyX << "," << pendingKeyDraftKeyY << ") -> localIdx=" << i;
									break;
								}
							}
						}

						// If not found by key coords, trust host's index (assume host and client have same player order)
						// In most cases, the host's draftPlayerIdx should match our local index directly.
						if (!foundByKeyCoords) {
							if (localTargetIdx >= 0 && localTargetIdx < (int)players.size()) {
								ofLogNotice("Draft") << "CLIENT: Using host draftPlayerIdx=" << localTargetIdx << " directly";
							} else {
								ofLogWarning("Draft") << "CLIENT: host draftPlayerIdx=" << pkt->draftPlayerIdx << " out of range, clamping";
								localTargetIdx = 0;
							}
						}
					}
					Player & p = players[localTargetIdx];
					int copiesPerCard = 1;
					if (!isInGameDraft && pkt->classTier == 1) copiesPerCard = 2;
					const std::vector<Card> * pool = &class1Cards;
					if (pkt->classTier == 2) pool = &class2Cards;
					if (pkt->classTier == 3) pool = &class3Cards;
					ofLogNotice("Draft") << "CLIENT: Pool size=" << pool->size() << " copies=" << copiesPerCard;
					for (int idx : sel) {
						if (idx >= 0 && idx < (int)pool->size()) {
							ofLogNotice("Draft") << "CLIENT: Adding card index=" << idx << " name=" << (*pool)[idx].name;
							for (int k = 0; k < copiesPerCard; ++k) {
								p.deck.push_back((*pool)[idx]);
							}
						}
					}
					// In multiplayer clients, mark that we will skip the immediate local shuffle and
					// wait for the host's authoritative `PKT_SHUFFLE` for this player's deck.
					ofLogNotice("Draft") << "CLIENT: Using localTargetIdx=" << localTargetIdx << " for shuffle (was pkt->draftPlayerIdx=" << pkt->draftPlayerIdx << ")";
					if (isClient()) {
						int pid = localTargetIdx; // map to our local index
						if (pid >= 0 && pid < (int)players.size()) {
							auto it = pendingShuffleNonces.find(pid);
							if (it != pendingShuffleNonces.end() && !it->second.empty()) {
								uint32_t nonceToApply = it->second.front();
								it->second.pop_front();
								std::mt19937 shuffleRng(nonceToApply);
								deterministic_shuffle(p.deck, shuffleRng);
								lastAppliedShuffleNonce[pid] = nonceToApply;
								if (skipClientShuffleFor == pid) {
									skipClientShuffleFor = -1;
								}
								ofLogNotice("Network") << "Client: Applied deferred shuffle nonce for player " << pid << " after AcceptDraft (nonce=" << nonceToApply << ")";
							} else {
								skipClientShuffleFor = pid;
								shuffleGameVector(p.deck, pid);
							}
						}
					} else {
						shuffleGameVector(p.deck, localTargetIdx);
					}
				}
				selectedDraftIndices.clear();
				if (isInGameDraft) {
					draftOptions.clear();
					isInGameDraft = false;
					// Clear pending key coords now that in-game draft is done
					pendingKeyDraftKeyX = -1;
					pendingKeyDraftKeyY = -1;
					currentState = STATE_GAMEPLAY;
					continue;
				}
				// If we haven't received the KeyPickup yet, remember this accept so we can close on arrival
				if (currentState != STATE_DRAFTING) {
					pendingKeyDraftAccept = true;
					pendingKeyDraftPlayer = pkt->draftPlayerIdx;
					pendingKeyDraftClass = pkt->classTier;
					AckPacket * ack = (AckPacket *)header;
					// If this ACK corresponds to an Action we sent, clear resend state
					if (isClient() && ack->ackType == PKT_ACTION) {
						if (lastSentActionValid && ack->ackSeq == lastSentActionPacket.clientActionID) {
							lastSentActionValid = false;
							ofLogNotice("Network") << "Client: ActionPacket (clientActionID=" << ack->ackSeq << ") acknowledged by host.";
						}
					}

					// Clear RenewedInspiration resend state if host acknowledged
					if (isClient() && ack->ackType == PKT_RENEWED_INSPIRATION) {
						if (lastSentRenewedInspirationValid && ack->ackSeq == lastSentRenewedInspirationPacket.clientActionID) {
							lastSentRenewedInspirationValid = false;
							lastSentRenewedInspirationAttempts = 0;
							ofLogNotice("Network") << "Client: RenewedInspiration acknowledged by host (clientActionID=" << ack->ackSeq << ").";
						}
					}

					// Clear DrawCards resend state if host acknowledged
					if (isClient() && ack->ackType == PKT_DRAW_CARDS) {
						if (lastSentDrawCardsValid && ack->ackSeq == lastSentDrawCardsPacket.clientActionID) {
							lastSentDrawCardsValid = false;
							lastSentDrawCardsAttempts = 0;
							ofLogNotice("Network") << "Client: DrawCards acknowledged by host (clientActionID=" << ack->ackSeq << ").";
						}
					}
					// Draft ACKs handled earlier via PKT_DRAFT_ACK branch
					continue;
				}
			}
		}
	}

	// After draining incoming packets, run client-side resend watchdogs for
	// certain reliable but lightweight packets (Renewed Inspiration, DrawCards).
	if (isClient()) {
		float now = ofGetElapsedTimef();
		const int MAX_ATTEMPTS = 5;
		if (lastSentRenewedInspirationValid) {
			float backoff = powf(2.0f, std::max(0, lastSentRenewedInspirationAttempts - 1));
			if (lastSentRenewedInspirationAttempts == 0) backoff = 0.5f; // first retry sooner
			if (now - lastSentRenewedInspirationTime > backoff) {
				if (lastSentRenewedInspirationAttempts >= MAX_ATTEMPTS) {
					// Give up and request authoritative snapshot
					if (!waitingForSnapshot) {
						SnapshotRequestPacket req = {};
						req.type = PKT_SNAPSHOT_REQUEST;
						req.playerID = myLocalPlayerID;
						req.requestedTurn = globalTurnCounter;
						steamManager.sendPacket(&req, sizeof(req));
						waitingForSnapshot = true;
						lastSnapshotRequestTime = now;
						ofLogNotice("Network") << "Client: RenewedInspiration retry limit reached — requested snapshot.";
					}
					lastSentRenewedInspirationValid = false;
					lastSentRenewedInspirationAttempts = 0;
				} else {
					steamManager.sendPacket(&lastSentRenewedInspirationPacket, sizeof(lastSentRenewedInspirationPacket));
					lastSentRenewedInspirationTime = now;
					lastSentRenewedInspirationAttempts++;
					ofLogNotice("Network") << "Client: Resent RenewedInspiration (attempt=" << lastSentRenewedInspirationAttempts << ").";
				}
			}
		}

		if (lastSentDrawCardsValid) {
			float backoff = powf(2.0f, std::max(0, lastSentDrawCardsAttempts - 1));
			if (lastSentDrawCardsAttempts == 0) backoff = 0.5f;
			if (now - lastSentDrawCardsTime > backoff) {
				if (lastSentDrawCardsAttempts >= MAX_ATTEMPTS) {
					if (!waitingForSnapshot) {
						SnapshotRequestPacket req = {};
						req.type = PKT_SNAPSHOT_REQUEST;
						req.playerID = myLocalPlayerID;
						req.requestedTurn = globalTurnCounter;
						steamManager.sendPacket(&req, sizeof(req));
						waitingForSnapshot = true;
						lastSnapshotRequestTime = now;
						ofLogNotice("Network") << "Client: DrawCards retry limit reached — requested snapshot.";
					}
					lastSentDrawCardsValid = false;
					lastSentDrawCardsAttempts = 0;
				} else {
					steamManager.sendPacket(&lastSentDrawCardsPacket, sizeof(lastSentDrawCardsPacket));
					lastSentDrawCardsTime = now;
					lastSentDrawCardsAttempts++;
					ofLogNotice("Network") << "Client: Resent DrawCards (attempt=" << lastSentDrawCardsAttempts << ").";
				}
			}
		}
	}

	// Close processNetworkPackets() scope
}

// --- Networking helper implementations ---
void ofApp::sendPlaceSummonedBegin(int minionType, int ownerPlayerID, int sourceX, int sourceY, int numToPlace) {
	PlaceSummonedBeginPacket bp = {};
	bp.type = PKT_PLACE_SUMMONED_BEGIN;
	bp.playerID = myLocalPlayerID;
	bp.minionType = (uint8_t)minionType;
	bp.ownerPlayerID = ownerPlayerID;
	bp.sourceX = sourceX;
	bp.sourceY = sourceY;
	bp.numToPlace = numToPlace;
	steamManager.sendPacket(&bp, sizeof(bp));
	ofLogNotice("Network") << "Host sent PlaceSummonedBegin (helper): type=" << (int)bp.minionType << " owner=" << bp.ownerPlayerID << " source=(" << bp.sourceX << "," << bp.sourceY << ") num=" << bp.numToPlace;
}

void ofApp::sendEarthquakeBegin() {
	EarthquakeBeginPacket eb = {};
	eb.type = PKT_EARTHQUAKE_BEGIN;
	eb.playerID = myLocalPlayerID;
	eb.numUnits = std::min((int)earthquakeUnits.size(), 16);
	for (int i = 0; i < eb.numUnits; ++i) {
		eb.playerIndex[i] = earthquakeUnits[i].playerIndex;
		eb.dirX[i] = (int8_t)earthquakeUnits[i].direction.x;
		eb.dirY[i] = (int8_t)earthquakeUnits[i].direction.y;
	}
	steamManager.sendPacket(&eb, sizeof(eb));
	ofLogNotice("Network") << "Host sent EarthquakeBegin (helper): units=" << eb.numUnits;
}

void ofApp::sendCardActionBegin(int cardType, int actorIndex, int targetX, int targetY, int p0, int p1, int p2, int p3, const std::string & label) {
	CardActionBeginPacket pkt = {};
	pkt.type = PKT_CARD_ACTION_BEGIN;
	pkt.playerID = myLocalPlayerID;
	pkt.cardType = cardType;
	pkt.actorIndex = actorIndex;
	pkt.targetX = targetX;
	pkt.targetY = targetY;
	pkt.param0 = p0;
	pkt.param1 = p1;
	pkt.param2 = p2;
	pkt.param3 = p3;
	if (!label.empty()) {
		strncpy(pkt.label, label.c_str(), sizeof(pkt.label) - 1);
		pkt.label[sizeof(pkt.label) - 1] = '\0';
	}
	steamManager.sendPacket(&pkt, sizeof(pkt));
	ofLogNotice("Network") << "Host sent CardActionBegin: card=" << cardType << " actor=" << actorIndex << " target=(" << targetX << "," << targetY << ") p0=" << p0 << " p1=" << p1;
}

// Send menu state for opponent visualization
void ofApp::sendMenuState(int menuType, int targetIndex, int hoveredChoice, int cardIndex) {
	if (!isMultiplayer) return;
	// Opponent menu visualization is disabled.
	return;
}

// When I click a card
void ofApp::sendActionPacket(int cardIndex, int tx, int ty, int cost, int menuChoice, const std::string & cardNameOverride) {
	// 1. Check if it's my turn or my minion's turn
	if (currentPlayerIndex < 0 || currentPlayerIndex >= (int)players.size()) return;
	const Player & currentPlayer = players[currentPlayerIndex];
	int controlledPlayerID = currentPlayer.isMinion ? currentPlayer.ownerID : currentPlayer.playerID;
	if (controlledPlayerID != myLocalPlayerID) {
		ofLogNotice("Network") << "sendActionPacket: abort - not controlling this player (controlledPlayerID=" << controlledPlayerID << " myLocalPlayerID=" << myLocalPlayerID << ")";
		return;
	}

	// 2. Create Packet
	ActionPacket pkt = {};
	pkt.type = PKT_ACTION;
	pkt.playerID = myLocalPlayerID;
	pkt.actorIndex = currentPlayerIndex;
	pkt.cardIndex = cardIndex;
	pkt.targetX = tx;
	pkt.targetY = ty;
	pkt.cost = cost;
	pkt.menuChoice = menuChoice;
	pkt.updatedAP = currentAP; // Send current AP after card play

	// Include card name so opponent knows which card was played and validate
	if (!cardNameOverride.empty()) {
		strncpy(pkt.cardName, cardNameOverride.c_str(), 63);
		pkt.cardName[63] = '\0';
	}

	bool validSend = false;
	// If no name yet, try to resolve from cardIndex
	if (pkt.cardName[0] == '\0') {
		if (cardIndex >= 0 && cardIndex < (int)currentPlayer.hand.size()) {
			strncpy(pkt.cardName, currentPlayer.hand[cardIndex].name.c_str(), 63);
			pkt.cardName[63] = '\0';
			validSend = true;
		}
	} else {
		// If we have a name, try to find it in our hand and sync index if found
		bool foundInHand = false;
		for (int i = 0; i < (int)currentPlayer.hand.size(); ++i) {
			if (currentPlayer.hand[i].name == pkt.cardName) {
				// Found the named card in hand
				validSend = true;
				foundInHand = true;
				if (cardIndex != i) pkt.cardIndex = i;
				break;
			}
		}
		// If name not found in hand, allow name-only sends (caller may have removed card locally
		// before sending; permit sending as long as a name was provided).
		if (!foundInHand) {
			validSend = true; // permit name-only send
		}
	}

	if (!validSend) {
		ofLogWarning("Network") << "sendActionPacket: Aborting send - card not found in hand: cardIndex=" << cardIndex << " name='" << pkt.cardName << "' menuChoice=" << menuChoice;
		return;
	}

	ofLogNotice("Network") << "sendActionPacket: Sending card '" << pkt.cardName << "' (cardIndex=" << pkt.cardIndex << ") to target=(" << tx << "," << ty << ") cost=" << cost;

	// 3. Send to Network
	// If we're a client, attach a clientActionID for ACK matching and record for resend
	if (isClient()) {
		pkt.clientActionID = ++actionClientActionCounter;
		lastSentActionPacket = pkt;
		lastSentActionValid = true;
		lastSentActionTime = ofGetElapsedTimef();
		lastSentActionResendCount = 0;
	}
	steamManager.sendPacket(&pkt, sizeof(pkt));

	// Local execution is handled by the caller (playCard + result handling).
}

void ofApp::sendMagicHandResolutionPacket(int choice) {
	if (!isMultiplayer) return;
	if (currentPlayerIndex < 0 || currentPlayerIndex >= (int)players.size()) return;
	const Player & currentPlayer = players[currentPlayerIndex];
	int controlledPlayerID = currentPlayer.isMinion ? currentPlayer.ownerID : currentPlayer.playerID;
	if (controlledPlayerID != myLocalPlayerID) return;
	if (pendingMagicHandCardIndex < 0 || pendingMagicHandCardIndex >= (int)currentPlayer.hand.size()) return;

	ActionPacket pkt = {};
	pkt.type = PKT_ACTION;
	pkt.playerID = myLocalPlayerID;
	pkt.actorIndex = currentPlayerIndex;
	pkt.cardIndex = pendingMagicHandCardIndex;
	pkt.targetX = magicHandTargetTile.x;
	pkt.targetY = magicHandTargetTile.y;
	pkt.cost = currentPlayer.hand[pendingMagicHandCardIndex].cost;
	pkt.menuChoice = choice;
	pkt.updatedAP = currentAP; // Send current AP after card play
	strncpy(pkt.cardName, currentPlayer.hand[pendingMagicHandCardIndex].name.c_str(), 63);
	pkt.cardName[63] = '\0';

	ofLogNotice("Network") << "sendMagicHandResolutionPacket: Sending '" << pkt.cardName << "' choice=" << choice
						   << " target=(" << pkt.targetX << "," << pkt.targetY << ") cost=" << pkt.cost;
	steamManager.sendPacket(&pkt, sizeof(pkt));
}

void ofApp::executeAction(const ActionPacket & pkt) {
	// This function runs on BOTH computers.
	// On the sender's PC, it runs immediately via sendActionPacket.
	// On the receiver's PC, it runs via processNetworkPackets.

	// IMPORTANT: Ensure currentPlayerIndex is correct on both machines
	// before calling playCard.

	// If the action came from an opponent (different playerID than current player),
	// we don't have access to their hand, so we need special handling
	if (isMultiplayer && pkt.playerID != static_cast<uint32_t>(myLocalPlayerID) && strlen(pkt.cardName) > 0) {
		// Opponent's card play - apply effect based on card name
		executeOpponentCardPlay(pkt);
	} else {
		// Local player's card play (client-side prediction or single player)
		playCard(pkt.cardIndex, pkt.targetX, pkt.targetY);
	}
}

void ofApp::executeOpponentCardPlay(const ActionPacket & pkt) {
	// Handle opponent's card play by temporarily adding card to their hand and executing full logic
	std::string cardName = pkt.cardName;
	int tx = pkt.targetX;
	int ty = pkt.targetY;

	ofLogNotice("Network") << "executeOpponentCardPlay: Opponent played " << cardName << " at (" << tx << "," << ty << ") actorIndex=" << pkt.actorIndex;

	// Find the acting unit (player or minion)
	int opponentPlayerIndex = -1;
	if (pkt.actorIndex >= 0 && pkt.actorIndex < (int)players.size()) {
		opponentPlayerIndex = pkt.actorIndex;
	} else {
		for (size_t i = 0; i < players.size(); i++) {
			Player & p = players[i];
			if (static_cast<uint32_t>(p.playerID) == pkt.playerID && !p.isMinion) {
				opponentPlayerIndex = (int)i;
				break;
			}
		}
	}
	if (opponentPlayerIndex < 0) {
		ofLogWarning("Network") << "executeOpponentCardPlay: Opponent unit not found!";
		return;
	}

	// Find the card definition from allCards by name
	Card cardDef;
	bool found = false;
	for (const auto & c : allCards) {
		if (c.name == cardName) {
			cardDef = c;
			found = true;
			break;
		}
	}

	// --- ADD DIAGNOSTIC LOG ---
	if (!found) {
		ofLogError("Network") << "CRITICAL: Opponent played card '" << cardName << "' but it was not found in local allCards DB!";
		// Attempt fallback? Or just return to avoid crash.
		return;
	}

	ofLogNotice("Network") << "executeOpponentCardPlay: Card type=" << (int)cardDef.type << " cost=" << cardDef.cost;
	Player & opponentPlayer = players[opponentPlayerIndex];

	// Temporarily swap to opponent's player context
	int savedCurrentPlayerIndex = currentPlayerIndex;
	int savedCurrentAP = currentAP;
	currentPlayerIndex = opponentPlayerIndex;

	// Find the card in opponent's hand (for cards received via DrawCards packet)
	int tempCardIndex = -1;
	for (size_t i = 0; i < opponentPlayer.hand.size(); i++) {
		if (opponentPlayer.hand[i].name == cardName) {
			tempCardIndex = (int)i;
			break;
		}
	}

	// If card not found in hand, add it temporarily (for cards not synced via DrawCards)
	bool addedTemporaryCard = false;
	if (tempCardIndex < 0) {
		opponentPlayer.hand.push_back(cardDef);
		opponentPlayer.hand.back().currentScale = opponentPlayer.hand.back().targetScale = 1.5f;
		tempCardIndex = (int)opponentPlayer.hand.size() - 1;
		addedTemporaryCard = true;
	}
	(void)addedTemporaryCard;

	// --- FIX START: ENFORCE AP AUTHORITY FOR REMOTE ACTIONS ---
	// Sync AP from the authoritative player state. Do NOT pre-deduct the
	// card cost here; `playCard()` will consume AP itself. Pre-deducting
	// caused double-AP consumption on the client and led to failed plays.
	currentAP = opponentPlayer.ap;
	// Do NOT subtract cardDef.cost here. The authoritative `pkt.updatedAP`
	// will be applied after the play completes to keep client state synced.
	// --- FIX END ---

	ofLogNotice("Network") << "executeOpponentCardPlay: Executing playCard with cardIndex=" << tempCardIndex << " currentPlayerIndex=" << currentPlayerIndex << " AP=" << currentAP;
	ofLogNotice("Network") << "executeOpponentCardPlay: Hand size before playCard = " << opponentPlayer.hand.size() << ", Played pile size = " << opponentPlayer.playedCardsPile.size();

	// Special-case: resolve Giant Magic Hand using the sender's menu choice
	if (cardDef.type == CARD_GIANT_MAGIC_HAND && pkt.menuChoice != 0) {
		// Track the card play
		currentAP -= cardDef.cost;
		opponentPlayer.playedCardsPile.push_back(cardDef);
		applyReplicateCopyToHand(opponentPlayer, cardDef);
		opponentPlayer.cardsPlayedThisTurn.push_back(cardDef.type);

		pendingMagicHandCardIndex = tempCardIndex;
		magicHandTargetTile = { tx, ty };
		isMagicHandMenuOpen = false;
		if (pkt.menuChoice == 1) {
			resolveMagicHandPush();
		} else if (pkt.menuChoice == 2) {
			resolveMagicHandPull();
		}

		// Save the updated AP back to the player
		opponentPlayer.ap = pkt.updatedAP;

		// Remove the card from opponent's hand
		if (tempCardIndex >= 0 && tempCardIndex < (int)opponentPlayer.hand.size()) {
			opponentPlayer.hand.erase(opponentPlayer.hand.begin() + tempCardIndex);
		}
		pendingMagicHandCardIndex = -1;

		if (savedCurrentPlayerIndex == opponentPlayerIndex) {
			currentAP = opponentPlayer.ap;
		} else {
			currentPlayerIndex = savedCurrentPlayerIndex;
			if (currentPlayerIndex >= 0 && currentPlayerIndex < (int)players.size()) {
				currentAP = players[currentPlayerIndex].ap;
			} else {
				currentAP = savedCurrentAP;
			}
		}
		return;
	}

	// Special-case: Dispel with menuChoice (1=barrier, 2=purge)
	if (cardDef.type == CARD_DISPEL && pkt.menuChoice == 1) {
		// Apply barrier directly without opening menu
		currentAP -= cardDef.cost;

		// --- SHARED RNG CHECK ---
		// Both Host and Client must use gameplayRNG here. Also include the
		// caster's Luck (both direct and passive) so the two sides compute
		// identical results and avoid checksum desyncs.
		int rawRoll = getGameRandom(1, 20);
		int luckBonus = opponentPlayer.luck + computePassiveLuck(opponentPlayerIndex);
		int rollResult = rawRoll + luckBonus;

		opponentPlayer.barrier += rollResult;
		ofLogNotice("Dispel") << "Opponent gained " << rollResult << " barrier (Synced RNG + Luck)";

		opponentPlayer.ap = pkt.updatedAP;

		// --- HAND/DISCARD UPDATE CHECK (Condition 3) ---
		// 1. Add to played (visuals)
		opponentPlayer.playedCardsPile.push_back(cardDef);

		// 2. Handle Replicate
		applyReplicateCopyToHand(opponentPlayer, cardDef);

		// 3. Remove from Hand
		if (tempCardIndex >= 0 && tempCardIndex < (int)opponentPlayer.hand.size()) {
			opponentPlayer.hand.erase(opponentPlayer.hand.begin() + tempCardIndex);
		}

		// 4. Note: playedCardsPile moves to discardPile automatically
		// in startNewTurn / PKT_END_TURN handler.

		if (savedCurrentPlayerIndex == opponentPlayerIndex) {
			currentAP = opponentPlayer.ap;
		} else {
			currentPlayerIndex = savedCurrentPlayerIndex;
			if (currentPlayerIndex >= 0 && currentPlayerIndex < (int)players.size()) {
				currentAP = players[currentPlayerIndex].ap;
			} else {
				currentAP = savedCurrentAP;
			}
		}
		return;
	}

	// Special-case: Train menuChoice (1=AP, 2=Draft)
	if (cardDef.type == CARD_TRAIN && (pkt.menuChoice == 1 || pkt.menuChoice == 2)) {
		currentAP -= cardDef.cost;
		opponentPlayer.playedCardsPile.push_back(cardDef);
		applyReplicateCopyToHand(opponentPlayer, cardDef);
		opponentPlayer.cardsPlayedThisTurn.push_back(cardDef.type);
		opponentPlayer.hand.erase(opponentPlayer.hand.begin() + tempCardIndex);

		if (pkt.menuChoice == 1) {
			opponentPlayer.nextTurnAPBonus += 3;
			spawnFloatingText(gridToWorld(opponentPlayer.x, opponentPlayer.y), "+3 AP next turn", ofColor::yellow);
		} else {
			// --- CHANGE START ---
			// OLD:
			/*
            isInGameDraft = true;
            draftPlayerIndex = currentPlayerIndex; // This is the OPPONENT index here
            generateDraftOptions(1);
            // ...
            currentState = STATE_DRAFTING;
            */

			// NEW:
			// Do NOT open draft screen for opponent. Host handles the logic.
			// Client just shows visual feedback.
			spawnFloatingText(gridToWorld(opponentPlayer.x, opponentPlayer.y), "Training: Drafting...", ofColor::orange);
			// --- CHANGE END ---
		}

		opponentPlayer.ap = pkt.updatedAP;
		if (savedCurrentPlayerIndex == opponentPlayerIndex) {
			currentAP = opponentPlayer.ap;
		} else {
			currentPlayerIndex = savedCurrentPlayerIndex;
			if (currentPlayerIndex >= 0 && currentPlayerIndex < (int)players.size()) {
				currentAP = players[currentPlayerIndex].ap;
			} else {
				currentAP = savedCurrentAP;
			}
		}
		return;
	}

	// Special-case: Dispel purge with encoded status index (menuChoice >= 100)
	if (cardDef.type == CARD_DISPEL && pkt.menuChoice >= 100) {
		int statusIndex = pkt.menuChoice - 100;
		Player * target = nullptr;
		for (size_t i = 0; i < players.size(); i++) {
			if (players[i].x == tx && players[i].y == ty) {
				target = &players[i];
				break;
			}
		}
		if (target) {
			std::vector<std::string> statuses;
			if (target->onFire) statuses.push_back("Fire");
			if (target->isParalyzed) statuses.push_back("Paralysis");
			if (statusIndex >= 0 && statusIndex < (int)statuses.size()) {
				const std::string & status = statuses[statusIndex];
				if (status == "Fire") target->onFire = false;
				if (status == "Paralysis") {
					target->isParalyzed = false;
					target->paralysisHeadsCount = 0;
				}
			}
		}

		currentAP -= cardDef.cost;
		finishPlayCard(opponentPlayer, cardDef, tempCardIndex);
		opponentPlayer.ap = pkt.updatedAP;

		if (savedCurrentPlayerIndex == opponentPlayerIndex) {
			currentAP = opponentPlayer.ap;
		} else {
			currentPlayerIndex = savedCurrentPlayerIndex;
			if (currentPlayerIndex >= 0 && currentPlayerIndex < (int)players.size()) {
				currentAP = players[currentPlayerIndex].ap;
			} else {
				currentAP = savedCurrentAP;
			}
		}
		return;
	}

	// Special-case: Wisdom Boon with menuChoice (1=confirm)
	if (cardDef.type == CARD_WISDOM_BOON && pkt.menuChoice == 1) {
		int targetIndex = -1;
		for (size_t i = 0; i < players.size(); i++) {
			if (players[i].x == tx && players[i].y == ty) {
				targetIndex = (int)i;
				break;
			}
		}
		if (targetIndex >= 0) {
			Player * target = getPlayer(targetIndex);
			bool isSelf = (targetIndex == currentPlayerIndex);
			bool isAdjacent = target && (abs(target->x - opponentPlayer.x) + abs(target->y - opponentPlayer.y) == 1);
			if (target && (isSelf || isAdjacent)) {
				int effectValue = (int)opponentPlayer.deck.size();
				if (isSelf) {
					target->block += effectValue;
					tryTriggerShellSpike();
				} else {
					int dmg = effectValue;
					int barrierDmg = std::min(target->barrier, dmg);
					target->barrier -= barrierDmg;
					dmg -= barrierDmg;
					if (dmg > 0) {
						int wardDmg = std::min(target->ward, dmg);
						target->ward -= wardDmg;
						dmg -= wardDmg;
					}
					if (dmg > 0) target->health -= dmg;
				}
			}
		}

		currentAP -= cardDef.cost;
		opponentPlayer.playedCardsPile.push_back(cardDef);
		applyReplicateCopyToHand(opponentPlayer, cardDef);
		opponentPlayer.ap = pkt.updatedAP;
		opponentPlayer.hand.erase(opponentPlayer.hand.begin() + tempCardIndex);

		currentPlayerIndex = savedCurrentPlayerIndex;
		if (currentPlayerIndex >= 0 && currentPlayerIndex < (int)players.size()) {
			currentAP = players[currentPlayerIndex].ap;
		} else {
			currentAP = savedCurrentAP;
		}
		return;
	}

	// Special-case: Burst of Light with menuChoice (1=damage, 2=heal)
	if (cardDef.type == CARD_BURST_OF_LIGHT && (pkt.menuChoice == 1 || pkt.menuChoice == 2)) {
		int targetIndex = -1;
		for (size_t i = 0; i < players.size(); i++) {
			if (players[i].x == tx && players[i].y == ty) {
				targetIndex = (int)i;
				break;
			}
		}
		if (targetIndex >= 0) {
			Player * target = getPlayer(targetIndex);
			int casterOwner = opponentPlayer.isMinion ? opponentPlayer.ownerID : opponentPlayer.playerID;
			int targetOwner = target->isMinion ? target->ownerID : target->playerID;
			if (pkt.menuChoice == 1) {
				if (casterOwner != targetOwner) {
					applyDamageTo(*target, 3, DAMAGE_HOLY, currentPlayerIndex);
				}
			} else {
				if (casterOwner == targetOwner) {
					int healAmt = 3;
					target->health = std::min(target->maxHealth, target->health + healAmt);
				}
			}
		}

		currentAP -= cardDef.cost;
		opponentPlayer.playedCardsPile.push_back(cardDef);
		applyReplicateCopyToHand(opponentPlayer, cardDef);
		opponentPlayer.ap = pkt.updatedAP;
		opponentPlayer.hand.erase(opponentPlayer.hand.begin() + tempCardIndex);

		if (savedCurrentPlayerIndex == opponentPlayerIndex) {
			currentAP = opponentPlayer.ap;
		} else {
			currentPlayerIndex = savedCurrentPlayerIndex;
			currentAP = savedCurrentAP;
		}
		return;
	}

	// Special-case: Double Handed with menuChoice (1=Punch, 2=Hand Block)
	if (cardDef.type == CARD_DOUBLE_HANDED && (pkt.menuChoice == 1 || pkt.menuChoice == 2)) {
		int targetIndex = -1;
		for (size_t i = 0; i < players.size(); i++) {
			if (players[i].x == tx && players[i].y == ty) {
				targetIndex = (int)i;
				break;
			}
		}
		if (targetIndex >= 0) {
			currentAP -= cardDef.cost;
			opponentPlayer.playedCardsPile.push_back(cardDef);
			applyReplicateCopyToHand(opponentPlayer, cardDef);
			opponentPlayer.cardsPlayedThisTurn.push_back(cardDef.type);
			// DO NOT erase here - resolveDoubleHanded() handles card removal
			pendingDoubleHandedCardIndex = tempCardIndex;
			pendingDoubleHandedTargetIndex = targetIndex;
			resolveDoubleHanded(pkt.menuChoice == 1 ? "Punch" : "Hand Block");
		}

		opponentPlayer.ap = pkt.updatedAP;

		if (savedCurrentPlayerIndex == opponentPlayerIndex) {
			currentAP = opponentPlayer.ap;
		} else {
			currentPlayerIndex = savedCurrentPlayerIndex;
			currentAP = savedCurrentAP;
		}
		return;
	}

	// Special-case: Teleport (apply move from packet)
	if (cardDef.type == CARD_TELEPORT) {
		// Burn teleport dice RNG so both machines consume the same dice calls
		for (int _ri = 0; _ri < cardDef.numDice; ++_ri) {
			(void)getGameRandom(1, cardDef.diceSides);
		}
		// Track the card play
		currentAP -= cardDef.cost;
		opponentPlayer.playedCardsPile.push_back(cardDef);
		applyReplicateCopyToHand(opponentPlayer, cardDef);
		opponentPlayer.cardsPlayedThisTurn.push_back(cardDef.type);

		// Move player
		board[opponentPlayer.x][opponentPlayer.y].hasPlayer = false;
		opponentPlayer.x = tx;
		opponentPlayer.y = ty;
		board[tx][ty].hasPlayer = true;
		playerVisualPos = gridToWorld(tx, ty);
		invalidateTargetCache();

		opponentPlayer.hand.erase(opponentPlayer.hand.begin() + tempCardIndex);
		opponentPlayer.ap = pkt.updatedAP;
		currentPlayerIndex = savedCurrentPlayerIndex;
		currentAP = savedCurrentAP;
		return;
	}

	// NOTE: Chain Lightning and Summon Faerie special-case intercepts removed.
	// These were previously short-circuiting execution and bypassing `playCard()`.
	// `playCard()` is authoritative for those effects; keep CARD_TELEPORT special-case only.

	// Special-case: Renewed Inspiration (menu already resolved on sender)
	if (cardDef.type == CARD_RENEWED_INSPIRATION) {
		currentAP -= cardDef.cost;
		opponentPlayer.playedCardsPile.push_back(cardDef);
		if (opponentPlayer.isReplicatePending) {
			// Create a replicated copy and add it to hand (matching local behavior)
			Card copy = cardDef;
			copy.isCopied = true;
			opponentPlayer.hand.push_back(copy);
			opponentPlayer.hand.back().currentScale = opponentPlayer.hand.back().targetScale = 1.5f;
			opponentPlayer.isReplicatePending = (copy.type == CARD_REPLICATE);
		}
		opponentPlayer.cardsPlayedThisTurn.push_back(cardDef.type);
		// Remove the card from the opponent's hand if present. If we added a temporary
		// card just above, this will remove that temporary entry as well.
		if (tempCardIndex >= 0 && tempCardIndex < (int)opponentPlayer.hand.size()) {
			opponentPlayer.hand.erase(opponentPlayer.hand.begin() + tempCardIndex);
		}
		createCardDisplay(cardDef, opponentPlayerIndex);
		opponentPlayer.ap = pkt.updatedAP;
		currentPlayerIndex = savedCurrentPlayerIndex;
		currentAP = savedCurrentAP;
		return;
	}

	// --- CHANGE START: DELETE THE SKIP LOGIC ---
	// We want to execute playCard() for EVERYTHING, including dice cards.
	/*
    if (cardDef.type == CARD_RAISE_DEAD || ... ) {
        // ... code that skips playCard ...
        return;
    }
    */
	// --- CHANGE END ---

	// ADD FAILSAFE BEFORE playCard() TO AVOID OPPONENT MENU-CARD FALL-THROUGH UI SOFTLOCK
	if (cardDef.type == CARD_WISDOM_BOON || cardDef.type == CARD_BURST_OF_LIGHT || cardDef.type == CARD_DOUBLE_HANDED || cardDef.type == CARD_GIANT_MAGIC_HAND || cardDef.type == CARD_DISPEL || cardDef.type == CARD_TRAIN) {
		ofLogError("Network") << "Failsafe: Opponent menu card fell through! Aborting to prevent UI softlock.";
		currentPlayerIndex = savedCurrentPlayerIndex;
		currentAP = savedCurrentAP;
		return;
	}

	// Execute the card play using the normal playCard logic
	CardPlayResult result = playCard(tempCardIndex, tx, ty);

	ofLogNotice("Network") << "executeOpponentCardPlay: After playCard result=" << result << " Hand size=" << opponentPlayer.hand.size() << " Played pile size=" << opponentPlayer.playedCardsPile.size();

	if (result == CARD_NOT_PLAYABLE) {
		ofLogError("Network") << "Opponent playCard failed locally! Sync issue likely.";
		// Force cleanup since playCard didn't consume it.
		// Be defensive: only erase if the card at tempCardIndex still matches
		// the expected card name. Otherwise search for the named card and remove
		// the first matching instance to avoid deleting an unrelated card.
		if (tempCardIndex >= 0) {
			if (tempCardIndex < (int)opponentPlayer.hand.size() && opponentPlayer.hand[tempCardIndex].name == cardName) {
				opponentPlayer.hand.erase(opponentPlayer.hand.begin() + tempCardIndex);
			} else {
				bool erased = false;
				for (size_t i = 0; i < opponentPlayer.hand.size(); ++i) {
					if (opponentPlayer.hand[i].name == cardName) {
						opponentPlayer.hand.erase(opponentPlayer.hand.begin() + i);
						erased = true;
						break;
					}
				}
				if (!erased) {
					ofLogNotice("Network") << "Cleanup: expected card '" << cardName << "' not found in opponent hand; nothing erased.";
				}
			}
		}
	} else {
		// playCard succeeded. It consumed the AP and removed the card from hand.
		// Use the AP value sent by the opponent (includes any AP bonuses like Sprint)
		opponentPlayer.ap = pkt.updatedAP;
	}

	// Restore current player context
	if (savedCurrentPlayerIndex == opponentPlayerIndex) {
		// If it was the opponent's turn, keep the AP value that resulted from the play
		currentAP = opponentPlayer.ap;
	} else {
		currentPlayerIndex = savedCurrentPlayerIndex;
		currentAP = savedCurrentAP;
	}
}

// Verify sync
long long ofApp::calculateChecksum() {
	// FNV-1a 64-bit
	const uint64_t FNV_OFFSET = 14695981039346656037ULL;
	const uint64_t FNV_PRIME = 1099511628211ULL;
	uint64_t h = FNV_OFFSET;
	auto mix = [&](uint64_t v) {
		h ^= v;
		h *= FNV_PRIME;
	};

	// Global counters
	mix((uint64_t)globalTurnCounter);
	mix((uint64_t)currentPlayerIndex);

	// Player state (only shared state - decks differ per player)
	for (const auto & p : players) {
		mix((uint64_t)p.playerID);
		mix((uint64_t)p.x);
		mix((uint64_t)p.y);
		mix((uint64_t)p.health);
		mix((uint64_t)p.maxHealth);
		mix((uint64_t)p.block);
		mix((uint64_t)p.ward);
		mix((uint64_t)p.fortification);
		mix((uint64_t)p.barrier);
		mix((uint64_t)p.holyBlock);
		mix((uint64_t)p.luck);
		mix((uint64_t)p.bonusTurns);
		mix((uint64_t)p.ap);
		mix((uint64_t)p.onFire);
		mix((uint64_t)p.isParalyzed);
		mix((uint64_t)p.paralysisHeadsCount);
		mix((uint64_t)p.isPoisoned);
		mix((uint64_t)p.poisonReduction);
		mix((uint64_t)p.nextTurnAPBonus);
		mix((uint64_t)p.nextAttackAddPoison);
		mix((uint64_t)p.nextTurnD10AP);
		mix((uint64_t)p.nextTurnExtraDraw);
		mix((uint64_t)p.isReplicatePending);
		mix((uint64_t)p.nextTurnBonusDiceFromMinions);
		mix((uint64_t)p.strengthenElementsTurnsRemaining);
		mix((uint64_t)p.sleepTurnsRemaining);
		mix((uint64_t)p.summonedOnTurnCycle);
		mix((uint64_t)p.inTortoiseForm);
		mix((uint64_t)p.tortoiseDamageTaken);
		mix((uint64_t)p.inGhostForm);
		mix((uint64_t)p.ghostDamageTaken);
		mix((uint64_t)p.freeKickTurns);

		// NOTE: We do NOT include deck/discard/hand sizes in checksum because:
		// 1. Network packet timing causes desyncs (DrawCards packets arrive after checksum)
		// 2. Opponent's deck/hand are hidden information anyway
		// 3. Cards are synchronized via explicit DrawCards/PlayCard packets
	}

	// NOTE: Do NOT include visual/timing-dependent arrays (like activeDiceRolls)
	// in the deterministic checksum. Dice are removed based on real-world
	// elapsed time and would cause non-deterministic checksum mismatches.
	// The authoritative game state is represented by `players`, `board`, and
	// `currentAP`, which are already included above.

	return (long long)h;
}
//--------------------------------------------------------------
void ofApp::applyMovement(int playerIndex, int targetX, int targetY, int newAP, const std::vector<glm::vec2> * pathOverride) {
	if (playerIndex < 0 || playerIndex >= (int)players.size()) return;
	Player & p = players[playerIndex];
	if (targetX < 0 || targetX >= BOARD_WIDTH || targetY < 0 || targetY >= BOARD_HEIGHT) return;

	const int prevX = p.x;
	const int prevY = p.y;

	// Log the movement
	addGameLog(getPlayerSteamName(playerIndex) + " moved to (" + ofToString(targetX) + "," + ofToString(targetY) + ")");

	board[prevX][prevY].hasPlayer = false;

	if (newAP >= 0) {
		ofLogNotice("APDebug") << "applyMovement: playerIndex=" << playerIndex << " prev_currentAP=" << currentAP << " newAP=" << newAP << " p.ap(before)=" << p.ap;
		currentAP = newAP;
		p.ap = newAP;
		ofLogNotice("APDebug") << "applyMovement: p.ap(after)=" << p.ap << " currentAP(after)=" << currentAP;
	}

	// Build animation path
	animationPath.clear();
	currentPathIndex = 0;
	glm::vec3 startPos = gridToWorld(prevX, prevY);
	glm::vec3 endPos = gridToWorld(targetX, targetY);
	playerVisualPos = startPos;
	animationPath.push_back(startPos);

	if (pathOverride && pathOverride->size() > 1) {
		for (size_t i = 1; i < pathOverride->size(); ++i) {
			animationPath.push_back(gridToWorld((int)(*pathOverride)[i].x, (int)(*pathOverride)[i].y));
		}
	} else {
		std::vector<glm::vec2> path = findShortestPathForPlayer(playerIndex, { (float)prevX, (float)prevY }, { (float)targetX, (float)targetY });
		if (path.size() > 1) {
			for (size_t i = 1; i < path.size(); ++i) {
				animationPath.push_back(gridToWorld((int)path[i].x, (int)path[i].y));
			}
		} else {
			animationPath.push_back(endPos);
		}
	}

	if (!animationPath.empty()) {
		isPlayerAnimating = true;
		animatingPlayerIndex = playerIndex;
	}

	board[targetX][targetY].hasPlayer = true;
	p.x = targetX;
	p.y = targetY;

	// Clear the enteredWallByClick flag if the player is no longer inside a wall
	if (!board[targetX][targetY].hasWall) {
		p.enteredWallByClick = false;
	}

	invalidateTargetCache();
}
//--------------------------------------------------------------
// Anti-cheat: Get deck state as string for logging
std::string ofApp::getDeckStateString(const Player & p) {
	std::string result = "Player" + std::to_string(p.playerID) + " Deck[" + std::to_string(p.deck.size()) + "]: ";
	for (size_t i = 0; i < p.deck.size(); ++i) {
		if (i > 0) result += ", ";
		result += p.deck[i].name + "(" + std::to_string((int)p.deck[i].type) + ")";
	}
	result += " | Hand[" + std::to_string(p.hand.size()) + "]: ";
	for (size_t i = 0; i < p.hand.size(); ++i) {
		if (i > 0) result += ", ";
		result += p.hand[i].name + "(" + std::to_string((int)p.hand[i].type) + ")";
	}
	result += " | Discard[" + std::to_string(p.discardPile.size()) + "]: ";
	for (size_t i = 0; i < p.discardPile.size(); ++i) {
		if (i > 0) result += ", ";
		result += p.discardPile[i].name + "(" + std::to_string((int)p.discardPile[i].type) + ")";
	}
	return result;
}
//--------------------------------------------------------------
// Anti-cheat: Log all player deck states to file and console
void ofApp::logDeckStates(const std::string & reason) {
	std::string timestamp = ofGetTimestampString("%Y-%m-%d %H:%M:%S");
	std::string logEntry = "\n=== DECK STATE LOG ===\n";
	logEntry += "Time: " + timestamp + "\n";
	logEntry += "Reason: " + reason + "\n";
	logEntry += "Turn: " + std::to_string(globalTurnCounter) + "\n";
	logEntry += "Current Player: " + std::to_string(currentPlayerIndex) + "\n";
	logEntry += "Local Player ID: " + std::to_string(myLocalPlayerID) + "\n";
	logEntry += "Is Host: " + std::string(steamManager.isHost() ? "true" : "false") + "\n\n";

	for (const auto & p : players) {
		logEntry += getDeckStateString(p) + "\n";
	}
	logEntry += "=====================\n";

	// Log to console
	ofLogNotice("DeckState") << logEntry;

	// Append to file
	std::string filename = "deck_states_" + std::string(steamManager.isHost() ? "host" : "client") + ".log";
	ofBuffer buffer;
	buffer.set(logEntry.c_str(), logEntry.size());

#pragma GCC diagnostic pop

	ofBufferToFile(filename, buffer, true); // true = append mode
}
